/* Conversaciones de listening.html (2, 3 y 4 personas, A1–B2). Generado por scripts/conversaciones/construir.py.
   lineas: [persona, inglés, español]. Audio: listening/conversaciones/{id}-{i}.mp3 */
window.LISTENING_CONVERSACIONES = [{"id":"va1-01","nivel":"A1","emoji":"🙋","titulo":"Meeting Someone New","tituloEs":"Conociendo a alguien nuevo","personas":[{"nombre":"Victor","genero":"hombre","rol":"estudiante nuevo"},{"nombre":"Chloe","genero":"mujer","rol":"estudiante"}],"lineas":[[0,"Hello. I'm Victor. What's your name?","Hola. Soy Victor. ¿Cómo te llamas?"],[1,"Hi, Victor. I'm Chloe. Nice to meet you.","Hola, Victor. Soy Chloe. Encantada de conocerte."],[0,"Nice to meet you too. Are you a new student?","Encantado de conocerte también. ¿Eres una estudiante nueva?"],[1,"No, I'm not. Are you new here?","No, no lo soy. ¿Tú eres nuevo aquí?"],[0,"Yes, I am. Today is my first day.","Sí, lo soy. Hoy es mi primer día."],[1,"Oh, welcome! I like this school.","¡Oh, bienvenido! Me gusta esta escuela."],[0,"Good. I am happy to be here.","Qué bueno. Estoy feliz de estar aquí."],[1,"I can help you if you want.","Puedo ayudarte si quieres."],[0,"Oh, thank you! That is very nice.","¡Oh, gracias! Eso es muy amable."],[1,"No problem. See you in class!","De nada. ¡Nos vemos en clase!"]]},{"id":"va1-02","nivel":"A1","emoji":"🏫","titulo":"Meeting New Classmates","tituloEs":"Conociendo a los compañeros","personas":[{"nombre":"Linda","genero":"mujer","rol":"Estudiante"},{"nombre":"Caleb","genero":"hombre","rol":"Estudiante"},{"nombre":"Abby","genero":"mujer","rol":"Estudiante"}],"lineas":[[0,"Hi! I'm Linda. What's your name?","¡Hola! Soy Linda. ¿Cómo te llamas?"],[1,"Hello. I'm Caleb. It's nice to meet you.","Hola. Soy Caleb. Encantado de conocerte."],[2,"Hi, I'm Abby. Nice to meet you too.","Hola, soy Abby. Encantada de conocerlos también."],[0,"Are you new students?","¿Son estudiantes nuevos?"],[1,"Yes, I am. This is my first class.","Sí, lo soy. Esta es mi primera clase."],[2,"Me too! I'm a little nervous.","¡Yo también! Estoy un poco nerviosa."],[0,"Don't be nervous. The teacher is nice.","No estés nerviosa. La profesora es simpática."],[1,"Good! I like English class.","¡Qué bueno! Me gusta la clase de inglés."],[2,"I like it too. Do you like coffee?","A mí también me gusta. ¿Les gusta el café?"],[0,"Yes, I love coffee!","¡Sí, me encanta el café!"],[1,"Let's get coffee after class.","Tomemos un café después de la clase."],[2,"Great idea!","¡Gran idea!"]]},{"id":"va1-03","nivel":"A1","emoji":"☕","titulo":"Ordering a Coffee","tituloEs":"Pedir un café","personas":[{"nombre":"Tasha","genero":"mujer","rol":"barista"},{"nombre":"Josh","genero":"hombre","rol":"cliente"}],"lineas":[[0,"Hi! What can I get for you?","¡Hola! ¿En qué te puedo ayudar?"],[1,"Hi. I want a coffee, please.","Hola. Quiero un café, por favor."],[0,"Okay. A small coffee or a large coffee?","Ok. ¿Un café chico o un café grande?"],[1,"A large coffee. A very large coffee.","Un café grande. Un café muy grande."],[0,"Okay! One large coffee. With milk?","¡Ok! Un café grande. ¿Con leche?"],[1,"No, just black coffee. Thank you.","No, solo café negro. Gracias."],[0,"Alright. That's three dollars.","Muy bien. Son tres dólares."],[1,"Okay. Here you are.","Ok. Aquí tienes."],[0,"Thank you. Your coffee is ready.","Gracias. Tu café está listo."],[1,"Great, thanks! Have a good day.","¡Genial, gracias! Que tengas un buen día."],[0,"You too! Enjoy.","¡Tú también! Que lo disfrutes."]]},{"id":"va1-04","nivel":"A1","emoji":"🍻","titulo":"Ordering Drinks at a Bar","tituloEs":"Pidiendo bebidas en un bar","personas":[{"nombre":"Olivia","genero":"mujer","rol":"Amiga del grupo"},{"nombre":"Nate","genero":"hombre","rol":"Amigo del grupo"},{"nombre":"Andre","genero":"hombre","rol":"Amigo del grupo"},{"nombre":"Linda","genero":"mujer","rol":"Amiga del grupo"}],"lineas":[[0,"Okay, what does everyone want to drink?","Bueno, ¿qué quieren tomar todos?"],[1,"I want a beer, please.","Yo quiero una cerveza, por favor."],[2,"A soda for me. I'm very thirsty.","Un refresco para mí. Tengo mucha sed."],[3,"Hmm, I'm not sure. What's good here?","Mmm, no estoy segura. ¿Qué es bueno aquí?"],[0,"The apple juice is really good.","El jugo de manzana es muy rico."],[1,"A big beer for me!","¡Una cerveza grande para mí!"],[2,"Haha, okay. One beer, one soda...","Jaja, ok. Una cerveza, un refresco..."],[3,"And an apple juice. Good idea!","Y un jugo de manzana. ¡Buena idea!"],[0,"Great! And I just want a water.","¡Genial! Y yo solo quiero un agua."],[1,"Perfect. We are a thirsty group!","Perfecto. ¡Somos un grupo sediento!"],[2,"Yes! Let's order now.","¡Sí! Pidamos ahora."],[3,"I'm happy. This is fun.","Estoy feliz. Esto es divertido."]]},{"id":"va1-05","nivel":"A1","emoji":"🗺️","titulo":"Where is the park?","tituloEs":"¿Dónde está el parque?","personas":[{"nombre":"Chloe","genero":"mujer","rol":"turista"},{"nombre":"Ray","genero":"hombre","rol":"residente local"}],"lineas":[[0,"Excuse me. Can you help me?","Disculpe. ¿Puede ayudarme?"],[1,"Sure. What do you need?","Claro. ¿Qué necesita?"],[0,"I want to go to the park.","Quiero ir al parque."],[1,"The park? Oh, it's very close.","El parque... Ah, está muy cerca."],[0,"Great! Where is it?","¡Genial! ¿Dónde está?"],[1,"Go straight. The park is on the right.","Siga derecho. El parque está a la derecha."],[0,"Straight, and on the right. Okay.","Derecho, y a la derecha. Okay."],[1,"Yes, it's very big. You can't miss it.","Sí, es muy grande. No tiene pierde."],[0,"Perfect. Thank you so much!","Perfecto. ¡Muchas gracias!"],[1,"You're welcome. Have a good day!","De nada. ¡Que tenga un buen día!"]]},{"id":"va1-06","nivel":"A1","emoji":"🍎","titulo":"Buying Fruit at the Market","tituloEs":"Comprando fruta en el mercado","personas":[{"nombre":"Kayla","genero":"mujer","rol":"clienta"},{"nombre":"Zach","genero":"hombre","rol":"vendedor"}],"lineas":[[0,"Hello. I want some fruit.","Hola. Quiero un poco de fruta."],[1,"Hi! We have good apples today.","¡Hola! Hoy tenemos buenas manzanas."],[0,"Oh, good! I like apples. Are they red?","¡Oh, qué bien! Me gustan las manzanas. ¿Son rojas?"],[1,"Yes. We have red apples and green apples.","Sí. Tenemos manzanas rojas y manzanas verdes."],[0,"Okay. I want four red apples, please.","Vale. Quiero cuatro manzanas rojas, por favor."],[1,"Four red apples. Anything else?","Cuatro manzanas rojas. ¿Algo más?"],[0,"No, thank you. How much is it?","No, gracias. ¿Cuánto es?"],[1,"It's three dollars.","Son tres dólares."],[0,"Okay. Here you are.","Vale. Aquí tienes."],[1,"Thank you. Enjoy the apples!","Gracias. ¡Que disfrutes las manzanas!"]]},{"id":"va1-07","nivel":"A1","emoji":"👨‍👩‍👧","titulo":"Looking at a Family Photo","tituloEs":"Mirando una foto familiar","personas":[{"nombre":"Luis","genero":"hombre","rol":"amigo de Chloe"},{"nombre":"Chloe","genero":"mujer","rol":"amiga de Luis"}],"lineas":[[0,"Look at this photo, Chloe.","Mira esta foto, Chloe."],[1,"Oh, is this your family?","Oh, ¿esta es tu familia?"],[0,"Yes. This is my mother and my father.","Sí. Esta es mi mamá y mi papá."],[1,"They look very happy. Who is she?","Se ven muy felices. ¿Quién es ella?"],[0,"That's my little sister. Her name is Sofia.","Esa es mi hermana pequeña. Su nombre es Sofía."],[1,"She's very cute! And the dog?","¡Es muy linda! ¿Y el perro?"],[0,"That's our dog, Rocky. He likes to play.","Ese es nuestro perro, Rocky. Le gusta jugar."],[1,"I like your dog! It's a very nice photo.","¡Me gusta tu perro! Es una foto muy bonita."],[0,"Thank you. I like it a lot.","Gracias. Me gusta mucho."],[1,"Your family is beautiful, Luis.","Tu familia es hermosa, Luis."]]},{"id":"va1-08","nivel":"A1","emoji":"🏨","titulo":"Checking Into a Hotel","tituloEs":"Registrarse en un hotel","personas":[{"nombre":"Justin","genero":"hombre","rol":"Recepcionista"},{"nombre":"Vanessa","genero":"mujer","rol":"Huésped del hotel"}],"lineas":[[0,"Hello! Welcome. How can I help you?","¡Hola! Bienvenida. ¿Cómo puedo ayudarla?"],[1,"Hi. I have a reservation.","Hola. Tengo una reservación."],[0,"Okay. What's your name, please?","De acuerdo. ¿Cuál es su nombre, por favor?"],[1,"My name is Vanessa Morales.","Mi nombre es Vanessa Morales."],[0,"Morales... yes! Here you are.","Morales... ¡sí! Aquí está."],[1,"Great! Is my room ready?","¡Genial! ¿Está lista mi habitación?"],[0,"Yes, it is. Here is your key card.","Sí, lo está. Aquí tiene su tarjeta de acceso."],[1,"Thank you. What's the room number?","Gracias. ¿Cuál es el número de la habitación?"],[0,"It's room 402. It has a great view!","Es la habitación 402. ¡Tiene una vista genial!"],[1,"Oh, wonderful! Thanks so much.","¡Oh, maravilloso! Muchísimas gracias."],[0,"You're welcome. Enjoy your stay!","De nada. ¡Disfrute su estancia!"]]},{"id":"va1-09","nivel":"A1","emoji":"🍝","titulo":"Ordering Food","tituloEs":"Pidiendo comida","personas":[{"nombre":"Natalie","genero":"mujer","rol":"cliente"},{"nombre":"Noah","genero":"hombre","rol":"cliente"},{"nombre":"Tasha","genero":"mujer","rol":"mesera"}],"lineas":[[0,"I'm so hungry. What do you want?","Tengo mucha hambre. ¿Tú qué quieres?"],[1,"I want a big hamburger.","Yo quiero una hamburguesa grande."],[2,"Hello! Are you ready to order?","¡Hola! ¿Están listos para ordenar?"],[0,"Yes. I'd like a salad, please.","Sí. Quisiera una ensalada, por favor."],[1,"And I want the hamburger with fries.","Y yo quiero la hamburguesa con papas fritas."],[2,"Okay. A salad and a hamburger. Anything to drink?","Ok. Una ensalada y una hamburguesa. ¿Algo para tomar?"],[0,"I'd like a water.","Quisiera un agua."],[1,"A soda for me, please.","Una gaseosa para mí, por favor."],[2,"Great. One water and one soda.","Genial. Un agua y una gaseosa."],[0,"Thank you!","¡Gracias!"],[1,"Yes, thank you very much.","Sí, muchas gracias."],[2,"You're welcome. Your food is coming soon.","De nada. Su comida ya casi llega."]]},{"id":"va1-10","nivel":"A1","emoji":"🌦️","titulo":"The Weather Today","tituloEs":"El clima de hoy","personas":[{"nombre":"Carlos","genero":"hombre","rol":"amigo"},{"nombre":"Ella","genero":"mujer","rol":"amiga"}],"lineas":[[0,"Brr! It's very cold today.","¡Brr! Hace mucho frío hoy."],[1,"Yes, it is. I don't like the cold.","Sí, lo está. No me gusta el frío."],[0,"Me neither. And the sky is gray.","A mí tampoco. Y el cielo está gris."],[1,"I like sunny days.","Me gustan los días soleados."],[0,"Me too. I love the sun.","Yo también. Me encanta el sol."],[1,"Do you think it will rain?","¿Crees que va a llover?"],[0,"Maybe. I see some dark clouds.","Quizás. Veo algunas nubes oscuras."],[1,"I hope not. I don't have an umbrella.","Espero que no. No tengo paraguas."],[0,"Well, I want a hot chocolate.","Bueno, yo quiero un chocolate caliente."],[1,"That's a great idea! Me too.","¡Es una gran idea! Yo también."]]},{"id":"va1-11","nivel":"A1","emoji":"👕","titulo":"Shopping for a Hat","tituloEs":"Comprando un sombrero","personas":[{"nombre":"Mason","genero":"hombre","rol":"Amigo de Nora"},{"nombre":"Nora","genero":"mujer","rol":"Amiga de Mason"},{"nombre":"Abby","genero":"mujer","rol":"Empleada de la tienda"}],"lineas":[[0,"Wow, I like this blue shirt.","Wow, me gusta esta camisa azul."],[1,"It's nice. I want a new hat.","Es bonita. Quiero un sombrero nuevo."],[2,"Hello. Can I help you?","Hola. ¿Puedo ayudarlos?"],[0,"Yes, please. Where are the hats?","Sí, por favor. ¿Dónde están los sombreros?"],[2,"The hats are over there.","Los sombreros están por allá."],[1,"Oh, I see them. I like the red hat.","Oh, los veo. Me gusta el sombrero rojo."],[0,"The red hat is very big!","¡El sombrero rojo es muy grande!"],[1,"Haha, yes. It's funny.","Jaja, sí. Es gracioso."],[2,"We have small hats, too.","Tenemos sombreros pequeños también."],[0,"Great! Thank you for your help.","¡Genial! Gracias por su ayuda."]]},{"id":"va1-12","nivel":"A1","emoji":"📞","titulo":"An Invitation to the Park","tituloEs":"Una invitación al parque","personas":[{"nombre":"Owen","genero":"hombre","rol":"amigo que llama"},{"nombre":"Emma","genero":"mujer","rol":"amiga que recibe la llamada"}],"lineas":[[0,"Hi Emma, it's Owen. How are you?","Hola Emma, soy Owen. ¿Cómo estás?"],[1,"Hi Owen! I'm good, thanks. And you?","¡Hola Owen! Estoy bien, gracias. ¿Y tú?"],[0,"I'm good. I want to go to the park.","Estoy bien. Quiero ir al parque."],[1,"The park? That sounds nice. When?","¿El parque? Suena bien. ¿Cuándo?"],[0,"On Saturday. Can you go?","El sábado. ¿Puedes ir?"],[1,"Yes, I can! I like the park.","¡Sí, puedo! Me gusta el parque."],[0,"Great! At two o'clock?","¡Genial! ¿A las dos en punto?"],[1,"Perfect. See you on Saturday.","Perfecto. Nos vemos el sábado."],[0,"Okay, great. Bye!","Vale, genial. ¡Chao!"],[1,"Bye, Owen!","¡Chao, Owen!"]]},{"id":"va1-13","nivel":"A1","emoji":"🩺","titulo":"I Feel Sick","tituloEs":"Me siento mal","personas":[{"nombre":"Nora","genero":"mujer","rol":"amiga de Danny"},{"nombre":"Danny","genero":"hombre","rol":"paciente"}],"lineas":[[0,"How do you feel, Danny?","¿Cómo te sientes, Danny?"],[1,"I feel bad. I'm very cold.","Me siento mal. Tengo mucho frío."],[0,"Oh, no. Do you want my jacket?","Oh, no. ¿Quieres mi chaqueta?"],[1,"Yes, please. Thank you.","Sí, por favor. Gracias."],[0,"Here you are. Are you hungry?","Aquí tienes. ¿Tienes hambre?"],[1,"No, I'm not. I want some water.","No, no tengo. Quiero un poco de agua."],[0,"Okay. I have water for you.","Vale. Tengo agua para ti."],[1,"Thank you. You are very kind.","Gracias. Eres muy amable."],[0,"You're welcome. Oh, the doctor is here.","De nada. Oh, el doctor está aquí."],[1,"Good. I want to go home.","Qué bien. Quiero ir a casa."]]},{"id":"va1-14","nivel":"A1","emoji":"⏰","titulo":"Morning Routines","tituloEs":"Rutinas de la mañana","personas":[{"nombre":"Lily","genero":"mujer","rol":"Amiga de Jordan"},{"nombre":"Jordan","genero":"hombre","rol":"Amigo de Lily"}],"lineas":[[0,"Hi Jordan! You look tired.","¡Hola, Jordan! Te ves cansado."],[1,"Hi Lily. I am. I don't like mornings.","Hola, Lily. Lo estoy. No me gustan las mañanas."],[0,"What time do you wake up?","¿A qué hora te despiertas?"],[1,"I wake up at nine o'clock.","Me despierto a las nueve en punto."],[0,"Wow, that's late! I wake up at seven.","¡Guau, es tarde! Yo me despierto a las siete."],[1,"I like my sleep. Do you eat a big breakfast?","Me gusta dormir. ¿Comes un gran desayuno?"],[0,"I eat toast and an egg. And you?","Yo como pan tostado y un huevo. ¿Y tú?"],[1,"I just drink coffee. No food.","Yo solo tomo café. Nada de comida."],[0,"Jordan, coffee is not breakfast!","¡Jordan, el café no es el desayuno!"],[1,"I know! It's my coffee breakfast.","¡Lo sé! Es mi desayuno de café."]]},{"id":"va1-15","nivel":"A1","emoji":"🎂","titulo":"A Fun Birthday Party","tituloEs":"Una Fiesta de Cumpleaños Divertida","personas":[{"nombre":"Nate","genero":"hombre","rol":"invitado"},{"nombre":"Maya","genero":"mujer","rol":"invitada"},{"nombre":"Amber","genero":"mujer","rol":"invitada"},{"nombre":"Danny","genero":"hombre","rol":"invitado"}],"lineas":[[0,"Wow, this party is fun.","Vaya, esta fiesta es divertida."],[1,"Yes! I like the music.","¡Sí! Me gusta la música."],[2,"And the cake looks good.","Y el pastel se ve bueno."],[3,"I'm hungry. I want cake now.","Tengo hambre. Quiero pastel ahora."],[0,"Me too. Do you want juice?","Yo también. ¿Quieres jugo?"],[1,"Yes, please. Thank you, Nate.","Sí, por favor. Gracias, Nate."],[2,"Oh, I like this song!","¡Oh, me gusta esta canción!"],[3,"Let's dance!","¡Bailemos!"],[0,"I can't dance. It's okay.","No sé bailar. No pasa nada."],[1,"Haha, it's easy! Come on!","¡Jaja, es fácil! ¡Vamos!"]]},{"id":"va1-16","nivel":"A1","emoji":"🐶","titulo":"Talking About Pets","tituloEs":"Hablando de mascotas","personas":[{"nombre":"Marcus","genero":"hombre","rol":"amigo"},{"nombre":"Abby","genero":"mujer","rol":"amiga"},{"nombre":"Lauren","genero":"mujer","rol":"amiga"}],"lineas":[[0,"I have a new pet.","Tengo una mascota nueva."],[1,"Oh, really? What is it?","Ah, ¿en serio? ¿Qué es?"],[2,"Is it a dog?","¿Es un perro?"],[0,"No, it's a cat. It's very small.","No, es un gato. Es muy pequeño."],[1,"Aww, I love cats!","¡Ay, me encantan los gatos!"],[2,"What is its name?","¿Cuál es su nombre?"],[0,"His name is Leo.","Su nombre es Leo."],[1,"Lauren, do you have a pet?","Lauren, ¿tú tienes una mascota?"],[2,"Yes, I have a big dog.","Sí, tengo un perro grande."],[0,"Cool! I like dogs too.","¡Genial! A mí también me gustan los perros."]]},{"id":"va1-17","nivel":"A1","emoji":"🚕","titulo":"Let's Get a Taxi","tituloEs":"Tomemos un taxi","personas":[{"nombre":"Zoe","genero":"mujer","rol":"amiga de Eli"},{"nombre":"Eli","genero":"hombre","rol":"amigo de Zoe"}],"lineas":[[0,"I'm tired. I want to take a taxi.","Estoy cansada. Quiero tomar un taxi."],[1,"Me too. A taxi is a good idea.","Yo también. Un taxi es una buena idea."],[0,"Okay. Where is a taxi?","Vale. ¿Dónde hay un taxi?"],[1,"Hmm, I don't see one.","Mmm, no veo ninguno."],[0,"Oh wait! Look over there!","¡Oh, espera! ¡Mira para allá!"],[1,"A yellow taxi! Perfect. Taxi!","¡Un taxi amarillo! Perfecto. ¡Taxi!"],[0,"Yay! We can go to our hotel.","¡Yupi! Podemos ir a nuestro hotel."],[1,"Yes, The Grand Hotel.","Sí, el Grand Hotel."],[0,"Do you have the address?","¿Tienes la dirección?"],[1,"Yes, it's on my phone. No problem.","Sí, está en mi teléfono. No hay problema."]]},{"id":"va1-18","nivel":"A1","emoji":"📅","titulo":"Weekend Plans","tituloEs":"Planes para el fin de semana","personas":[{"nombre":"Megan","genero":"mujer","rol":"amiga"},{"nombre":"Kyle","genero":"hombre","rol":"amigo"},{"nombre":"Derek","genero":"hombre","rol":"amigo"}],"lineas":[[0,"Hi guys! What are your plans for the weekend?","¡Hola chicos! ¿Qué planes tienen para el fin de semana?"],[1,"I want to go to the park. I like the park.","Quiero ir al parque. Me gusta el parque."],[2,"I want to sleep. I'm very tired.","Yo quiero dormir. Estoy muy cansado."],[0,"The park is a good idea. Derek, do you want to go?","El parque es una buena idea. Derek, ¿quieres ir?"],[1,"Yes, come with us. It's fun!","Sí, ven con nosotros. ¡Es divertido!"],[2,"I don't know. I really like my bed.","No sé. Me gusta mucho mi cama."],[0,"We can eat ice cream in the park.","Podemos comer helado en el parque."],[1,"Oh, yes! I love ice cream.","¡Oh, sí! Me encanta el helado."],[2,"Ice cream? Okay, I can go.","¿Helado? Está bien, puedo ir."],[0,"Great! See you on Saturday.","¡Genial! Nos vemos el sábado."]]},{"id":"va1-19","nivel":"A1","emoji":"🛒","titulo":"At the Checkout Counter","tituloEs":"En la caja","personas":[{"nombre":"Caleb","genero":"hombre","rol":"cliente"},{"nombre":"Hannah","genero":"mujer","rol":"cajera"}],"lineas":[[0,"Hello there.","Hola."],[1,"Hi. Oh, I love this chocolate!","Hola. ¡Oh, me encanta este chocolate!"],[0,"Yes, it's my favorite.","Sí, es mi favorito."],[1,"It's very good. Is this all for you?","Es muy bueno. ¿Es esto todo?"],[0,"Yes, just this.","Sí, solo esto."],[1,"Okay. Your total is eight dollars.","Ok. Su total es ocho dólares."],[0,"Can I pay with a card?","¿Puedo pagar con tarjeta?"],[1,"Yes, of course. You can insert it here.","Sí, claro. Puede insertarla aquí."],[0,"Great. Thank you.","Genial. Gracias."],[1,"You're welcome. Have a nice day!","De nada. ¡Que tenga un buen día!"],[0,"Thanks, you too!","¡Gracias, igualmente!"]]},{"id":"va1-20","nivel":"A1","emoji":"🏠","titulo":"Meeting a New Neighbor","tituloEs":"Conociendo a un vecino nuevo","personas":[{"nombre":"Andre","genero":"hombre","rol":"Vecino nuevo"},{"nombre":"Denise","genero":"mujer","rol":"Vecina"},{"nombre":"Rosa","genero":"mujer","rol":"Amiga de Denise"}],"lineas":[[0,"Hello! I'm Andre. I'm a new neighbor.","¡Hola! Soy Andre. Soy un vecino nuevo."],[1,"Oh, hi Andre! I'm Denise. Welcome!","¡Oh, hola Andre! Soy Denise. ¡Bienvenido!"],[2,"And I'm Rosa. Nice to meet you.","Y yo soy Rosa. Mucho gusto en conocerte."],[0,"Nice to meet you too. I like this building.","Igualmente. Me gusta este edificio."],[1,"Yes, it's a good place. We are happy here.","Sí, es un buen lugar. Estamos felices aquí."],[2,"Do you live in apartment 4B?","¿Vives en el apartamento 4B?"],[0,"Yes, I do. It's a nice apartment.","Sí. Es un lindo apartamento."],[1,"That's great. We are in 4A.","Qué bueno. Nosotras estamos en el 4A."],[2,"We are neighbors! That is funny.","¡Somos vecinos! Qué gracioso."],[0,"Yes! Well, see you later.","¡Sí! Bueno, nos vemos luego."],[1,"Okay, bye Andre!","¡De acuerdo, adiós Andre!"]]},{"id":"va1-21","nivel":"A1","emoji":"🍕","titulo":"What's for Lunch?","tituloEs":"¿Qué hay para almorzar?","personas":[{"nombre":"Nate","genero":"hombre","rol":"Amigo"},{"nombre":"Olivia","genero":"mujer","rol":"Amiga"},{"nombre":"Eli","genero":"hombre","rol":"Amigo"},{"nombre":"Lily","genero":"mujer","rol":"Amiga"}],"lineas":[[0,"I'm hungry. Let's eat lunch.","Tengo hambre. Vamos a almorzar."],[1,"I want pizza. Pizza is my favorite.","Yo quiero pizza. La pizza es mi favorita."],[2,"Yes! I like pizza a lot.","¡Sí! Me gusta mucho la pizza."],[3,"I like tacos. Tacos are very good.","A mí me gustan los tacos. Los tacos son muy buenos."],[0,"Mmm, I like tacos too.","Mmm, a mí también me gustan los tacos."],[1,"What do you like on your pizza, Eli?","¿Qué te gusta en tu pizza, Eli?"],[2,"I just like cheese. A lot of cheese.","Solo me gusta el queso. Mucho queso."],[3,"And you, Nate? Pizza or tacos?","¿Y tú, Nate? ¿Pizza o tacos?"],[0,"Tacos today. Let's get tacos.","Tacos hoy. Vamos a comer tacos."],[1,"Okay! I like tacos too.","¡Está bien! A mí también me gustan los tacos."],[2,"Great! I'm very hungry now.","¡Genial! Ahora tengo mucha hambre."]]},{"id":"va1-22","nivel":"A1","emoji":"🚆","titulo":"Buying a Train Ticket","tituloEs":"Comprando un boleto de tren","personas":[{"nombre":"Priya","genero":"mujer","rol":"Agente de boletos"},{"nombre":"Carlos","genero":"hombre","rol":"Pasajero"}],"lineas":[[0,"Hello. How can I help you?","Hola. ¿Cómo puedo ayudarte?"],[1,"Hi. I want one ticket to Chicago.","Hola. Quiero un boleto para Chicago."],[0,"Okay. For today?","De acuerdo. ¿Para hoy?"],[1,"Yes, for today, please.","Sí, para hoy, por favor."],[0,"The next train is at 2 PM.","El próximo tren es a las 2 p.m."],[1,"Oh, 2 PM is late. Is there a train in the morning?","Oh, las 2 p.m. es tarde. ¿Hay un tren por la mañana?"],[0,"Yes, there's a train at 10 AM.","Sí, hay un tren a las 10 a.m."],[1,"Perfect! The 10 AM train, please.","¡Perfecto! El tren de las 10 a.m., por favor."],[0,"Great. That's fifty dollars.","Genial. Son cincuenta dólares."],[1,"Okay. Here you are. Thank you!","De acuerdo. Aquí tiene. ¡Gracias!"],[0,"You're welcome. Here's your ticket.","De nada. Aquí está su boleto."]]},{"id":"va1-23","nivel":"A1","emoji":"🎸","titulo":"What Do You Like To Do?","tituloEs":"¿Qué te gusta hacer?","personas":[{"nombre":"Caleb","genero":"hombre","rol":"amigo"},{"nombre":"Vanessa","genero":"mujer","rol":"amiga"},{"nombre":"Danny","genero":"hombre","rol":"amigo"}],"lineas":[[0,"Hi! What do you like to do for fun?","¡Hola! ¿Qué les gusta hacer para divertirse?"],[1,"I like to watch movies. I watch movies every weekend.","Me gusta ver películas. Veo películas todos los fines de semana."],[2,"Me too! I love movies. I also play sports.","¡A mí también! Me encantan las películas. También hago deportes."],[0,"Cool. I don't play sports. I read books.","Genial. Yo no hago deportes. Yo leo libros."],[1,"Oh, I like books too. What do you read?","Oh, a mí también me gustan los libros. ¿Qué lees?"],[2,"I don't read much. I prefer music.","Yo no leo mucho. Prefiero la música."],[0,"I listen to music when I read. It's nice.","Yo escucho música cuando leo. Es agradable."],[1,"That's a good idea! I want to try that.","¡Es una buena idea! Quiero probar eso."],[2,"So, we all like movies. Let's watch one tomorrow!","Entonces, a todos nos gustan las películas. ¡Veamos una mañana!"],[0,"Yes! I want to go.","¡Sí! Yo quiero ir."]]},{"id":"va1-24","nivel":"A1","emoji":"💼","titulo":"Talking About Work","tituloEs":"Hablando del trabajo","personas":[{"nombre":"Ryan","genero":"hombre","rol":"amigo de Tasha"},{"nombre":"Tasha","genero":"mujer","rol":"amiga de Ryan"}],"lineas":[[0,"Hi Tasha. How are you?","Hola Tasha. ¿Cómo estás?"],[1,"I'm good, thanks. I'm a little tired.","Estoy bien, gracias. Estoy un poco cansada."],[0,"Oh no. A long day at work?","Oh, no. ¿Un día largo en el trabajo?"],[1,"Yes! I work at a big restaurant.","¡Sí! Trabajo en un restaurante grande."],[0,"Do you like your job?","¿Te gusta tu trabajo?"],[1,"It's okay. The people are nice.","Está bien. La gente es amable."],[0,"That's good. I like my job.","Eso es bueno. A mí me gusta mi trabajo."],[1,"You work in an office, right?","Tú trabajas en una oficina, ¿verdad?"],[0,"Yes. It's very quiet. I like quiet.","Sí. Es muy tranquilo. Me gusta la tranquilidad."],[1,"Haha, I understand. My job is not quiet!","Jaja, entiendo. ¡Mi trabajo no es tranquilo!"]]},{"id":"va1-25","nivel":"A1","emoji":"🍽️","titulo":"Family Dinner Time","tituloEs":"Hora de la cena familiar","personas":[{"nombre":"Frank","genero":"hombre","rol":"Padre"},{"nombre":"Nora","genero":"mujer","rol":"Madre"},{"nombre":"Wes","genero":"hombre","rol":"Hijo"},{"nombre":"Mia","genero":"mujer","rol":"Hija"}],"lineas":[[0,"Mmm, the chicken is good.","Mmm, el pollo está bueno."],[1,"Thank you. I'm happy you like it.","Gracias. Me alegra que te guste."],[2,"Can I have more potatoes?","¿Puedo comer más papas?"],[3,"I want more potatoes too!","¡Yo también quiero más papas!"],[0,"We all love potatoes.","A todos nos encantan las papas."],[1,"Yes, of course. Here you are.","Sí, por supuesto. Aquí tienen."],[2,"Thank you, Mom. This is great.","Gracias, mamá. Esto está genial."],[3,"I really like this dinner.","Realmente me gusta esta cena."],[0,"So, what is for dessert?","Entonces, ¿qué hay de postre?"],[1,"We have ice cream.","Tenemos helado."],[2,"Yes! I love ice cream.","¡Sí! Me encanta el helado."],[3,"Me too! Is it chocolate?","¡A mí también! ¿Es de chocolate?"]]},{"id":"va1-26","nivel":"A1","emoji":"✈️","titulo":"At the Airport Check-in","tituloEs":"En el check-in del aeropuerto","personas":[{"nombre":"Harper","genero":"mujer","rol":"Agente de aerolínea"},{"nombre":"Kyle","genero":"hombre","rol":"Pasajero"}],"lineas":[[0,"Hello! Where are you going today?","¡Hola! ¿A dónde viaja hoy?"],[1,"Hi! I'm going to Miami.","¡Hola! Voy a Miami."],[0,"Oh, Miami is fun! Can I see your passport?","¡Oh, Miami es divertido! ¿Puedo ver su pasaporte?"],[1,"Yes, of course. Here you are.","Sí, claro. Aquí tiene."],[0,"Thank you. Do you have any bags to check?","Gracias. ¿Tiene maletas para documentar?"],[1,"Yes, I have one big suitcase.","Sí, tengo una maleta grande."],[0,"Okay. And you have a carry-on bag?","De acuerdo. ¿Y tiene un bolso de mano?"],[1,"Yes, just this small backpack.","Sí, solo esta mochila pequeña."],[0,"Perfect. Do you want a window seat?","Perfecto. ¿Quiere un asiento de ventana?"],[1,"Oh, yes please! I like window seats.","¡Oh, sí por favor! Me gustan los asientos de ventana."],[0,"Great! Here is your boarding pass. Have a good flight.","¡Genial! Aquí está su pase de abordar. Que tenga un buen vuelo."],[1,"Thank you so much! You too.","¡Muchas gracias! Usted también."]]},{"id":"va1-27","nivel":"A1","emoji":"🎬","titulo":"Going to the Movies","tituloEs":"Ir al cine","personas":[{"nombre":"Caleb","genero":"hombre","rol":"amigo"},{"nombre":"Molly","genero":"mujer","rol":"amiga"},{"nombre":"Noah","genero":"hombre","rol":"amigo"}],"lineas":[[0,"Let's go to the movies today.","Vamos al cine hoy."],[1,"A movie? That's a great idea.","¿Una película? Es una gran idea."],[2,"Yes! I like movies a lot.","¡Sí! Me gustan mucho las películas."],[0,"What movie do you want to see?","¿Qué película quieren ver?"],[1,"I want to see a comedy.","Quiero ver una comedia."],[2,"I like comedies! They are funny.","¡Me gustan las comedias! Son divertidas."],[0,"Okay, a comedy is good for me.","Ok, una comedia está bien para mí."],[1,"Great! And I want popcorn.","¡Genial! Y quiero palomitas de maíz."],[2,"Mmm, popcorn. I want a big popcorn!","Mmm, palomitas. ¡Quiero unas palomitas grandes!"],[0,"Okay, let's go now!","¡Ok, vamos ahora!"]]},{"id":"va1-28","nivel":"A1","emoji":"🔑","titulo":"The Lost Keys","tituloEs":"Las Llaves Perdidas","personas":[{"nombre":"Megan","genero":"mujer","rol":"buscando sus llaves"},{"nombre":"Owen","genero":"hombre","rol":"amigo de Megan"},{"nombre":"Grace","genero":"mujer","rol":"amiga de Megan"}],"lineas":[[0,"Oh no. Where are my keys?","Ay no. ¿Dónde están mis llaves?"],[1,"I don't know. Are they on the table?","No sé. ¿Están sobre la mesa?"],[2,"Look in your bag, Megan.","Busca en tu bolso, Megan."],[0,"No, they're not in my bag.","No, no están en mi bolso."],[1,"I can help you.","Puedo ayudarte."],[2,"Wait. What is in your hand?","Espera. ¿Qué tienes en la mano?"],[0,"My hand? Oh! My keys!","¿Mi mano? ¡Oh! ¡Mis llaves!"],[1,"Haha! You have the keys!","¡Jaja! ¡Tienes las llaves!"],[2,"That's funny. Let's go.","Qué gracioso. Vámonos."],[0,"Okay, I'm ready. Thank you!","Vale, estoy lista. ¡Gracias!"]]},{"id":"va1-29","nivel":"A1","emoji":"🧺","titulo":"Picnic in the Park","tituloEs":"Picnic en el parque","personas":[{"nombre":"Grace","genero":"mujer","rol":"Amiga"},{"nombre":"Ray","genero":"hombre","rol":"Amigo"},{"nombre":"Olivia","genero":"mujer","rol":"Amiga"},{"nombre":"Kayla","genero":"mujer","rol":"Amiga"}],"lineas":[[0,"This park is very nice.","Este parque es muy bonito."],[1,"Yes, it is. I'm hungry now.","Sí, lo es. Tengo hambre ahora."],[2,"I have sandwiches. Do you want one?","Tengo sándwiches. ¿Quieres uno?"],[3,"Yes, please! I like sandwiches.","¡Sí, por favor! Me gustan los sándwiches."],[0,"We have drinks, too. Here is juice.","También tenemos bebidas. Aquí hay jugo."],[1,"Thank you. Are there cookies?","Gracias. ¿Hay galletas?"],[2,"Yes! I have chocolate cookies.","¡Sí! Tengo galletas de chocolate."],[3,"Yum! I love chocolate cookies.","¡Qué rico! Me encantan las galletas de chocolate."],[0,"This is a great picnic.","Este es un picnic genial."],[1,"It is! I am very happy.","¡Lo es! Estoy muy feliz."]]},{"id":"va1-30","nivel":"A1","emoji":"👋","titulo":"Goodbye After the Trip","tituloEs":"Adiós Después del Viaje","personas":[{"nombre":"Kevin","genero":"hombre","rol":"amigo de viaje"},{"nombre":"Emma","genero":"mujer","rol":"amiga de viaje"},{"nombre":"Paige","genero":"mujer","rol":"amiga de viaje"},{"nombre":"Trevor","genero":"hombre","rol":"amigo de viaje"}],"lineas":[[0,"The trip is over. I'm sad.","El viaje se terminó. Estoy triste."],[1,"Me too. This is a great trip.","Yo también. Este es un viaje genial."],[2,"I don't want to go home!","¡No quiero ir a casa!"],[3,"I know. But my flight is soon.","Lo sé. Pero mi vuelo es pronto."],[0,"My taxi is here now.","Mi taxi ya está aquí."],[1,"Okay. Have a good flight.","Bueno. Que tengas un buen vuelo."],[2,"Yes, travel safe, everyone.","Sí, viajen con cuidado todos."],[3,"You too. Let's talk tomorrow.","Ustedes también. Hablemos mañana."],[0,"Yes! Goodbye, my friends.","¡Sí! Adiós, mis amigos."],[1,"Goodbye, Kevin! Bye, everyone!","¡Adiós, Kevin! ¡Chau a todos!"]]},{"id":"va2-01","nivel":"A2","emoji":"🤝","titulo":"A Simple Job Interview","tituloEs":"Una entrevista de trabajo sencilla","personas":[{"nombre":"Andre","genero":"hombre","rol":"Candidato"},{"nombre":"Rachel","genero":"mujer","rol":"Entrevistadora"}],"lineas":[[1,"Hi Andre, please come in. You can sit down here.","Hola Andre, por favor pasa. Puedes sentarte aquí."],[0,"Thank you. It's nice to meet you, Rachel.","Gracias. Es un gusto conocerte, Rachel."],[1,"So, tell me about your last job. What did you do?","Bueno, cuéntame sobre tu último trabajo. ¿Qué hacías?"],[0,"I was a waiter at The Corner Cafe for two years.","Fui mesero en The Corner Cafe por dos años."],[1,"Oh, I know that place! It's always very busy.","¡Ah, conozco ese lugar! Siempre está muy concurrido."],[0,"Yes, it was very busy. This job is closer to my house.","Sí, estaba muy ocupado. Este trabajo está más cerca de mi casa."],[1,"That's good. Why do you want to work here with us?","Qué bueno. ¿Por qué quieres trabajar aquí con nosotros?"],[0,"Your restaurant is more famous than the cafe. The food looks great.","Su restaurante es más famoso que el café. La comida se ve genial."],[1,"Haha, thank you! We think our food is better, too.","¡Jaja, gracias! Nosotros también creemos que nuestra comida es mejor."],[0,"And I want to learn more about cooking. I love food.","Y quiero aprender más sobre cocina. Me encanta la comida."],[1,"That's great to hear. Do you have any questions for me?","Es genial oír eso. ¿Tienes alguna pregunta para mí?"],[0,"No, not right now, thank you.","No, no por ahora, gracias."],[1,"Okay, great. I am going to call you this week.","De acuerdo, genial. Te voy a llamar esta semana."],[0,"Perfect. Thank you for your time. Have a good day.","Perfecto. Gracias por tu tiempo. Que tengas un buen día."]]},{"id":"va2-02","nivel":"A2","emoji":"🏢","titulo":"Finding a New Apartment","tituloEs":"Buscando un nuevo apartamento","personas":[{"nombre":"Owen","genero":"hombre","rol":"Buscando apartamento"},{"nombre":"Rachel","genero":"mujer","rol":"Buscando apartamento"}],"lineas":[[0,"So, what did you think of that apartment?","Entonces, ¿qué te pareció ese apartamento?"],[1,"I liked it. It's much bigger than the last one we saw.","Me gustó. Es mucho más grande que el último que vimos."],[0,"Yes, the living room was very spacious. And I loved the kitchen.","Sí, la sala era muy espaciosa. Y me encantó la cocina."],[1,"Me too! But it's more expensive. We need to think about it.","¡A mí también! Pero es más caro. Necesitamos pensarlo."],[0,"That's true. The location is better, though. It's closer to the train.","Es verdad. Sin embargo, la ubicación es mejor. Está más cerca del tren."],[1,"Good point. Did you get the agent's phone number?","Buen punto. ¿Conseguiste el número de teléfono del agente?"],[0,"I did. I'm going to call him back tomorrow morning.","Sí. Lo voy a volver a llamar mañana por la mañana."],[1,"Okay, great. This one has a really nice balcony for our plants.","Vale, genial. Este tiene un balcón muy lindo para nuestras plantas."],[0,"And the building looked very clean. The other place was a bit dirty.","Y el edificio se veía muy limpio. El otro lugar estaba un poco sucio."],[1,"You're right. I didn't like the old carpet there at all.","Tienes razón. No me gustó para nada la alfombra vieja de allí."],[0,"So, are we going to take this one? I think we should.","Entonces, ¿vamos a quedarnos con este? Yo creo que deberíamos."],[1,"Yes, let's do it! I'm excited to move in.","¡Sí, hagámoslo! Estoy emocionada por mudarnos."]]},{"id":"va2-03","nivel":"A2","emoji":"🧳","titulo":"Planning a Trip with Friends","tituloEs":"Planeando un viaje con amigos","personas":[{"nombre":"Trevor","genero":"hombre","rol":"Amigo del grupo"},{"nombre":"Vanessa","genero":"mujer","rol":"Amiga del grupo"},{"nombre":"Nora","genero":"mujer","rol":"Amiga del grupo"},{"nombre":"Erin","genero":"mujer","rol":"Amiga del grupo"}],"lineas":[[0,"Okay everyone, let's plan our trip. Where are we going to go?","Bueno todos, planeemos nuestro viaje. ¿A dónde vamos a ir?"],[1,"I want to go to the beach. The weather is warmer there.","Quiero ir a la playa. El clima es más cálido allá."],[2,"Hmm, the mountains are nice too. I went there last year.","Mmm, las montañas también son bonitas. Fui allí el año pasado."],[3,"The beach is more relaxing than the mountains. I agree with Vanessa.","La playa es más relajante que las montañas. Estoy de acuerdo con Vanessa."],[0,"So, the beach sounds good. When are we going to travel?","Entonces, la playa suena bien. ¿Cuándo vamos a viajar?"],[1,"How about next month? I looked up some hotels yesterday.","¿Qué tal el próximo mes? Ayer busqué algunos hoteles."],[2,"Next month is good for me. Can we find a cheap hotel?","El próximo mes está bien para mí. ¿Podemos encontrar un hotel barato?"],[3,"An Airbnb is sometimes cheaper than a hotel. I can look for one.","Un Airbnb a veces es más barato que un hotel. Puedo buscar uno."],[0,"That's a great idea, Erin. Let's check out the prices tonight.","Es una gran idea, Erin. Echemos un vistazo a los precios esta noche."],[1,"Yes! I'm getting excited. This trip is going to be fun.","¡Sí! Me estoy emocionando. Este viaje va a ser divertido."],[2,"I agree. I'm going to bring my new camera for photos.","De acuerdo. Voy a llevar mi cámara nueva para las fotos."],[3,"Perfect! I can't wait to hang out together at the beach.","¡Perfecto! No puedo esperar a pasar el rato juntos en la playa."]]},{"id":"va2-04","nivel":"A2","emoji":"🍸","titulo":"Meeting a Friend's Friend","tituloEs":"Conociendo a la amiga de un amigo","personas":[{"nombre":"Kyle","genero":"hombre","rol":"Amigo en común"},{"nombre":"Julia","genero":"mujer","rol":"Amiga de Kyle"},{"nombre":"Kayla","genero":"mujer","rol":"Amiga de Kyle"}],"lineas":[[0,"Julia! You came. This is my friend Kayla.","¡Julia! Viniste. Esta es mi amiga Kayla."],[1,"Hi Kayla, nice to meet you. I'm happy to be here.","Hola Kayla, encantada de conocerte. Estoy feliz de estar aquí."],[2,"You too, Julia! Kyle told me a lot about you.","¡Igualmente, Julia! Kyle me habló mucho de ti."],[0,"Only good things, I promise. What are you going to drink?","Solo cosas buenas, lo prometo. ¿Qué vas a beber?"],[1,"I'm not sure. What are you guys having?","No estoy segura. ¿Qué están tomando ustedes?"],[2,"I got a beer. It's colder than my last one, thankfully!","Pedí una cerveza. ¡Está más fría que la anterior, por suerte!"],[1,"That sounds good. I think I'm going to have a beer too.","Eso suena bien. Creo que voy a tomar una cerveza también."],[0,"Great idea. I went to a new brewery last weekend.","Gran idea. Fui a una nueva cervecería el fin de semana pasado."],[2,"Oh really? Was it better than this place?","¿Ah, sí? ¿Era mejor que este lugar?"],[0,"The music was better, but the beer is more expensive there.","La música era mejor, pero la cerveza es más cara allí."],[1,"I like the music here. It's not too loud.","Me gusta la música de aquí. No está demasiado alta."],[2,"I agree. Let's get you that beer! Kyle is paying.","Estoy de acuerdo. ¡Vamos a buscarte esa cerveza! Paga Kyle."],[0,"Hey! Okay, fine. The first one is on me.","¡Oye! De acuerdo, está bien. La primera corre por mi cuenta."]]},{"id":"va2-05","nivel":"A2","emoji":"🥶","titulo":"My Food is Cold","tituloEs":"Mi comida está fría","personas":[{"nombre":"Kayla","genero":"mujer","rol":"Clienta en restaurante"},{"nombre":"Nate","genero":"hombre","rol":"Amigo de Kayla"},{"nombre":"Rachel","genero":"mujer","rol":"Mesera"}],"lineas":[[0,"Oh, my pasta is cold. This isn't very good.","Oh, mi pasta está fría. Esto no está muy bueno."],[1,"Really? My chicken isn't very hot either. What a shame.","¿En serio? Mi pollo tampoco está muy caliente. Qué lástima."],[2,"Hi, how is everything? Are you enjoying your meal?","Hola, ¿cómo está todo? ¿Están disfrutando su comida?"],[0,"Excuse me, my food is a little cold. Could you heat it up?","Disculpe, mi comida está un poco fría. ¿Podría calentarla?"],[1,"Yes, my food is pretty cold too. It's not warm enough.","Sí, mi comida también está bastante fría. No está lo suficientemente caliente."],[2,"Oh, I'm so sorry. I am going to get you new plates.","Oh, lo siento mucho. Les voy a traer platos nuevos."],[0,"Thank you so much. We would really appreciate that.","Muchas gracias. Realmente lo apreciaríamos."],[1,"Thanks! We're very hungry, so hot food will be great.","¡Gracias! Tenemos mucha hambre, así que la comida caliente será genial."],[2,"Of course. Let me take these back to the kitchen now.","Por supuesto. Déjenme llevar estos de vuelta a la cocina ahora."],[0,"Great, thanks again for your help. You are very kind.","Genial, gracias de nuevo por tu ayuda. Eres muy amable."],[1,"Now I'm even more excited to eat my chicken!","¡Ahora estoy aún más emocionado por comer mi pollo!"],[2,"It will be just a few minutes. I'll be right back!","Serán solo unos minutos. ¡Ya vuelvo!"]]},{"id":"va2-06","nivel":"A2","emoji":"🏋️","titulo":"Joining the Gym","tituloEs":"Inscribirse en el gimnasio","personas":[{"nombre":"Abby","genero":"mujer","rol":"nueva socia"},{"nombre":"Wes","genero":"hombre","rol":"empleado del gimnasio"}],"lineas":[[0,"Hi, I'd like to sign up for a membership.","Hola, me gustaría inscribirme para una membresía."],[1,"Great! We have a few different plans. What are you looking for?","¡Genial! Tenemos algunos planes diferentes. ¿Qué estás buscando?"],[0,"I want to use the pool and the yoga classes.","Quiero usar la piscina y las clases de yoga."],[1,"Okay, the Gold plan is good for that. It's more popular than our basic plan.","Vale, el plan Gold es bueno para eso. Es más popular que nuestro plan básico."],[0,"How much does that cost? I don't want something too expensive.","¿Cuánto cuesta eso? No quiero algo demasiado caro."],[1,"It's fifty dollars a month. And the first month is half price.","Son cincuenta dólares al mes. Y el primer mes es a mitad de precio."],[0,"Oh, that's better than I thought! I'm going to take that one.","¡Ah, eso es mejor de lo que pensaba! Voy a tomar ese."],[1,"Perfect. I just need you to fill out this short form, please.","Perfecto. Solo necesito que llenes este breve formulario, por favor."],[0,"Sure. I went to my old gym two or three times a week.","Claro. Iba a mi antiguo gimnasio dos o tres veces por semana."],[1,"That's great. You're going to love our yoga classes here.","Eso es genial. Te van a encantar nuestras clases de yoga de aquí."],[0,"Awesome! I am very excited. When can I start?","¡Genial! Estoy muy emocionada. ¿Cuándo puedo empezar?"],[1,"You can start today! Welcome to the gym.","¡Puedes empezar hoy mismo! Bienvenida al gimnasio."]]},{"id":"va2-07","nivel":"A2","emoji":"💊","titulo":"At the Pharmacy","tituloEs":"En la farmacia","personas":[{"nombre":"Nicole","genero":"mujer","rol":"clienta en la farmacia"},{"nombre":"Mason","genero":"hombre","rol":"cliente en la farmacia"}],"lineas":[[0,"Mason? Wow, you don't look very good at all.","¿Mason? Vaya, no te ves nada bien."],[1,"Hi Nicole. I feel much worse than I look.","Hola, Nicole. Me siento mucho peor de lo que me veo."],[0,"Oh no! What are you getting for your cold?","¡Oh, no! ¿Qué vas a comprar para tu resfriado?"],[1,"I'm going to buy everything. This is the worst cold ever.","Voy a comprar de todo. Este es el peor resfriado de la historia."],[0,"I had a bad cold last month. It was terrible.","Tuve un resfriado fuerte el mes pasado. Fue terrible."],[1,"Was it worse than this? I can't even taste food.","¿Fue peor que esto? Ni siquiera puedo saborear la comida."],[0,"Maybe not! I just came to pick up some vitamins.","¡Quizás no! Solo vine a recoger unas vitaminas."],[1,"That's a good idea. Vitamins are better than medicine sometimes.","Es una buena idea. A veces las vitaminas son mejores que las medicinas."],[0,"You should get some vitamin C. It really helps a lot.","Deberías comprar algo de vitamina C. Ayuda mucho de verdad."],[1,"Okay, I'll look for it. My head hurts so much.","Vale, la buscaré. Me duele muchísimo la cabeza."],[0,"Get well soon, Mason! I hope you feel better tomorrow.","¡Mejórate pronto, Mason! Espero que mañana te sientas mejor."],[1,"Thanks, Nicole. I hope so too. See you around.","Gracias, Nicole. Yo también lo espero. Nos vemos por ahí."]]},{"id":"va2-08","nivel":"A2","emoji":"📦","titulo":"Returning a Damaged Item","tituloEs":"Devolviendo un producto dañado","personas":[{"nombre":"Brandon","genero":"hombre","rol":"Empleado de tienda"},{"nombre":"Claire","genero":"mujer","rol":"Clienta"}],"lineas":[[0,"Hi there, how can I help you today?","Hola, ¿cómo puedo ayudarte hoy?"],[1,"Hi, I need to return this coffee maker. It arrived broken.","Hola, necesito devolver esta cafetera. Llegó rota."],[0,"Oh no, I'm sorry about that. Do you have your receipt?","Oh no, lo lamento. ¿Tienes tu recibo?"],[1,"Yes, I bought it online last week. Here's the email confirmation.","Sí, la compré en línea la semana pasada. Aquí está la confirmación del correo."],[0,"Great, thanks. I'm going to look up your order right now.","Genial, gracias. Voy a buscar tu pedido ahora mismo."],[1,"The box looked fine, but the glass part was in pieces.","La caja se veía bien, pero la parte de vidrio estaba en pedazos."],[0,"That's not good at all. We can give you a new one.","Eso no es bueno para nada. Podemos darte una nueva."],[1,"Oh, that's great! Is this new one going to break easily too?","¡Oh, qué bien! ¿Esta nueva también se va a romper fácilmente?"],[0,"I hope not! This model is much stronger than the old one.","¡Espero que no! Este modelo es mucho más resistente que el antiguo."],[1,"That sounds better. It also looks a little nicer.","Eso suena mejor. También se ve un poco más bonita."],[0,"It is. Do you want to take this one home with you?","Lo es. ¿Quieres llevarte esta a casa?"],[1,"Yes, please. Thank you so much for all your help.","Sí, por favor. Muchas gracias por toda tu ayuda."],[0,"You're very welcome! Enjoy your coffee.","De nada. ¡Que disfrutes tu café!"]]},{"id":"va2-09","nivel":"A2","emoji":"🏖️","titulo":"Talking About Our Vacations","tituloEs":"Hablando de nuestras vacaciones","personas":[{"nombre":"Nora","genero":"mujer","rol":"amiga"},{"nombre":"Frank","genero":"hombre","rol":"amigo"},{"nombre":"Ella","genero":"mujer","rol":"amiga"}],"lineas":[[0,"Hey Frank! How was your vacation? You just got back, right?","¡Hola, Frank! ¿Qué tal tus vacaciones? Acabas de regresar, ¿verdad?"],[1,"It was great! I went camping with my family near the lake.","¡Estuvieron geniales! Fui a acampar con mi familia cerca del lago."],[2,"Oh, camping is so fun. Was the weather good for you?","Oh, acampar es muy divertido. ¿Tuvieron buen clima?"],[0,"I prefer hotels. Camping is colder than staying in a hotel.","Yo prefiero los hoteles. Acampar es más frío que quedarse en un hotel."],[1,"Yes, but the stars at night were amazing. It was beautiful.","Sí, pero las estrellas en la noche estuvieron increíbles. Fue hermoso."],[2,"I went to the city. I visited museums and the food was delicious.","Yo fui a la ciudad. Visité museos y la comida estuvo deliciosa."],[0,"That sounds nice. Was it more expensive than your trip last year?","Eso suena bien. ¿Fue más caro que tu viaje del año pasado?"],[1,"What about you, Nora? What did you do for your vacation?","¿Y tú, Nora? ¿Qué hiciste en tus vacaciones?"],[2,"Yes, tell us! Did you go anywhere special this time?","¡Sí, cuéntanos! ¿Fuiste a algún lugar especial esta vez?"],[0,"I stayed home. I just relaxed and watched a lot of movies.","Me quedé en casa. Solo me relajé y vi muchas películas."],[1,"Sometimes that's the best vacation. No stress at all!","A veces esas son las mejores vacaciones. ¡Nada de estrés!"],[2,"True! We have to look at your camping photos sometime, Frank.","¡Cierto! Tenemos que ver tus fotos del campamento alguna vez, Frank."]]},{"id":"va2-10","nivel":"A2","emoji":"🍳","titulo":"Cooking Dinner Together","tituloEs":"Cocinando la cena juntos","personas":[{"nombre":"Kevin","genero":"hombre","rol":"esposo"},{"nombre":"Abby","genero":"mujer","rol":"esposa"},{"nombre":"Sophia","genero":"mujer","rol":"amiga"}],"lineas":[[0,"What are we going to make for dinner tonight?","¿Qué vamos a hacer para la cena esta noche?"],[1,"Let's make pasta. It's easier than making tacos.","Hagamos pasta. Es más fácil que hacer tacos."],[2,"Great idea! I can help you cut up the vegetables.","¡Gran idea! Puedo ayudarles a picar las verduras."],[0,"Okay. I burned the pasta last time, so please help me.","Está bien. Quemé la pasta la última vez, así que por favor ayúdenme."],[1,"Don't worry. We are going to watch the pot carefully.","No te preocupes. Vamos a vigilar la olla con cuidado."],[2,"Kevin, can you get the big pot from that cabinet?","Kevin, ¿puedes traer la olla grande de ese gabinete?"],[0,"Yes, here it is. Is this one big enough for all of us?","Sí, aquí está. ¿Es esta lo suficientemente grande para todos nosotros?"],[1,"It's perfect. Now we need to put some water in it.","Es perfecta. Ahora necesitamos ponerle un poco de agua."],[2,"I brought a special sauce. My mom made it yesterday.","Traje una salsa especial. Mi mamá la hizo ayer."],[0,"Wow, thank you! Your mom's cooking is better than mine.","¡Vaya, gracias! La comida de tu mamá es mejor que la mía."],[1,"Okay, the water is boiling. Let's put in the pasta.","Bueno, el agua está hirviendo. Pongamos la pasta."],[2,"This dinner is going to be really delicious, everyone!","¡Esta cena va a estar realmente deliciosa, todos!"]]},{"id":"va2-11","nivel":"A2","emoji":"🧹","titulo":"Roommate Cleaning Plan","tituloEs":"Plan de limpieza de compañeros","personas":[{"nombre":"Kayla","genero":"mujer","rol":"compañera de piso"},{"nombre":"Wes","genero":"hombre","rol":"compañero de piso"},{"nombre":"Justin","genero":"hombre","rol":"compañero de piso"}],"lineas":[[0,"Hey guys, this apartment is a mess. We need to clean up.","Oigan, chicos, este apartamento es un desastre. Necesitamos limpiar."],[1,"I know. I cleaned the kitchen last week, but it's dirty again.","Lo sé. Limpié la cocina la semana pasada, pero está sucia de nuevo."],[2,"Well, my room is definitely cleaner than your room, Wes.","Bueno, mi cuarto definitivamente está más limpio que el tuyo, Wes."],[0,"Okay, let's not argue. I'm going to clean the living room.","Ok, no discutamos. Yo voy a limpiar la sala de estar."],[1,"Alright, I can vacuum the floors and take out the trash.","Está bien, yo puedo aspirar los pisos y sacar la basura."],[2,"So, what about the bathroom? That's the worst job.","Entonces, ¿qué hay del baño? Ese es el peor trabajo."],[0,"Yes, the bathroom is your job. You didn't help much last time.","Sí, el baño es tu tarea. No ayudaste mucho la última vez."],[1,"She's right. The bathroom is the dirtiest place in the house!","¡Ella tiene razón. El baño es el lugar más sucio de la casa!"],[2,"Oh, come on. Fine, I'll do it, but I get to choose the music.","Oh, vamos. Bien, lo haré, pero yo escojo la música."],[0,"That's a deal. Let's make this place look nice again.","Trato hecho. Hagamos que este lugar se vea bien de nuevo."],[1,"And after we finish, we're going to order a big pizza.","Y después de que terminemos, vamos a pedir una pizza grande."],[2,"Okay, now I'm ready to clean. Pizza makes everything better!","¡Ok, ahora estoy listo para limpiar. La pizza hace todo mejor!"]]},{"id":"va2-12","nivel":"A2","emoji":"👔","titulo":"First Day at a New Job","tituloEs":"Primer día en un trabajo nuevo","personas":[{"nombre":"Luis","genero":"hombre","rol":"empleado nuevo"},{"nombre":"Rachel","genero":"mujer","rol":"la jefa"},{"nombre":"Tasha","genero":"mujer","rol":"compañera de trabajo"},{"nombre":"Danny","genero":"hombre","rol":"compañero de trabajo"}],"lineas":[[1,"Everyone, this is Luis. He is our new graphic designer.","A todos, él es Luis. Es nuestro nuevo diseñador gráfico."],[2,"Welcome, Luis! It's great to have you on the team.","¡Bienvenido, Luis! Es genial tenerte en el equipo."],[3,"Hi, Luis. I'm Danny. We are happy to see a new face.","Hola, Luis. Soy Danny. Estamos felices de ver una cara nueva."],[0,"Hello, everyone. I'm very excited to start working with you.","Hola a todos. Estoy muy emocionado de empezar a trabajar con ustedes."],[1,"Your desk is over there. Tasha can help you set up your computer.","Tu escritorio está por allá. Tasha puede ayudarte a configurar tu computadora."],[2,"Of course. My desk is bigger than Danny's, so I have more space!","Por supuesto. ¡Mi escritorio es más grande que el de Danny, así que tengo más espacio!"],[3,"That's true. But my chair is much more comfortable than hers!","Es verdad. ¡Pero mi silla es mucho más cómoda que la de ella!"],[0,"Haha, thanks. I looked for the coffee station, but I didn't find it.","Jaja, gracias. Busqué la estación de café, pero no la encontré."],[2,"It's in the kitchen. I'm going to get some now. Do you want a cup?","Está en la cocina. Voy a buscar un poco ahora. ¿Quieres una taza?"],[0,"Yes, please! That would be great. Thank you so much.","¡Sí, por favor! Eso sería genial. Muchas gracias."],[3,"Later, we are going to have lunch together. We usually get pizza.","Más tarde, vamos a almorzar juntos. Usualmente comemos pizza."],[1,"That's a good idea. Luis, come find me after you are settled.","Es una buena idea. Luis, ven a buscarme cuando ya te hayas instalado."]]},{"id":"va2-13","nivel":"A2","emoji":"📲","titulo":"Booking a Table by Phone","tituloEs":"Reservar una mesa por teléfono","personas":[{"nombre":"Ava","genero":"mujer","rol":"Empleada del restaurante"},{"nombre":"Greg","genero":"hombre","rol":"Cliente"}],"lineas":[[0,"Good evening, The Corner Bistro. How can I help you?","Buenas noches, The Corner Bistro. ¿En qué puedo ayudarle?"],[1,"Hi, I'd like to make a reservation for tonight.","Hola, me gustaría hacer una reserva para esta noche."],[0,"Of course. For how many people and what time?","Por supuesto. ¿Para cuántas personas y a qué hora?"],[1,"For two people. We were thinking about 7:30 PM.","Para dos personas. Estábamos pensando sobre las 7:30 PM."],[0,"Let me see... 7:30 is very busy tonight.","Déjeme ver... Las 7:30 está muy concurrido esta noche."],[1,"Oh, really? Is a later time better for you?","Ah, ¿en serio? ¿Es mejor para ustedes una hora más tarde?"],[0,"Yes, 8:00 PM is much better. We have a table then.","Sí, las 8:00 PM es mucho mejor. Tenemos una mesa a esa hora."],[1,"Great! 8:00 PM is perfect for us, actually.","¡Genial! Las 8:00 PM es perfecto para nosotros, de hecho."],[0,"Wonderful. Can I have a name for the booking, please?","Maravilloso. ¿Me puede dar un nombre para la reserva, por favor?"],[1,"Yes, the name is Greg. That's G-R-E-G.","Sí, el nombre es Greg. Se deletrea G-R-E-G."],[0,"Okay, Greg. I have you down for a table at 8:00.","De acuerdo, Greg. Lo tengo anotado para una mesa a las 8:00."],[1,"Thank you so much! We'll see you then. Goodbye!","¡Muchísimas gracias! Nos vemos entonces. ¡Adiós!"]]},{"id":"va2-14","nivel":"A2","emoji":"🏦","titulo":"Opening a Bank Account","tituloEs":"Abrir una cuenta bancaria","personas":[{"nombre":"Ryan","genero":"hombre","rol":"Cliente nuevo del banco"},{"nombre":"Olivia","genero":"mujer","rol":"Amiga"}],"lineas":[[0,"Hey Olivia, I'm going to the bank this afternoon.","Hola Olivia, voy a ir al banco esta tarde."],[1,"Oh, really? What do you need to do there?","¿Ah, sí? ¿Qué necesitas hacer allí?"],[0,"I need to open a new bank account for my job.","Necesito abrir una nueva cuenta bancaria para mi trabajo."],[1,"That's exciting! I opened my account there last year.","¡Qué emocionante! Yo abrí mi cuenta allí el año pasado."],[0,"Was it difficult? I'm a little nervous about it.","¿Fue difícil? Estoy un poco nervioso por eso."],[1,"No, it was easier than I expected. It was very fast.","No, fue más fácil de lo que esperaba. Fue muy rápido."],[0,"Good. What documents did you bring with you?","Qué bueno. ¿Qué documentos llevaste contigo?"],[1,"I just brought my ID and a bill with my address.","Solo llevé mi identificación y una factura con mi dirección."],[0,"Okay, great. I have my passport and a phone bill.","Vale, genial. Tengo mi pasaporte y una factura del teléfono."],[1,"That's perfect. Don't worry, the people there are helpful.","Eso es perfecto. No te preocupes, la gente de allí es servicial."],[0,"Thanks for the information. I feel much better now.","Gracias por la información. Ahora me siento mucho mejor."],[1,"You're welcome! Good luck with everything today.","¡De nada! Buena suerte con todo hoy."]]},{"id":"va2-15","nivel":"A2","emoji":"🚗","titulo":"Renting a Car for the Weekend","tituloEs":"Alquilando un carro para el fin de semana","personas":[{"nombre":"Max","genero":"hombre","rol":"Cliente"},{"nombre":"Emma","genero":"mujer","rol":"Agente de alquiler"}],"lineas":[[0,"Hi, I'd like to rent a car, please.","Hola, me gustaría alquilar un carro, por favor."],[1,"Of course! What kind of car are you looking for?","¡Claro! ¿Qué tipo de carro está buscando?"],[0,"I need something for the weekend. Maybe a small car?","Necesito algo para el fin de semana. ¿Quizás un carro pequeño?"],[1,"We have a compact car available. It's very good on gas.","Tenemos un carro compacto disponible. Ahorra mucha gasolina."],[0,"Is it bigger than the economy car? I have some luggage.","¿Es más grande que el carro económico? Tengo algo de equipaje."],[1,"Yes, it's a little bigger and has more space.","Sí, es un poco más grande y tiene más espacio."],[0,"Great! I saw a promotion online. Is it still valid?","¡Genial! Vi una promoción en línea. ¿Todavía es válida?"],[1,"Let me check for you. What was the promotion code?","Déjeme revisar. ¿Cuál era el código de la promoción?"],[0,"It was 'WEEKEND20'. I wrote it down yesterday.","Era 'WEEKEND20'. Lo anoté ayer."],[1,"Yes, that code works! You're going to get a great price.","¡Sí, ese código funciona! Va a conseguir un precio excelente."],[0,"Wonderful! This is much easier than I thought.","¡Maravilloso! Esto es mucho más fácil de lo que pensé."],[1,"I'm happy to help. We'll get everything ready for you.","Estoy feliz de ayudar. Le prepararemos todo."]]},{"id":"va2-16","nivel":"A2","emoji":"📚","titulo":"Parent-Teacher Meeting","tituloEs":"Reunión de padres y profesora","personas":[{"nombre":"Julia","genero":"mujer","rol":"profesora"},{"nombre":"Jake","genero":"hombre","rol":"papá de Leo"},{"nombre":"Zach","genero":"hombre","rol":"papá de Leo"}],"lineas":[[0,"Hi, thanks for coming in. I'm Leo's teacher.","Hola, gracias por venir. Soy la profesora de Leo."],[1,"Hello! It's nice to meet you. We're Leo's dads.","¡Hola! Mucho gusto en conocerla. Somos los papás de Leo."],[2,"Yes, we wanted to see how he's doing in class.","Sí, queríamos ver cómo le está yendo en clase."],[0,"Leo is doing very well. His reading is much better now.","A Leo le está yendo muy bien. Su lectura es mucho mejor ahora."],[1,"That's great to hear! He reads with us every night.","¡Qué bueno escuchar eso! Él lee con nosotros todas las noches."],[2,"Is his math okay? He thinks math is harder than reading.","¿Sus matemáticas están bien? Él piensa que las matemáticas son más difíciles que la lectura."],[0,"His math is good too. He just needs to slow down a little.","Sus matemáticas también están bien. Solo necesita ir un poco más despacio."],[1,"Yes, he always wants to finish first. It's a little funny.","Sí, siempre quiere terminar primero. Es un poco gracioso."],[2,"What are you going to work on next in the class?","¿En qué van a trabajar después en la clase?"],[0,"We're going to start a new science project next week.","Vamos a empezar un nuevo proyecto de ciencias la próxima semana."],[1,"Oh, he will love that. He loves learning about animals.","Oh, eso le va a encantar. Le encanta aprender sobre los animales."],[2,"Thank you so much for your time. This was very helpful.","Muchas gracias por su tiempo. Esto fue de mucha ayuda."],[0,"You're welcome. It was a pleasure to meet you both.","De nada. Fue un placer conocerlos a ambos."]]},{"id":"va2-17","nivel":"A2","emoji":"💈","titulo":"Getting a Fresh Haircut","tituloEs":"Haciéndose un corte de pelo nuevo","personas":[{"nombre":"Ethan","genero":"hombre","rol":"cliente de la barbería"},{"nombre":"Hannah","genero":"mujer","rol":"amiga de Ethan"}],"lineas":[[0,"Hey Hannah, what do you think of my new haircut?","Oye Hannah, ¿qué te parece mi nuevo corte de pelo?"],[1,"Oh wow, you cut your hair! It looks great, really fresh.","¡Oh, vaya, te cortaste el pelo! Se ve genial, muy fresco."],[0,"Thanks! I went to that new barbershop downtown yesterday.","¡Gracias! Fui a esa nueva barbería en el centro ayer."],[1,"It looks much shorter than your old style. Was it busy?","Se ve mucho más corto que tu estilo anterior. ¿Había mucha gente?"],[0,"Yes, it was pretty busy. But the barber did a good job.","Sí, estaba bastante lleno. Pero el barbero hizo un buen trabajo."],[1,"He did! It's better than your last haircut, I think.","¡Claro que sí! Es mejor que tu último corte, creo."],[0,"I agree. It feels so much lighter for the warm weather.","Estoy de acuerdo. Se siente mucho más ligero para el clima cálido."],[1,"That makes sense. Now I want to cut my hair too.","Tiene sentido. Ahora yo también quiero cortarme el pelo."],[0,"Are you going to get a new style for the summer?","¿Te vas a hacer un nuevo estilo para el verano?"],[1,"I'm going to think about it. Maybe something shorter.","Voy a pensarlo. Quizás algo más corto."],[0,"You should! You can check out the place I went to.","¡Deberías! Puedes echar un vistazo al lugar al que fui."],[1,"Good idea. I'll look it up on my phone later.","Buena idea. Lo buscaré en mi teléfono más tarde."]]},{"id":"va2-18","nivel":"A2","emoji":"💻","titulo":"Help with the Computer","tituloEs":"Ayuda con la computadora","personas":[{"nombre":"Ella","genero":"mujer","rol":"Compañera de trabajo"},{"nombre":"Noah","genero":"hombre","rol":"Compañero de trabajo"}],"lineas":[[0,"Ugh, Noah? Can you help me for a minute, please?","Uf, ¿Noah? ¿Puedes ayudarme un minuto, por favor?"],[1,"Sure, Ella. What's going on with your computer?","Claro, Ella. ¿Qué pasa con tu computadora?"],[0,"It's so slow today. It's slower than my old phone!","Está muy lenta hoy. ¡Es más lenta que mi teléfono viejo!"],[1,"Hmm, let me see. Did you turn it off last night?","Mmm, déjame ver. ¿La apagaste anoche?"],[0,"No, I didn't. I never turn it off. Is that a problem?","No, no lo hice. Nunca la apago. ¿Eso es un problema?"],[1,"Sometimes it just needs a good rest. Let's try to restart it.","A veces solo necesita un buen descanso. Intentemos reiniciarla."],[0,"Okay, I'm going to do that now. I hope it works.","Vale, voy a hacer eso ahora. Espero que funcione."],[1,"Me too. Just wait a minute for it to start up.","Yo también. Solo espera un minuto a que arranque."],[0,"Hey, it's working! It's much faster now. You're a genius!","¡Oye, está funcionando! Ahora es mucho más rápida. ¡Eres un genio!"],[1,"Haha, not a genius. The computer was just very tired.","Jaja, no soy un genio. La computadora solo estaba muy cansada."],[0,"Well, thank you so much! I'm going to buy you a coffee.","Bueno, ¡muchas gracias! Voy a invitarte a un café."],[1,"That sounds great. No problem at all, Ella.","Eso suena genial. Ningún problema, Ella."]]},{"id":"va2-19","nivel":"A2","emoji":"⚽","titulo":"Watching the Game at a Bar","tituloEs":"Viendo el partido en un bar","personas":[{"nombre":"Kyle","genero":"hombre","rol":"amigo del grupo"},{"nombre":"Megan","genero":"mujer","rol":"amiga del grupo"},{"nombre":"Claire","genero":"mujer","rol":"amiga del grupo"},{"nombre":"Denise","genero":"mujer","rol":"amiga del grupo"}],"lineas":[[0,"This game is so exciting! I'm glad we came here.","¡Este partido es muy emocionante! Me alegra que hayamos venido aquí."],[1,"Me too. This bar is nicer than the last one. I'm going to get some fries.","A mí también. Este bar es más agradable que el anterior. Voy a pedir unas papas fritas."],[2,"Hi everyone! Sorry I'm late. What's the score now?","¡Hola a todos! Disculpen que llego tarde. ¿Cómo va el marcador ahora?"],[3,"It's one to zero. The other team is playing very badly today.","Va uno a cero. El otro equipo está jugando muy mal hoy."],[0,"Yeah, our team is much better. They played well last week too.","Sí, nuestro equipo es mucho mejor. Jugaron bien la semana pasada también."],[1,"Did you see that goal? It was amazing! I almost missed it.","¿Viste ese gol? ¡Fue increíble! Casi me lo pierdo."],[2,"I saw it! Who is going to win this game?","¡Yo lo vi! ¿Quién va a ganar este partido?"],[3,"I think we are. After the game, let's go out for pizza.","Creo que nosotros. Después del partido, salgamos a comer pizza."],[0,"That sounds great. I'm getting really hungry now.","Eso suena genial. Me está dando mucha hambre ahora."],[1,"Okay, but let's watch the end. Look! He's going to shoot!","Vale, pero veamos el final. ¡Mira! ¡Va a tirar a gol!"],[2,"Wow! This is more exciting than my work meeting yesterday.","¡Guau! Esto es más emocionante que mi reunión de trabajo de ayer."],[3,"Haha, of course it is! Come on, team!","Jaja, ¡por supuesto que sí! ¡Vamos, equipo!"]]},{"id":"va2-20","nivel":"A2","emoji":"🍿","titulo":"Movie Night Decisions","tituloEs":"Decisiones de noche de películas","personas":[{"nombre":"Noah","genero":"hombre","rol":"Amigo del grupo"},{"nombre":"Tasha","genero":"mujer","rol":"Amiga del grupo"},{"nombre":"Nicole","genero":"mujer","rol":"Amiga del grupo"},{"nombre":"Paige","genero":"mujer","rol":"Amiga del grupo"}],"lineas":[[0,"So, what are we going to watch tonight? I want something funny.","Entonces, ¿qué vamos a ver esta noche? Quiero algo divertido."],[1,"I saw a new comedy yesterday. It was okay, but not great.","Vi una comedia nueva ayer. Estuvo bien, pero no genial."],[2,"How about a horror movie? They're more exciting than comedies.","¿Qué tal una película de terror? Son más emocionantes que las comedias."],[3,"Oh no, I don't like horror movies. They are too scary for me.","Ay no, no me gustan las películas de terror. Me dan demasiado miedo."],[0,"I agree. Let's find something different. No horror, please.","Estoy de acuerdo. Busquemos algo diferente. Terror no, por favor."],[1,"Okay, what about that new action movie? I think it's on Netflix.","Vale, ¿qué tal esa película de acción nueva? Creo que está en Netflix."],[2,"Oh, I heard about that one. Let's look for it now.","Ah, oí hablar de esa. Busquémosla ahora."],[3,"Good idea! Action is better than horror. I can watch that.","¡Buena idea! La acción es mejor que el terror. Esa sí la puedo ver."],[0,"Perfect. So, are we going to order a large pizza, too?","Perfecto. Entonces, ¿vamos a pedir una pizza grande también?"],[1,"Yes! I'm getting hungry. I can call the pizza place right now.","¡Sí! Me está dando hambre. Puedo llamar a la pizzería ahora mismo."],[2,"Great! You order the pizza, and I'll put on the movie.","¡Genial! Tú pide la pizza y yo pongo la película."],[3,"This is going to be a fun night. I'll go get the blankets.","Esta va a ser una noche divertida. Iré a buscar las mantas."]]},{"id":"va2-21","nivel":"A2","emoji":"🛄","titulo":"Lost Suitcase at the Airport","tituloEs":"Maleta perdida en el aeropuerto","personas":[{"nombre":"Victor","genero":"hombre","rol":"Pasajero"},{"nombre":"Brooke","genero":"mujer","rol":"Amiga de Victor"}],"lineas":[[0,"Oh no! I can't find my suitcase. I looked for it everywhere.","¡Ay, no! No encuentro mi maleta. La busqué por todas partes."],[1,"Are you sure? What does your suitcase look like?","¿Estás seguro? ¿Cómo es tu maleta?"],[0,"It's a normal black suitcase. It's not very big.","Es una maleta negra normal. No es muy grande."],[1,"Black suitcases are more difficult to find than other colors.","Las maletas negras son más difíciles de encontrar que las de otros colores."],[0,"I know! My old suitcase was bright blue. It was much better.","¡Lo sé! Mi maleta anterior era azul brillante. Era mucho mejor."],[1,"Where did you see your suitcase for the last time?","¿Dónde viste tu maleta por última vez?"],[0,"I think it was on the baggage carousel over there.","Creo que estaba en la cinta de equipaje de allá."],[1,"Okay, let's go ask at the lost and found office.","Bueno, vamos a preguntar en la oficina de objetos perdidos."],[0,"Good idea. I hope they have it. I'm going to need my clothes.","Buena idea. Espero que la tengan. Voy a necesitar mi ropa."],[1,"Is there anything really important in the suitcase?","¿Hay algo realmente importante en la maleta?"],[0,"Well, my favorite sweater is in there. It was a gift.","Bueno, mi suéter favorito está ahí. Fue un regalo."],[1,"Don't worry. We are going to find your favorite sweater.","No te preocupes. Vamos a encontrar tu suéter favorito."],[0,"Thanks, Brooke. You are much nicer than the airport staff.","Gracias, Brooke. Eres mucho más amable que el personal del aeropuerto."],[1,"Haha, come on. I'm sure they are going to help us.","Jaja, vamos. Estoy segura de que nos van a ayudar."]]},{"id":"va2-22","nivel":"A2","emoji":"🦷","titulo":"After the Dentist","tituloEs":"Después del dentista","personas":[{"nombre":"Nora","genero":"mujer","rol":"paciente"},{"nombre":"Noah","genero":"hombre","rol":"amigo de Nora"}],"lineas":[[0,"Okay, I'm all done. That was not very fun.","Ok, ya terminé. Eso no fue muy divertido."],[1,"How are you feeling? Was the dentist nice?","¿Cómo te sientes? ¿Fue amable el dentista?"],[0,"My mouth is still so numb. I can't feel my lips!","Todavía tengo la boca muy dormida. ¡No siento mis labios!"],[1,"You look a little funny when you try to smile.","Te ves un poco rara cuando intentas sonreír."],[0,"It's not funny! But he was nicer than the last doctor.","¡No es gracioso! Pero él fue más amable que el doctor anterior."],[1,"That's good. So, what did he say about your teeth?","Qué bueno. Y, ¿qué dijo sobre tus dientes?"],[0,"He said they are good. I just need to floss more often.","Dijo que están bien. Solo necesito usar el hilo dental más seguido."],[1,"That's what they always say. It's never enough floss.","Eso es lo que siempre dicen. Nunca es suficiente hilo dental."],[0,"I know. Now, I'm going to go home and eat candy.","Lo sé. Ahora, voy a ir a casa a comer dulces."],[1,"Ha! I don't think that is a very good idea.","¡Ja! No creo que esa sea una muy buena idea."],[0,"I'm just kidding. Can we get some ice cream, please?","Solo estoy bromeando. ¿Podemos ir por un helado, por favor?"],[1,"Of course! Let's go get you some ice cream right now.","¡Claro! Vamos a comprarte un helado ahora mismo."]]},{"id":"va2-23","nivel":"A2","emoji":"🎁","titulo":"A Gift for Mom","tituloEs":"Un regalo para mamá","personas":[{"nombre":"Caleb","genero":"hombre","rol":"hijo"},{"nombre":"Ella","genero":"mujer","rol":"hija"},{"nombre":"Denise","genero":"mujer","rol":"hija"}],"lineas":[[0,"Okay, Mom's birthday is next week. What are we going to get her?","Bueno, el cumpleaños de mamá es la próxima semana. ¿Qué le vamos a comprar?"],[1,"I don't know. I thought about a book because she likes reading.","No sé. Pensé en un libro porque a ella le gusta leer."],[2,"A book is nice, but we can find something more special this year.","Un libro está bien, pero podemos encontrar algo más especial este año."],[0,"What about perfume? She liked the one we got for her last year.","¿Y qué tal un perfume? Le gustó el que le compramos el año pasado."],[1,"That's true, but I think her new perfume is better. Let's think of something else.","Es verdad, pero creo que su perfume nuevo es mejor. Pensemos en otra cosa."],[2,"How about a beautiful scarf? She always wears them in the winter.","¿Qué te parece una bufanda bonita? Siempre las usa en el invierno."],[0,"A scarf is a great idea! It's more personal than a book.","¡Una bufanda es una gran idea! Es más personal que un libro."],[1,"Yes! I saw some very pretty scarves at the mall last weekend.","¡Sí! Vi unas bufandas muy bonitas en el centro comercial el fin de semana pasado."],[2,"Perfect. Are we going to look for one together on Saturday?","Perfecto. ¿Vamos a buscar una juntos el sábado?"],[0,"That sounds good. We can meet up around noon.","Eso suena bien. Podemos encontrarnos cerca del mediodía."],[1,"Great! She is going to love a new scarf from all of us.","¡Genial! Le va a encantar una bufanda nueva de parte de todos."],[2,"I agree. It's a perfect gift for her.","Estoy de acuerdo. Es un regalo perfecto para ella."]]},{"id":"va2-24","nivel":"A2","emoji":"👵","titulo":"Video Call with Grandma and Grandpa","tituloEs":"Videollamada con los abuelos","personas":[{"nombre":"Frank","genero":"hombre","rol":"abuelo"},{"nombre":"Zoe","genero":"mujer","rol":"abuela"},{"nombre":"Justin","genero":"hombre","rol":"nieto"},{"nombre":"Emma","genero":"mujer","rol":"nieta"}],"lineas":[[0,"Hi kids! It's so good to see your faces.","¡Hola, niños! Qué bueno ver sus caras."],[1,"You're getting so big! Justin, your hair is longer now.","¡Están creciendo mucho! Justin, tu cabello está más largo ahora."],[2,"Hi! Yeah, I'm going to get it cut next week.","¡Hola! Sí, me lo voy a cortar la próxima semana."],[3,"Hello! I played soccer yesterday. My team won the game.","¡Hola! Jugué fútbol ayer. Mi equipo ganó el partido."],[0,"That's my girl! Did you have fun with your friends?","¡Esa es mi chica! ¿Te divertiste con tus amigos?"],[1,"We are so proud of you. What are you going to eat for dinner?","Estamos muy orgullosos de ustedes. ¿Qué van a cenar?"],[2,"We're going to have pizza. It's my favorite food!","Vamos a comer pizza. ¡Es mi comida favorita!"],[3,"I'm going to help Dad pick it up from the restaurant.","Voy a ayudar a papá a recogerla del restaurante."],[0,"That sounds nice. Your grandma and I watched a movie last night.","Eso suena bien. Tu abuela y yo vimos una película anoche."],[1,"He fell asleep before the end, like always!","¡Se quedó dormido antes del final, como siempre!"],[2,"We have to go now. It was great talking to you!","Tenemos que irnos ahora. ¡Fue genial hablar con ustedes!"],[3,"Bye! We love you! We'll call back on the weekend.","¡Adiós! ¡Los queremos! Volveremos a llamar el fin de semana."]]},{"id":"va2-25","nivel":"A2","emoji":"🔊","titulo":"A Noisy Hotel Room","tituloEs":"Una habitación de hotel ruidosa","personas":[{"nombre":"Frank","genero":"hombre","rol":"huésped del hotel"},{"nombre":"Lauren","genero":"mujer","rol":"recepcionista"}],"lineas":[[0,"Excuse me, I have a problem with my room.","Disculpe, tengo un problema con mi habitación."],[1,"Oh, I'm sorry to hear that. What's the problem?","Oh, lamento escuchar eso. ¿Cuál es el problema?"],[0,"It's very noisy. I didn't sleep well last night.","Es muy ruidosa. No dormí bien anoche."],[1,"I understand. The street outside can be very loud.","Entiendo. La calle de afuera puede ser muy ruidosa."],[0,"Yes. Do you have a quieter room available?","Sí. ¿Tiene una habitación más tranquila disponible?"],[1,"Let me see. Yes, we have a room on a higher floor.","Déjeme ver. Sí, tenemos una habitación en un piso más alto."],[0,"That's great. Is it bigger than my current room?","Eso es genial. ¿Es más grande que mi habitación actual?"],[1,"It's a little smaller, but it is much quieter.","Es un poco más pequeña, pero es mucho más silenciosa."],[0,"A quiet room is more important. I'll take it.","Una habitación tranquila es más importante. La tomaré."],[1,"Perfect. I'm going to prepare your new key for you.","Perfecto. Voy a prepararle su nueva llave."],[0,"Thank you so much! You are very helpful.","¡Muchas gracias! Es usted muy amable."],[1,"You're welcome. The new room is ready for you now.","De nada. La nueva habitación ya está lista para usted."]]},{"id":"va2-26","nivel":"A2","emoji":"🌮","titulo":"Lunch at the Food Truck","tituloEs":"Almuerzo en el food truck","personas":[{"nombre":"Logan","genero":"hombre","rol":"Amigo de Kim y Molly"},{"nombre":"Kim","genero":"mujer","rol":"Amiga de Logan y Molly"},{"nombre":"Molly","genero":"mujer","rol":"Amiga de Logan y Kim"}],"lineas":[[0,"Okay, what are we getting? I'm so hungry right now.","Bueno, ¿qué vamos a pedir? Tengo mucha hambre ahora mismo."],[1,"Hmm, the tacos look good. I had them last week.","Mmm, los tacos se ven bien. Los comí la semana pasada."],[2,"Are they very spicy? I don't like very spicy food.","¿Son muy picantes? No me gusta la comida muy picante."],[0,"The sign says they are a little spicy. The burrito is bigger.","El letrero dice que son un poco picantes. El burrito es más grande."],[1,"Yes, the burrito is much bigger than the tacos, and it's not spicy.","Sí, el burrito es mucho más grande que los tacos, y no es picante."],[2,"Okay, I'm going to get the chicken burrito then. That sounds great.","Vale, voy a pedir el burrito de pollo entonces. Eso suena genial."],[0,"Good choice. I'm going to try the spicy tacos. I love spicy food.","Buena elección. Voy a probar los tacos picantes. Me encanta la comida picante."],[1,"I think I'll get the tacos again. They were really delicious.","Creo que voy a pedir los tacos otra vez. Estaban realmente deliciosos."],[2,"Great! So, that's one burrito and two orders of tacos.","¡Genial! Entonces, es un burrito y dos órdenes de tacos."],[0,"Perfect. Let's go order before I eat the menu.","Perfecto. Vamos a pedir antes de que me coma el menú."],[1,"Haha, okay. I'm going to find us a place to sit down.","Jaja, de acuerdo. Voy a buscarnos un lugar para sentarnos."],[2,"Good idea. We can wait for you over there by the bench.","Buena idea. Podemos esperarte allá junto a la banca."]]},{"id":"va2-27","nivel":"A2","emoji":"🚌","titulo":"The Bus is Late","tituloEs":"El bus llega tarde","personas":[{"nombre":"Wes","genero":"hombre","rol":"extraño en la parada"},{"nombre":"Amber","genero":"mujer","rol":"extraña en la parada"}],"lineas":[[0,"Excuse me, do you know when the bus is coming?","Disculpa, ¿sabes cuándo viene el bus?"],[1,"I'm not sure. It's usually here at ten o'clock.","No estoy segura. Usualmente está aquí a las diez en punto."],[0,"Right. It's already ten twenty. I'm going to be late for work.","Cierto. Ya son las diez y veinte. Voy a llegar tarde al trabajo."],[1,"Me too! Waiting makes it feel colder than yesterday.","¡Yo también! Esperar hace que se sienta más frío que ayer."],[0,"You're right. Yesterday was much warmer than today.","Tienes razón. Ayer estuvo mucho más cálido que hoy."],[1,"I know! When did you get here this morning?","¡Lo sé! ¿Cuándo llegaste aquí esta mañana?"],[0,"I got here at ten o'clock. So, twenty minutes ago.","Llegué a las diez en punto. O sea, hace veinte minutos."],[1,"Oh, I only came here five minutes ago. You waited longer!","Oh, yo solo llegué hace cinco minutos. ¡Tú esperaste más tiempo!"],[0,"Haha, yes. Maybe our bus went on vacation today.","Jaja, sí. Quizás nuestro bus se fue de vacaciones hoy."],[1,"That's a funny thought! I really hope it comes soon.","¡Qué idea tan graciosa! De verdad espero que venga pronto."],[0,"Oh, wait! Look over there! I think that's our bus!","¡Oh, espera! ¡Mira para allá! ¡Creo que ese es nuestro bus!"],[1,"Finally! It was really nice talking to you.","¡Por fin! Fue muy agradable hablar contigo."]]},{"id":"va2-28","nivel":"A2","emoji":"📝","titulo":"Study Group Before an Exam","tituloEs":"Grupo de estudio antes de un examen","personas":[{"nombre":"Trevor","genero":"hombre","rol":"estudiante"},{"nombre":"Zoe","genero":"mujer","rol":"estudiante"},{"nombre":"Grace","genero":"mujer","rol":"estudiante"},{"nombre":"Ryan","genero":"hombre","rol":"estudiante"}],"lineas":[[0,"I'm not ready for this test. I studied a lot last night.","No estoy listo para este examen. Estudié mucho anoche."],[1,"Don't worry. We're going to review the important topics together now.","No te preocupes. Vamos a repasar los temas importantes juntos ahora."],[2,"Good idea. Chapter three is easier than chapter four.","Buena idea. El capítulo tres es más fácil que el capítulo cuatro."],[3,"I agree. I didn't understand chapter four at all.","Estoy de acuerdo. No entendí nada del capítulo cuatro."],[0,"Okay, chapter three then. I have some questions about the vocabulary.","Ok, capítulo tres entonces. Tengo algunas preguntas sobre el vocabulario."],[1,"We can look up the words. I have my dictionary right here.","Podemos buscar las palabras. Tengo mi diccionario aquí mismo."],[2,"You are more prepared than me! That's really helpful.","¡Estás más preparada que yo! Eso es de gran ayuda."],[3,"After this, are we going to get some coffee? I need it.","Después de esto, ¿vamos a buscar un café? Lo necesito."],[0,"Yes! That sounds much better than studying more.","¡Sí! Eso suena mucho mejor que seguir estudiando."],[1,"Let's study for one more hour. Then we can go.","Estudiemos una hora más. Luego podemos ir."],[2,"Perfect. My brain is going to be tired later anyway.","Perfecto. Mi cerebro va a estar cansado más tarde de todos modos."],[3,"Great! The coffee is going to be my reward.","¡Genial! El café va a ser mi recompensa."]]},{"id":"va2-29","nivel":"A2","emoji":"🏡","titulo":"A Great Housewarming Party","tituloEs":"Una Gran Fiesta de Inauguración","personas":[{"nombre":"Mason","genero":"hombre","rol":"Amigo de Ashley"},{"nombre":"Ashley","genero":"mujer","rol":"La nueva dueña"},{"nombre":"Erin","genero":"mujer","rol":"Amiga de Ashley"},{"nombre":"Natalie","genero":"mujer","rol":"Amiga de Ashley"}],"lineas":[[0,"Ashley, your new house is amazing! I really love it.","¡Ashley, tu casa nueva es increíble! Me encanta de verdad."],[1,"Thanks, Mason! We're so happy you could make it.","¡Gracias, Mason! Estamos muy felices de que pudieras venir."],[2,"This living room is much bigger than your old apartment.","Esta sala es mucho más grande que tu apartamento anterior."],[3,"I agree! And where did you get this awesome painting?","¡Estoy de acuerdo! ¿Y dónde conseguiste esta pintura genial?"],[0,"The backyard looks great too. What did you do there?","El patio trasero también se ve genial. ¿Qué hicieron allí?"],[1,"We cleaned it up. We're going to put some chairs there soon.","Lo limpiamos. Vamos a poner algunas sillas allí pronto."],[2,"I love this music. Who chose the songs for the party?","Me encanta esta música. ¿Quién eligió las canciones para la fiesta?"],[3,"I did! I'm happy you like the playlist I put together.","¡Fui yo! Me alegra que te guste la lista de reproducción que armé."],[0,"You did a great job. Is there anything to eat?","Hiciste un gran trabajo. ¿Hay algo para comer?"],[1,"Of course! The food is on the table in the kitchen.","¡Por supuesto! La comida está en la mesa de la cocina."],[2,"Perfect! I'm going to get a plate right now.","¡Perfecto! Voy a buscar un plato ahora mismo."],[3,"Good idea. Let's go check out the food together.","Buena idea. Vayamos a ver la comida juntas."]]},{"id":"va2-30","nivel":"A2","emoji":"🧾","titulo":"Splitting the Bill","tituloEs":"Dividiendo la cuenta","personas":[{"nombre":"Greg","genero":"hombre","rol":"amigo"},{"nombre":"Chloe","genero":"mujer","rol":"amiga"},{"nombre":"Claire","genero":"mujer","rol":"amiga"}],"lineas":[[0,"Wow, that dinner was really good.","Wow, esa cena estuvo muy buena."],[1,"It was! My salad was bigger than I expected.","¡Lo estuvo! Mi ensalada fue más grande de lo que esperaba."],[2,"Everything was delicious. Should we get the check now?","Todo estaba delicioso. ¿Deberíamos pedir la cuenta ahora?"],[0,"I already asked for it. Don't worry, I'm going to pay.","Ya la pedí. No se preocupen, yo voy a pagar."],[1,"Oh, Greg, that's very nice, but you don't have to.","Oh, Greg, eso es muy amable, pero no tienes que hacerlo."],[2,"Yes, let's just split the bill. It's easier.","Sí, simplemente dividamos la cuenta. Es más fácil."],[0,"Are you sure? It was my idea to come here.","¿Están seguras? Fue mi idea venir aquí."],[1,"We are sure. We can just divide it by three.","Estamos seguras. Podemos simplemente dividirlo entre tres."],[2,"Exactly. So, how much is the total?","Exacto. Entonces, ¿cuánto es el total?"],[0,"The total is sixty dollars. That's twenty dollars each.","El total es sesenta dólares. Eso es veinte dólares cada uno."],[1,"Okay, perfect. I'm going to pay with my card.","Ok, perfecto. Voy a pagar con mi tarjeta."],[2,"Me too. Thanks for offering to pay, Greg!","Yo también. ¡Gracias por ofrecerte a pagar, Greg!"]]},{"id":"vb1-01","nivel":"B1","emoji":"💼","titulo":"A Friendly Job Interview","tituloEs":"Una entrevista de trabajo amigable","personas":[{"nombre":"Jake","genero":"hombre","rol":"entrevistador"},{"nombre":"Maya","genero":"mujer","rol":"entrevistadora"},{"nombre":"Chloe","genero":"mujer","rol":"candidata"}],"lineas":[[0,"Hi Chloe, thanks for coming in. I'm Jake, and this is my colleague, Maya.","Hola Chloe, gracias por venir. Soy Jake, y esta es mi colega, Maya."],[1,"It's great to meet you. Your resume is very impressive.","Es un placer conocerte. Tu currículum es muy impresionante."],[2,"Thank you! I'm really excited about this opportunity.","¡Gracias! Estoy muy entusiasmada con esta oportunidad."],[0,"Good. So, what have you enjoyed most about your previous roles?","Bien. Entonces, ¿qué es lo que más has disfrutado de tus trabajos anteriores?"],[2,"Well, I've worked on several campaigns, but I've really enjoyed social media management. It's so dynamic.","Bueno, he trabajado en varias campañas, pero he disfrutado mucho la gestión de redes sociales. Es muy dinámico."],[1,"That's great to hear. Can you tell us about a time you had to deal with a difficult client?","Qué bueno escuchar eso. ¿Puedes contarnos sobre alguna vez que tuviste que lidiar con un cliente difícil?"],[2,"Oh, definitely. I once had a client who wanted their logo to be 'louder'. It was a bit funny.","Oh, claro. Una vez tuve un cliente que quería que su logo fuera 'más ruidoso'. Fue un poco gracioso."],[0,"Louder? That's a new one. How did you handle that?","¿Más ruidoso? Esa es nueva. ¿Cómo manejaste eso?"],[2,"I had to explain that colors don't actually make sounds. I showed them some bold color options and they loved it.","Tuve que explicarle que los colores en realidad no hacen sonidos. Le mostré algunas opciones de colores llamativos y le encantó."],[1,"That sounds like you handled it perfectly. So, why do you want to work with us specifically?","Suena a que lo manejaste perfectamente. Entonces, ¿por qué quieres trabajar con nosotros específicamente?"],[2,"I've followed your company for a while, and I really admire your creative work. I feel like I'd fit in well here.","He seguido a su empresa por un tiempo y realmente admiro su trabajo creativo. Siento que encajaría bien aquí."],[0,"We like to hear that. If you were hired, what would be your first priority?","Nos gusta oír eso. Si te contratáramos, ¿cuál sería tu primera prioridad?"],[2,"I would focus on understanding the team and your current projects. A smooth start is important.","Me enfocaría en entender al equipo y sus proyectos actuales. Un comienzo sin problemas es importante."],[1,"Excellent. Well, we'll be in touch by the end of the week.","Excelente. Bueno, nos pondremos en contacto para el final de la semana."],[2,"Great, thank you so much for your time. It was a pleasure meeting you both.","Genial, muchas gracias por su tiempo. Fue un placer conocerlos a ambos."],[0,"You too, Chloe. Have a great day.","Igualmente, Chloe. Que tengas un buen día."]]},{"id":"vb1-02","nivel":"B1","emoji":"🔑","titulo":"Negotiating the Rent","tituloEs":"Negociando el Alquiler","personas":[{"nombre":"Grace","genero":"mujer","rol":"Inquilina"},{"nombre":"Owen","genero":"hombre","rol":"Dueño"}],"lineas":[[0,"Hi Owen, thanks for meeting me. I've received the new lease agreement.","Hola Owen, gracias por reunirte conmigo. He recibido el nuevo contrato de alquiler."],[1,"Hi Grace. Great. So, you saw the rent is going up to $1,800.","Hola Grace. Genial. Entonces, viste que el alquiler sube a $1,800."],[0,"Yes, I did. To be honest, that's a bit more than I was expecting.","Sí, lo vi. Para ser honesta, es un poco más de lo que esperaba."],[1,"I understand. The thing is, market rates have gone up quite a bit this year.","Entiendo. El tema es que los precios del mercado han subido bastante este año."],[0,"I know, but I've been a good tenant for three years and I've always paid on time.","Lo sé, pero he sido una buena inquilina por tres años y siempre he pagado a tiempo."],[1,"You're right, you have. And I really appreciate that. I don't want to lose you.","Tienes razón, lo has sido. Y realmente aprecio eso. No quiero perderte."],[0,"Well, if you could meet me in the middle, I could sign for another year right now.","Bueno, si pudieras negociar un punto medio, podría firmar por otro año ahora mismo."],[1,"What do you have in mind? What feels fair to you?","¿Qué tienes en mente? ¿Qué te parece justo?"],[0,"How about $1,725? That's still an increase, but it's one I can manage.","¿Qué tal $1,725? Sigue siendo un aumento, pero es uno que puedo manejar."],[1,"Hmm, $1,725... you know what? Okay. For a great tenant like you, it's a deal.","Mmm, $1,725... ¿sabes qué? De acuerdo. Por una inquilina genial como tú, es un trato."],[0,"Oh, thank you so much, Owen! That is a huge relief.","¡Oh, muchísimas gracias, Owen! Es un gran alivio."],[1,"You're very welcome. I'll send you the updated lease this afternoon.","De nada. Te enviaré el contrato actualizado esta tarde."],[0,"Perfect. I really appreciate you being so reasonable.","Perfecto. Realmente aprecio que seas tan razonable."],[1,"No problem at all. Have a good one, Grace.","Ningún problema. Que tengas un buen día, Grace."]]},{"id":"vb1-03","nivel":"B1","emoji":"📊","titulo":"Project Deadline Check-in","tituloEs":"Reunión sobre la fecha de entrega","personas":[{"nombre":"Tasha","genero":"mujer","rol":"líder de equipo"},{"nombre":"Luis","genero":"hombre","rol":"desarrollador"},{"nombre":"Nora","genero":"mujer","rol":"diseñadora"},{"nombre":"Frank","genero":"hombre","rol":"diseñador"}],"lineas":[[0,"Okay team, let's talk about the project deadline. Do we still think Friday is realistic?","Bueno equipo, hablemos de la fecha de entrega del proyecto. ¿Todavía creemos que el viernes es realista?"],[1,"Well, I'm a little worried. I've finished the main code, but the testing is taking longer than I expected.","Pues, estoy un poco preocupado. He terminado el código principal, pero las pruebas están tomando más tiempo de lo que esperaba."],[2,"I see. What if Frank and I help you with the testing? We've already completed our design tasks.","Entiendo. ¿Y si Frank y yo te ayudamos con las pruebas? Ya hemos completado nuestras tareas de diseño."],[3,"Yeah, absolutely. I mean, two extra pairs of eyes are better than one, right? We can get it done faster.","Sí, por supuesto. O sea, cuatro ojos ven más que dos, ¿verdad? Podemos terminarlo más rápido."],[0,"That's a great idea, Nora. Thanks, Frank. If you both help Luis, we should be able to meet the deadline.","Esa es una gran idea, Nora. Gracias, Frank. Si ambos ayudan a Luis, deberíamos poder cumplir con la fecha de entrega."],[1,"That would be a huge help. I think with your support, we can definitely finish by Friday.","Eso sería de gran ayuda. Creo que con su apoyo, definitivamente podemos terminar para el viernes."],[2,"Perfect. I can start this afternoon. I'll review the user interface part first.","Perfecto. Puedo empezar esta tarde. Revisaré la parte de la interfaz de usuario primero."],[3,"Sounds good. And if we finish early, the first round of coffee is on me.","Suena bien. Y si terminamos temprano, yo invito la primera ronda de café."],[0,"Haha, I'll hold you to that, Frank. Okay, great work everyone. Let's do it.","Jaja, te tomo la palabra, Frank. Ok, gran trabajo a todos. Manos a la obra."],[1,"Thanks again, everyone. I feel much better about this now.","Gracias de nuevo a todos. Me siento mucho mejor con esto ahora."],[2,"No problem, Luis. We're a team, after all.","No hay problema, Luis. Somos un equipo, después de todo."],[3,"Exactly! Teamwork makes the dream work... and gets us coffee sooner.","¡Exacto! El trabajo en equipo hace que los sueños se cumplan... y nos consigue café más pronto."],[0,"Alright, you heard him. Let's get back to it. Good talk.","Muy bien, ya lo oyeron. Volvamos al trabajo. Buena charla."],[1,"On it! Thanks again.","¡En eso estoy! Gracias de nuevo."]]},{"id":"vb1-04","nivel":"B1","emoji":"💘","titulo":"First Date at a Bar","tituloEs":"Primera cita en un bar","personas":[{"nombre":"Andre","genero":"hombre","rol":"En una cita"},{"nombre":"Tiffany","genero":"mujer","rol":"En una cita"}],"lineas":[[0,"Hey, Tiffany? Sorry I'm a little late. The traffic was crazy.","¿Hola, Tiffany? Perdón que llego un poco tarde. El tráfico estaba terrible."],[1,"Hi, Andre! No worries at all. It gave me time to check out the menu. I've never been here before.","¡Hola, Andre! No te preocupes para nada. Me dio tiempo de ver el menú. Nunca había venido aquí antes."],[0,"Me neither, actually. My friend recommended it. It looks pretty cool, right?","Yo tampoco, la verdad. Un amigo mío lo recomendó. Se ve bastante genial, ¿no?"],[1,"Yeah, I love the atmosphere. So, your dating profile said you're a graphic designer. That sounds so creative.","Sí, me encanta el ambiente. Oye, tu perfil de citas decía que eres diseñador gráfico. Eso suena muy creativo."],[0,"It has its moments! It's better than my last job, anyway. What about you? You're a teacher, right?","¡Tiene sus momentos! Es mejor que mi último trabajo, de todos modos. ¿Y tú? Eres maestra, ¿verdad?"],[1,"I am. I teach third grade. It's rewarding, but some days... you know. The kids have so much energy.","Sí, lo soy. Doy clases en tercer grado. Es gratificante, pero algunos días... ya sabes. Los niños tienen muchísima energía."],[0,"I can only imagine! I don't think I would have the patience for that.","¡Solo puedo imaginarlo! No creo que yo tendría la paciencia para eso."],[1,"Well, you learn. By the way, I have to ask about the picture of you with the huge fish. Is that real?","Bueno, se aprende. Por cierto, te tengo que preguntar por la foto tuya con el pez enorme. ¿Es de verdad?"],[0,"Haha, yes! I was so proud of that. If I had known it would be such a conversation starter, I would have made it my main photo.","¡Jaja, sí! Estaba muy orgulloso de eso. Si hubiera sabido que daría tanto de qué hablar, la habría puesto como mi foto principal."],[1,"It definitely caught my attention! It’s much better than the usual blurry selfies.","¡Definitivamente llamó mi atención! Es mucho mejor que las típicas selfies borrosas."],[0,"I'll take that as a compliment. So, have you decided what you want to drink?","Lo tomaré como un cumplido. Y bueno, ¿ya decidiste qué quieres beber?"],[1,"I think I'll try one of their famous cocktails. The one with the spicy mango sounds interesting.","Creo que voy a probar uno de sus cócteles famosos. El que tiene mango picante suena interesante."],[0,"Good choice. If you like it, maybe we can order some appetizers to go with it.","Buena elección. Si te gusta, quizás podamos pedir unos aperitivos para acompañarlo."],[1,"I'd like that a lot.","Me gustaría mucho."]]},{"id":"vb1-05","nivel":"B1","emoji":"🌍","titulo":"Debating a Move Abroad","tituloEs":"Debate: ¿mudarse a otro país?","personas":[{"nombre":"Max","genero":"hombre","rol":"Amigo del grupo"},{"nombre":"Amber","genero":"mujer","rol":"Amiga del grupo"},{"nombre":"Julia","genero":"mujer","rol":"Amiga del grupo"}],"lineas":[[0,"I've been thinking a lot lately... what if we just moved to another country?","He estado pensando mucho últimamente... ¿y si simplemente nos mudáramos a otro país?"],[1,"Oh, wow! I love that idea. Imagine living in Italy or Japan!","¡Oh, guau! Me encanta esa idea. ¡Imagina vivir en Italia o Japón!"],[2,"That sounds exciting, but isn't it really difficult? I mean, with visas and finding a job?","Suena emocionante, ¿pero no es muy difícil? Digo, con las visas y encontrar un trabajo."],[0,"Well, yeah, it wouldn't be easy. But I've seen so many people do it. It seems like an amazing adventure.","Bueno, sí, no sería fácil. Pero he visto a tanta gente hacerlo. Parece una aventura increíble."],[1,"Exactly! I've always wanted to become fluent in another language. Plus, think of all the food!","¡Exacto! Siempre he querido hablar con fluidez otro idioma. Además, ¡piensa en toda la comida!"],[2,"I guess... but I would miss my family so much. I think I'd get really homesick.","Supongo... pero extrañaría mucho a mi familia. Creo que me daría mucha nostalgia."],[0,"That's a good point. If I moved, I would definitely need to video call them every day.","Ese es un buen punto. Si me mudara, definitivamente necesitaría hacerles videollamadas todos los días."],[1,"And they could come visit! We could show them around our new city.","¡Y podrían venir de visita! Podríamos mostrarles nuestra nueva ciudad."],[2,"You two make it sound so simple. Have you actually looked at how much it costs?","Ustedes dos hacen que suene tan simple. ¿Se han puesto a ver cuánto cuesta en realidad?"],[0,"Okay, you got me there. I haven't checked the costs yet. It's probably super expensive.","Ok, me atrapaste. No he revisado los costos todavía. Probablemente es súper caro."],[1,"Well, we don't have to move to Paris. There are more affordable places, you know?","Bueno, no tenemos que mudarnos a París. Hay lugares más asequibles, ¿sabes?"],[2,"That's true. Actually, I've heard that Portugal is beautiful and not as expensive.","Es verdad. De hecho, he oído que Portugal es hermoso y no tan caro."],[0,"See? Maybe it's not such a crazy idea after all. We should research it.","¿Ves? Quizás no es una idea tan loca después de todo. Deberíamos investigarlo."],[1,"Yes! But for now, who wants another coffee? My treat.","¡Sí! Pero por ahora, ¿quién quiere otro café? Yo invito."],[2,"Oh, thanks! Let's dream about Portugal over coffee then.","¡Oh, gracias! Entonces soñemos con Portugal con un café."]]},{"id":"vb1-06","nivel":"B1","emoji":"📶","titulo":"The Internet Is Down Again","tituloEs":"El internet no funciona otra vez","personas":[{"nombre":"Justin","genero":"hombre","rol":"Cliente"},{"nombre":"Linda","genero":"mujer","rol":"Agente de servicio al cliente"}],"lineas":[[0,"Hi there. I'm calling because my internet has been out all day.","Hola. Llamo porque no he tenido internet en todo el día."],[1,"Hello! Thanks for calling SpeedNet. I'm sorry to hear that.","¡Hola! Gracias por llamar a SpeedNet. Lamento escuchar eso."],[0,"Yeah, it's not great. I work from home, so this is a real problem for me.","Sí, no es ideal. Trabajo desde casa, así que esto es un verdadero problema para mí."],[1,"I completely understand. First, have you tried restarting your router?","Entiendo perfectamente. Primero, ¿ha intentado reiniciar su rúter?"],[0,"Of course. I've already done that three times. It didn't help at all.","Por supuesto. Ya lo he hecho tres veces. No ayudó en nada."],[1,"Okay, I see. What lights do you see on the front of the device?","De acuerdo, ya veo. ¿Qué luces ve en la parte frontal del aparato?"],[0,"Well, the power light is green, but the internet light is blinking orange.","Pues, la luz de encendido está verde, pero la luz de internet parpadea en naranja."],[1,"Hmm, an orange light isn't good. If we can't fix this now, I'll need to schedule a technician.","Mmm, una luz naranja no es bueno. Si no podemos arreglar esto ahora, tendré que agendar un técnico."],[0,"Oh, I really hope not. I have a meeting in an hour. Is there anything else you can try?","Oh, de verdad espero que no. Tengo una reunión en una hora. ¿Hay algo más que pueda intentar?"],[1,"Yes, actually. Let me try sending a refresh signal from here. Just give me one moment.","Sí, de hecho. Déjeme intentar enviar una señal de actualización desde aquí. Solo deme un momento."],[0,"Okay, I'm crossing my fingers. This has happened before, you know.","Ok, cruzo los dedos. Esto ya ha pasado antes, sabe."],[1,"Alright, I've sent the signal. Can you tell me if the light has changed?","Muy bien, he enviado la señal. ¿Puede decirme si la luz ha cambiado?"],[0,"One second... Hey, it's solid green now! I think it's working! Thank you so much.","Un segundo... ¡Oye, ahora está en verde fijo! ¡Creo que está funcionando! Muchísimas gracias."],[1,"Excellent! I'm so glad we could get it working for you. Have a great day!","¡Excelente! Me alegra mucho que pudiéramos hacerlo funcionar para usted. ¡Que tenga un buen día!"]]},{"id":"vb1-07","nivel":"B1","emoji":"🚓","titulo":"A Minor Fender Bender","tituloEs":"Un Choque Leve","personas":[{"nombre":"Tasha","genero":"mujer","rol":"conductora"},{"nombre":"Lucas","genero":"hombre","rol":"otro conductor"},{"nombre":"Brian","genero":"hombre","rol":"policía"}],"lineas":[[0,"Oh, I'm so sorry! I just didn't see you. Are you okay?","¡Ay, lo siento tanto! Simplemente no te vi. ¿Estás bien?"],[1,"I'm fine, thanks. A bit shaken, but okay. It happened so fast.","Estoy bien, gracias. Un poco alterado, pero bien. Pasó tan rápido."],[2,"Alright folks, I'm Officer Brian. Can I see your driver's licenses and insurance information, please?","Bueno, señores, soy el oficial Brian. ¿Puedo ver sus licencias de conducir e información del seguro, por favor?"],[0,"Yes, of course. Here's my information. I've never been in an accident before. My car is brand new!","Sí, por supuesto. Aquí está mi información. Nunca he tenido un accidente. ¡Mi coche es nuevo de paquete!"],[1,"Me neither. Here are my documents. The most important thing is that nobody got hurt.","Yo tampoco. Aquí están mis documentos. Lo más importante es que nadie salió herido."],[2,"That's right. So, can one of you tell me what happened?","Así es. Entonces, ¿puede alguno de ustedes decirme qué pasó?"],[0,"Well, I was backing out of the parking spot. I really thought I had looked carefully.","Pues, estaba saliendo en reversa del estacionamiento. De verdad pensé que había mirado con cuidado."],[1,"And I was driving through the lot. If you had been a second later, I would have missed you completely.","Y yo estaba conduciendo por el aparcamiento. Si hubieras salido un segundo más tarde, te habría esquivado por completo."],[2,"I see. It looks like just a minor fender bender. No major damage.","Entiendo. Parece que es solo un choque leve. No hay daños mayores."],[0,"So what do we do now? Do we just exchange insurance details?","¿Y ahora qué hacemos? ¿Solo intercambiamos los datos del seguro?"],[2,"I'll write up a short report for you both. You'll need it for your insurance companies.","Redactaré un informe breve para ambos. Lo necesitarán para sus compañías de seguros."],[1,"Okay, that sounds good. I appreciate your help, Officer.","De acuerdo, eso suena bien. Agradezco su ayuda, oficial."],[0,"Yes, thank you so much for your time.","Sí, muchas gracias por su tiempo."],[2,"You're welcome. Just wait here for a few minutes while I get this done.","De nada. Solo esperen aquí unos minutos mientras termino esto."]]},{"id":"vb1-08","nivel":"B1","emoji":"🤒","titulo":"Explaining Symptoms to the Doctor","tituloEs":"Explicando los síntomas al médico","personas":[{"nombre":"Ryan","genero":"hombre","rol":"Paciente"},{"nombre":"Tiffany","genero":"mujer","rol":"Doctora"}],"lineas":[[0,"Hi Doctor. Thanks for seeing me. I haven't been feeling very well lately.","Hola, doctora. Gracias por atenderme. No me he sentido muy bien últimamente."],[1,"Hello Ryan. I'm sorry to hear that. What seems to be the problem?","Hola, Ryan. Lamento oír eso. ¿Cuál parece ser el problema?"],[0,"Well, for about three days, I've had a terrible headache and a sore throat.","Bueno, desde hace unos tres días, he tenido un dolor de cabeza terrible y dolor de garganta."],[1,"I see. And have you had a fever or any other symptoms?","Entiendo. ¿Y ha tenido fiebre o algún otro síntoma?"],[0,"I don't think I have a fever, but I feel really tired and I've been coughing a lot.","No creo tener fiebre, pero me siento muy cansado y he estado tosiendo mucho."],[1,"Okay. Let me take a look at your throat. Please open your mouth and say 'ah'.","De acuerdo. Déjeme revisarle la garganta. Por favor, abra la boca y diga 'ah'."],[0,"Ahhh. It actually hurts when I swallow.","Ahhh. De hecho, me duele cuando trago."],[1,"Yes, it looks quite red. It seems like you have a viral infection, probably a bad cold.","Sí, se ve bastante roja. Parece que tiene una infección viral, probablemente un resfriado fuerte."],[0,"Oh, that's what I thought. Is it serious?","Ah, es lo que pensaba. ¿Es grave?"],[1,"No, not at all. But you should definitely get some rest and drink plenty of fluids.","No, para nada. Pero definitivamente debería descansar y beber muchos líquidos."],[0,"Should I take any medicine for it?","¿Debería tomar algún medicamento para esto?"],[1,"I'd suggest you take some ibuprofen for the pain. That should help with the headache too.","Le sugeriría que tome ibuprofeno para el dolor. Eso también debería ayudar con el dolor de cabeza."],[0,"Okay, that sounds good. So, no antibiotics?","De acuerdo, eso suena bien. Entonces, ¿sin antibióticos?"],[1,"No, antibiotics wouldn't help a virus. If you don't feel better in five days, give us a call.","No, los antibióticos no ayudarían con un virus. Si no se siente mejor en cinco días, llámenos."]]},{"id":"vb1-09","nivel":"B1","emoji":"💍","titulo":"Planning the Wedding Details","tituloEs":"Planeando los detalles de la boda","personas":[{"nombre":"Derek","genero":"hombre","rol":"el novio"},{"nombre":"Claire","genero":"mujer","rol":"la novia"},{"nombre":"Molly","genero":"mujer","rol":"amiga de la novia"},{"nombre":"Tasha","genero":"mujer","rol":"amiga de la novia"}],"lineas":[[0,"Okay, so I've been looking at these venues. My head is spinning. There are so many options.","Bueno, he estado viendo estos lugares. Me da vueltas la cabeza. Hay tantas opciones."],[1,"I know, honey. But let's talk about something fun. What about the wedding cake?","Lo sé, cariño. Pero hablemos de algo divertido. ¿Qué tal el pastel de bodas?"],[2,"Ooh, the cake! Have you thought about flavors? I think chocolate is always a crowd-pleaser.","¡Uy, el pastel! ¿Han pensado en sabores? Creo que el chocolate siempre le gusta a todo el mundo."],[3,"Actually, I went to a wedding with a lemon raspberry cake. It was amazing and so refreshing.","De hecho, fui a una boda con un pastel de limón y frambuesa. Estuvo increíble y muy refrescante."],[0,"Lemon raspberry? That sounds interesting. I'm not a huge chocolate fan, to be honest.","¿Limón y frambuesa? Eso suena interesante. Para ser sincero, no soy muy fan del chocolate."],[1,"See? This is helpful! What if we did a tasting with a few different flavors? We could make it a fun afternoon.","¿Ves? ¡Esto ayuda! ¿Y si hacemos una degustación con algunos sabores diferentes? Podríamos pasar una tarde divertida."],[2,"That's a great idea! If we do that, we should also try some champagne.","¡Es una gran idea! Si hacemos eso, también deberíamos probar un poco de champán."],[3,"Definitely. And we haven't even talked about the music yet. Are you thinking a band or a DJ?","Definitivamente. Y ni siquiera hemos hablado de la música todavía. ¿Están pensando en una banda o un DJ?"],[0,"Oh man, music. A good DJ is probably more affordable, right?","Ay, la música. Un buen DJ es probablemente más económico, ¿verdad?"],[1,"Probably. I've always dreamed of a live band, but a great DJ could be just as good.","Probablemente. Siempre he soñado con una banda en vivo, pero un gran DJ podría ser igual de bueno."],[2,"Well, my cousin used a DJ who was fantastic. I can get his number for you.","Bueno, mi primo contrató a un DJ que fue fantástico. Puedo conseguirte su número."],[3,"And I know a great local band, just in case you want to compare. No pressure!","Y yo conozco una banda local genial, por si quieren comparar. ¡Sin presiones!"],[0,"Thanks, you guys are the best. I feel a little less stressed now.","Gracias, chicas, son las mejores. Ahora me siento un poco menos estresado."],[1,"Me too. Let's schedule that cake tasting for next weekend. It's a date!","Yo también. Agendemos esa degustación de pasteles para el próximo fin de semana. ¡Es una cita!"]]},{"id":"vb1-10","nivel":"B1","emoji":"🏝️","titulo":"Vacation Planning Problems","tituloEs":"Problemas para planear las vacaciones","personas":[{"nombre":"Kim","genero":"mujer","rol":"amiga del grupo"},{"nombre":"Cody","genero":"hombre","rol":"amigo del grupo"},{"nombre":"Trevor","genero":"hombre","rol":"amigo del grupo"}],"lineas":[[0,"Okay guys, we really need to decide on a vacation spot. I still think a beach trip would be perfect.","Bueno chicos, de verdad necesitamos decidir un lugar para las vacaciones. Sigo pensando que un viaje a la playa sería perfecto."],[1,"Ugh, not the beach again. I've already been to the beach twice this year. How about the mountains instead?","Uf, la playa de nuevo no. Ya he ido a la playa dos veces este año. ¿Qué tal las montañas en su lugar?"],[2,"The mountains? All we would do is walk. I was thinking of something more exciting, like a big city.","¿Las montañas? Todo lo que haríamos es caminar. Yo pensaba en algo más emocionante, como una gran ciudad."],[0,"A city could be fun! But some are really expensive. If we choose a big city, we'll have to find cheap hotels.","¡Una ciudad podría ser divertida! Pero algunas son muy caras. Si elegimos una ciudad grande, tendremos que encontrar hoteles baratos."],[1,"That's true. I haven't saved a lot of money. The beach is usually cheaper, you know.","Es verdad. No he ahorrado mucho dinero. La playa suele ser más barata, sabes."],[2,"Come on! We never do anything adventurous. I think we should go to New York City. It would be amazing!","¡Vamos! Nunca hacemos nada aventurero. Creo que deberíamos ir a la ciudad de Nueva York. ¡Sería increíble!"],[0,"I've never been to New York! Actually, that sounds really exciting. We could see a Broadway show.","¡Nunca he estado en Nueva York! De hecho, eso suena muy emocionante. Podríamos ver un show de Broadway."],[1,"Okay, I'm starting to like this idea. We can find affordable food, and we don't need to rent a car.","Vale, me empieza a gustar esta idea. Podemos encontrar comida asequible y no necesitamos alquilar un coche."],[2,"See? And think about Central Park. It's like having nature right in the middle of the city.","¿Ven? Y piensen en Central Park. Es como tener naturaleza justo en medio de la ciudad."],[0,"You're right. That's a great compromise. A city with a giant park is the best of both worlds.","Tienes razón. Es un excelente punto medio. Una ciudad con un parque gigante es lo mejor de ambos mundos."],[1,"So, have we finally decided? New York City for our vacation?","Entonces, ¿finalmente hemos decidido? ¿Nueva York para nuestras vacaciones?"],[2,"Yes! I'll start looking for flights and cool things to do. I'm so excited.","¡Sí! Empezaré a buscar vuelos y cosas geniales para hacer. Estoy muy emocionado."],[0,"Me too! This is going to be the best trip we've ever had.","¡Yo también! Este va a ser el mejor viaje que hemos tenido."],[1,"Awesome. Just promise me we'll find the best pizza place in the city.","Genial. Solo prométanme que encontraremos la mejor pizzería de la ciudad."]]},{"id":"vb1-11","nivel":"B1","emoji":"🎶","titulo":"A Friendly Noise Complaint","tituloEs":"Una Queja Amistosa por Ruido","personas":[{"nombre":"Brian","genero":"hombre","rol":"Vecino de abajo"},{"nombre":"Olivia","genero":"mujer","rol":"Vecina de arriba"}],"lineas":[[0,"Hi, Olivia? I'm Brian from downstairs. Sorry to bother you, do you have a minute?","Hola, ¿Olivia? Soy Brian, del piso de abajo. Disculpa que te moleste, ¿tienes un minuto?"],[1,"Oh, hi Brian! Not a bother at all. Sure, what's up?","¡Ah, hola Brian! No es ninguna molestia. Claro, ¿qué pasa?"],[0,"Well, this is a little awkward, but I wanted to ask about the music at night.","Bueno, esto es un poco incómodo, pero quería preguntarte sobre la música por la noche."],[1,"The music? Oh no, has it been too loud? I'm so sorry!","¿La música? ¡Oh no! ¿Ha estado muy fuerte? ¡Lo siento mucho!"],[0,"It's okay. It's just that I've noticed it's pretty loud some nights, especially the bass.","No te preocupes. Es solo que he notado que está bastante fuerte algunas noches, especialmente el bajo."],[1,"Oh, I had no idea! I've just gotten a new speaker and I guess I got carried away. I feel terrible.","¡Ay, no tenía idea! Acabo de comprar una bocina nueva y supongo que me emocioné. Me siento fatal."],[0,"No, no, don't feel terrible! The sound quality is great. It's mainly an issue after about 10 PM.","¡No, no, no te sientas mal! La calidad del sonido es genial. El problema es principalmente después de las 10 p.m."],[1,"Okay, that's good to know. If it's ever too loud, please just send me a text. I don't want to be a bad neighbor.","Ok, es bueno saberlo. Si alguna vez está muy fuerte, por favor, solo mándame un mensaje de texto. No quiero ser una mala vecina."],[0,"That's really nice of you, thanks. I appreciate you being so cool about it.","Qué amable de tu parte, gracias. Agradezco que te lo tomes tan bien."],[1,"Of course! I mean, we have to live together, right? I'll be much more careful with the volume.","¡Por supuesto! Digo, tenemos que convivir, ¿verdad? Tendré mucho más cuidado con el volumen."],[0,"Awesome, thank you so much, Olivia. I really appreciate it.","Genial, muchas gracias, Olivia. De verdad te lo agradezco."],[1,"Anytime. And sorry again for the noise. It won't happen again.","Cuando quieras. Y disculpa de nuevo por el ruido. No volverá a pasar."],[0,"Sounds good. Well, have a great night!","Perfecto. Bueno, ¡que pases una excelente noche!"],[1,"Thanks, you too! Bye.","Gracias, ¡tú también! Adiós."]]},{"id":"vb1-12","nivel":"B1","emoji":"🐾","titulo":"Volunteering at the Shelter","tituloEs":"Voluntariado en el refugio","personas":[{"nombre":"Claire","genero":"mujer","rol":"Voluntaria en un refugio"},{"nombre":"Eli","genero":"hombre","rol":"Amigo de Claire y Max"},{"nombre":"Max","genero":"hombre","rol":"Amigo de Claire y Eli"}],"lineas":[[0,"I just finished my shift at the animal shelter. I'm so tired but happy.","Acabo de terminar mi turno en el refugio de animales. Estoy muy cansada pero feliz."],[1,"Oh wow, how was it? Was it a lot of work?","Oh, vaya, ¿qué tal estuvo? ¿Fue mucho trabajo?"],[2,"I bet you just played with cute puppies all day!","¡Seguro que solo estuviste jugando con cachorritos monos todo el día!"],[0,"Ha! I wish. Actually, I spent most of the time cleaning cages. It's not glamorous.","¡Ja! Ojalá. En realidad, pasé la mayor parte del tiempo limpiando jaulas. No es glamuroso."],[1,"I can imagine. But you get to be around the animals, which must be nice.","Me lo imagino. Pero puedes estar cerca de los animales, lo cual debe ser agradable."],[2,"Have you seen that huge dog they posted online? The one that looks like a bear.","¿Has visto ese perro enorme que publicaron en internet? El que parece un oso."],[0,"Oh, Buster! Yes, he's a gentle giant. He just needs a lot of space and a loving home.","¡Ah, Buster! Sí, es un gigante bonachón. Solo necesita mucho espacio y un hogar cariñoso."],[1,"I've been thinking about volunteering there. Do you think I'd like it?","He estado pensando en ser voluntario allí. ¿Crees que me gustaría?"],[2,"If you volunteer, you have to get me a discount on a cat. I'm kidding... mostly.","Si te haces voluntario, tienes que conseguirme un descuento para un gato. Estoy bromeando... más o menos."],[0,"You should definitely try it, Eli. They always need more help, especially on weekends.","Definitivamente deberías intentarlo, Eli. Siempre necesitan más ayuda, sobre todo los fines de semana."],[1,"Okay, maybe I will. I'll look into it this week.","Vale, quizás lo haga. Lo investigaré esta semana."],[2,"Just be careful. You might come home with three dogs and a parrot.","Solo ten cuidado. Podrías volver a casa con tres perros y un loro."],[0,"It's a real risk! But honestly, it's the most rewarding thing I've done.","¡Es un riesgo real! Pero sinceramente, es la cosa más gratificante que he hecho."],[1,"That's good to hear. It sounds like it's totally worth it.","Qué bueno oír eso. Suena a que vale totalmente la pena."]]},{"id":"vb1-13","nivel":"B1","emoji":"💰","titulo":"Asking for a Raise","tituloEs":"Pedir un aumento de sueldo","personas":[{"nombre":"Rachel","genero":"mujer","rol":"Compañera de trabajo"},{"nombre":"Sam","genero":"hombre","rol":"Compañero de trabajo"}],"lineas":[[0,"Hey Sam, have you got a minute? I'm a little nervous about something.","Oye Sam, ¿tienes un minuto? Estoy un poco nerviosa por algo."],[1,"Sure, what's on your mind? You look worried.","Claro, ¿qué te pasa? Te ves preocupada."],[0,"Well, I've decided to talk to our boss this afternoon. I'm going to ask for a raise.","Bueno, he decidido hablar con nuestro jefe esta tarde. Voy a pedir un aumento de sueldo."],[1,"Wow, that's a big step! Good for you, Rachel.","¡Vaya, ese es un gran paso! Bien por ti, Rachel."],[0,"Thanks. I mean, I've been here for three years, and I think I've done a good job.","Gracias. O sea, he estado aquí por tres años, y creo que he hecho un buen trabajo."],[1,"You definitely have. Your work on the last project was fantastic.","Definitivamente lo has hecho. Tu trabajo en el último proyecto fue fantástico."],[0,"I hope he agrees. I've prepared a list of my achievements, just in case.","Espero que esté de acuerdo. He preparado una lista de mis logros, por si acaso."],[1,"That's a great idea. Just be confident and explain why you deserve it.","Esa es una gran idea. Solo ten confianza y explica por qué te lo mereces."],[0,"If I don't ask, I'll never know, right? It's just so nerve-wracking.","Si no pregunto, nunca lo sabré, ¿verdad? Es que es muy estresante."],[1,"Totally. But you've got this. You've been a key part of the team.","Totalmente. Pero tú puedes con esto. Has sido una pieza clave del equipo."],[0,"Hearing you say that actually helps a lot. Thanks for the support.","Escucharte decir eso de hecho ayuda mucho. Gracias por el apoyo."],[1,"Of course! What are coworkers for?","¡Por supuesto! ¿Para qué están los compañeros de trabajo?"],[0,"Okay, I'm feeling a bit more brave now. Wish me luck!","Bueno, me siento un poco más valiente ahora. ¡Deséame suerte!"],[1,"Good luck! Let me know how it goes. I'll be waiting for good news.","¡Buena suerte! Avísame cómo te va. Estaré esperando buenas noticias."]]},{"id":"vb1-14","nivel":"B1","emoji":"🎒","titulo":"Hostel Travel Stories","tituloEs":"Historias de viaje en el hostal","personas":[{"nombre":"Lily","genero":"mujer","rol":"Viajera"},{"nombre":"Danny","genero":"hombre","rol":"Viajero"},{"nombre":"Hannah","genero":"mujer","rol":"Viajera"},{"nombre":"Rachel","genero":"mujer","rol":"Viajera"}],"lineas":[[0,"So, what's the craziest thing that's happened to you guys while traveling?","Entonces, ¿qué es lo más loco que les ha pasado mientras viajan?"],[1,"Well, last year in Thailand, I accidentally got on the wrong bus. I ended up in a tiny village three hours away!","Bueno, el año pasado en Tailandia, me subí al autobús equivocado por accidente. ¡Terminé en un pueblito a tres horas de distancia!"],[2,"Oh no! I've never done that, but I once ordered something I thought was chicken. It was definitely not chicken.","¡Oh no! A mí nunca me ha pasado eso, pero una vez pedí algo que pensé que era pollo. Definitivamente no era pollo."],[3,"That's hilarious! For me, the best moments have been meeting local people. They've always been so kind.","¡Qué gracioso! Para mí, los mejores momentos han sido conocer a la gente local. Siempre han sido muy amables."],[0,"I agree. I've met some amazing people on this trip alone.","Estoy de acuerdo. He conocido a gente increíble solo en este viaje."],[1,"Yeah, me too. If I had more time, I would visit the family I met in Peru again.","Sí, yo también. Si tuviera más tiempo, visitaría de nuevo a la familia que conocí en Perú."],[2,"Oh, that's so sweet. I think it's the people that make a place special, not just the sights.","Oh, qué tierno. Creo que es la gente la que hace especial un lugar, no solo los monumentos."],[3,"Exactly! I mean, seeing the Eiffel Tower is cool, but sharing a meal with a Parisian family is better.","¡Exacto! O sea, ver la Torre Eiffel es genial, pero compartir una comida con una familia parisina es mejor."],[0,"Totally. You learn so much more about the culture that way.","Totalmente. Aprendes mucho más sobre la cultura de esa manera."],[1,"For sure. Actually, I got a recipe for a great curry from that village I got lost in.","Claro que sí. De hecho, conseguí una receta para un curry buenísimo en ese pueblo donde me perdí."],[2,"No way! You have to share it with us. I love a good curry.","¡No puede ser! Tienes que compartirla con nosotros. Me encanta un buen curry."],[3,"That sounds amazing. We should all cook dinner together tomorrow night!","¡Eso suena increíble! ¡Deberíamos cocinar la cena todos juntos mañana por la noche!"],[0,"That's a great idea! I'm in.","¡Es una gran idea! Yo me apunto."],[1,"Count me in! It'll be fun.","¡Cuenten conmigo! Será divertido."]]},{"id":"vb1-15","nivel":"B1","emoji":"📖","titulo":"Book Club Catch-up","tituloEs":"Puesta al día del club de lectura","personas":[{"nombre":"Mia","genero":"mujer","rol":"Miembro del club"},{"nombre":"Greg","genero":"hombre","rol":"Miembro del club"},{"nombre":"Jasmine","genero":"mujer","rol":"Miembro del club"},{"nombre":"Lauren","genero":"mujer","rol":"Miembro del club"}],"lineas":[[0,"Okay, so what did everyone think about the book? I've been excited to hear your thoughts.","Bueno, ¿qué les pareció a todos el libro? He estado ansiosa por escuchar sus opiniones."],[1,"Well, to be honest, I found the beginning a little slow. It took me a while to get into it.","Pues, para ser sincero, el principio me pareció un poco lento. Me costó un poco engancharme."],[2,"Really? I loved it from the first page! I think the author's descriptions were beautiful.","¿En serio? ¡A mí me encantó desde la primera página! Creo que las descripciones de la autora eran preciosas."],[3,"I agree with you, Jasmine. And that twist at the end? I totally didn't see it coming!","Estoy de acuerdo contigo, Jasmine. ¿Y ese giro en el final? ¡No me lo vi venir para nada!"],[0,"The ending was definitely surprising. If I had known it was a mystery, I would have paid more attention to the clues.","El final fue definitivamente sorprendente. Si hubiera sabido que era un misterio, habría prestado más atención a las pistas."],[1,"I just couldn't stand the main character's brother. He was so annoying!","Es que no soportaba al hermano del personaje principal. ¡Era tan fastidioso!"],[2,"Ha! I know what you mean, but I think he was supposed to be like that. He made things more interesting.","¡Ja! Sé a qué te refieres, pero creo que se suponía que debía ser así. Hizo las cosas más interesantes."],[3,"Speaking of interesting, have you guys heard of \"City of Echoes\"? I think we should read it next.","Hablando de interesante, ¿han oído hablar de \"Ciudad de Ecos\"? Creo que deberíamos leerlo después."],[0,"Oh, I haven't heard of that one. What's it about?","Ah, no he oído hablar de ese. ¿De qué se trata?"],[1,"I've seen that book everywhere! Yes, let's do it. I'm ready for something new.","¡He visto ese libro por todas partes! Sí, hagámoslo. Estoy listo para algo nuevo."],[2,"Sounds good to me. A friend of mine said it's a real page-turner.","Me parece bien. Una amiga mía dijo que es un libro que de verdad te atrapa."],[3,"It's a sci-fi thriller. I think you'll like it, Greg, it's very fast-paced from the start.","Es un thriller de ciencia ficción. Creo que te gustará, Greg, tiene mucho ritmo desde el principio."],[0,"Alright, \"City of Echoes\" it is, then! I'll send an email to confirm.","¡Está bien, entonces será \"Ciudad de Ecos\"! Enviaré un correo para confirmar."],[1,"Great! As long as there are no annoying brothers in it, I'm happy.","¡Genial! Mientras no haya hermanos fastidiosos, yo feliz."]]},{"id":"vb1-16","nivel":"B1","emoji":"📱","titulo":"Online Dating Stories","tituloEs":"Historias de citas por internet","personas":[{"nombre":"Mia","genero":"mujer","rol":"amiga de Ryan y Liam"},{"nombre":"Ryan","genero":"hombre","rol":"amigo de Mia y Liam"},{"nombre":"Liam","genero":"hombre","rol":"amigo de Mia y Ryan"}],"lineas":[[0,"So, any interesting online dating stories recently? I feel like I've heard everything.","Y bueno, ¿alguna historia interesante de citas por internet últimamente? Siento que ya he oído de todo."],[1,"Oh, you have no idea. I went on a date last week, and the girl only talked about her twenty cats.","Oh, no tienes ni idea. Tuve una cita la semana pasada y la chica solo hablaba de sus veinte gatos."],[2,"Twenty cats? Seriously? That's a lot. Was she nice otherwise?","¿Veinte gatos? ¿En serio? Son muchísimos. ¿Aparte de eso, era simpática?"],[0,"I mean, you have to really love cats for that. Did you see any pictures of them?","O sea, te tienen que gustar mucho los gatos para eso. ¿Viste alguna foto de ellos?"],[1,"Yes, she showed me a slideshow for 30 minutes. It was... something. I don't think I'll see her again.","Sí, me mostró una presentación de 30 minutos. Fue... algo. No creo que la vuelva a ver."],[2,"Well, at least she was honest! My last date looked nothing like her profile picture. It was really awkward.","Bueno, ¡al menos fue honesta! Mi última cita no se parecía en nada a su foto de perfil. Fue muy incómodo."],[0,"Oh no, that's the worst! I've had that happen too. It's so disappointing.","¡Ay no, eso es lo peor! A mí también me ha pasado. Es tan decepcionante."],[1,"Exactly! If I had known she looked so different, I probably wouldn't have gone.","¡Exacto! Si hubiera sabido que se veía tan diferente, probablemente no habría ido."],[2,"Right? It just feels like they're lying from the very beginning, you know?","¿Verdad? Simplemente se siente como si estuvieran mintiendo desde el principio, ¿sabes?"],[0,"Totally. But I've also met some really great people online. You just never know.","Totalmente. Pero también he conocido a gente muy genial en línea. Simplemente nunca se sabe."],[1,"That's true. My friend actually met his wife on a dating app.","Es verdad. De hecho, mi amigo conoció a su esposa en una aplicación de citas."],[2,"Yeah, it's a lottery, I guess. You win some, you lose some.","Sí, es una lotería, supongo. A veces se gana, a veces se pierde."],[0,"For sure. So, Ryan, are you going on any more dates this week?","Seguro. Y tú, Ryan, ¿tienes más citas esta semana?"],[1,"Haha, maybe. But I'll check for cat photos on their profile first!","Jaja, tal vez. ¡Pero primero revisaré si hay fotos de gatos en su perfil!"]]},{"id":"vb1-17","nivel":"B1","emoji":"🛫","titulo":"Canceled Flight at the Gate","tituloEs":"Vuelo cancelado en la puerta de embarque","personas":[{"nombre":"Denise","genero":"mujer","rol":"Pasajera"},{"nombre":"Marcus","genero":"hombre","rol":"Otro pasajero"},{"nombre":"Amber","genero":"mujer","rol":"Otra pasajera"}],"lineas":[[0,"You have got to be kidding me. Canceled? Just like that?","Tienes que estar bromeando. ¿Cancelado? ¿Así sin más?"],[1,"I know, right? I've been waiting here for three hours. I can't believe this.","Ya sé, ¿verdad? He estado esperando aquí por tres horas. No puedo creer esto."],[2,"Well, look on the bright side. At least we're not stuck on the plane.","Bueno, miren el lado positivo. Al menos no estamos atrapados en el avión."],[0,"That's true. So, what's the plan now? Do we just wait in another long line?","Es verdad. Entonces, ¿cuál es el plan ahora? ¿Simplemente esperamos en otra fila larga?"],[1,"I guess so. They said they'll rebook us. If I had known this would happen, I would've taken the train.","Supongo que sí. Dijeron que nos darán otro vuelo. Si hubiera sabido que esto pasaría, habría tomado el tren."],[2,"The train? That would've taken forever! I'm going to see if they'll give us a hotel voucher.","¿El tren? ¡Eso habría tardado una eternidad! Voy a ver si nos dan un cupón para un hotel."],[0,"That's a great idea. I haven't even thought about where to stay tonight.","Esa es una gran idea. Ni siquiera he pensado dónde quedarme esta noche."],[1,"Me neither. This whole situation is a mess. I just want to get home.","Yo tampoco. Toda esta situación es un desastre. Solo quiero llegar a casa."],[2,"I know. But hey, we're all in the same boat. Maybe we can find a decent airport restaurant?","Lo sé. Pero oigan, estamos todos en la misma situación. ¿Quizás podamos encontrar un restaurante decente en el aeropuerto?"],[0,"You know what? I could really use a coffee right now. Or something stronger.","¿Sabes qué? Me vendría muy bien un café ahora mismo. O algo más fuerte."],[1,"I'm with you on that. Let's go find that customer service desk together.","Estoy de acuerdo contigo. Vayamos a buscar ese mostrador de atención al cliente juntos."],[2,"Sounds like a plan. It's an unexpected adventure, I guess!","Suena como un plan. ¡Es una aventura inesperada, supongo!"],[0,"Haha, 'adventure' is one word for it. Okay, let's do it.","Jaja, 'aventura' es una forma de decirlo. De acuerdo, hagámoslo."],[1,"After you. Maybe if we all go together, they'll listen to us.","Después de ustedes. Quizás si vamos todos juntos, nos hagan caso."]]},{"id":"vb1-18","nivel":"B1","emoji":"🧁","titulo":"Starting a Small Business","tituloEs":"Empezar un pequeño negocio","personas":[{"nombre":"Tasha","genero":"mujer","rol":"amiga y socia potencial"},{"nombre":"Tyler","genero":"hombre","rol":"amigo y socio potencial"}],"lineas":[[0,"Hey, I've been thinking a lot lately. We should totally start a small business together.","Oye, he estado pensando mucho últimamente. Deberíamos totalmente empezar un pequeño negocio juntos."],[1,"A business? Seriously? What have you been dreaming up?","¿Un negocio? ¿En serio? ¿Y qué has estado soñando?"],[0,"Well, everyone loves your baking. We could sell your famous cookies online!","Bueno, a todo el mundo le encanta cómo horneas. ¡Podríamos vender tus famosas galletas por internet!"],[1,"My cookies? I've never thought of them as a business. I just make them for fun.","¿Mis galletas? Nunca he pensado en ellas como un negocio. Solo las hago por diversión."],[0,"Exactly! And they're amazing. If we created a cool brand, I bet we'd be successful.","¡Exacto! Y son increíbles. Si creáramos una marca genial, apuesto a que tendríamos éxito."],[1,"Hmm, I don't know, Tasha. It sounds like a lot of work and a big risk.","Hmm, no lo sé, Tasha. Suena como mucho trabajo y un gran riesgo."],[0,"It could be, but think about it! You'd be the baker, and I could manage the website and sales.","Podría ser, ¡pero piénsalo! Tú serías el panadero y yo podría encargarme de la página web y las ventas."],[1,"You've really put some thought into this, haven't you?","Realmente has pensado en esto, ¿verdad?"],[0,"Of course! I've already been looking at logos. I'm telling you, it's a great idea.","¡Por supuesto! Ya he estado mirando logos. Te digo que es una gran idea."],[1,"Okay, I admit it's a little exciting. What would we even call it?","Vale, admito que es un poco emocionante. ¿Cómo lo llamaríamos siquiera?"],[0,"I was thinking something like 'The Cookie Corner' or 'Tyler's Treats.' Simple and catchy!","Estaba pensando en algo como \"El Rincón de la Galleta\" o \"Los Dulces de Tyler\". ¡Simple y pegadizo!"],[1,"'Tyler's Treats'... I kind of like the sound of that. It would be cool to be my own boss.","\"Los Dulces de Tyler\"... Me gusta cómo suena. Sería genial ser mi propio jefe."],[0,"See? I knew you'd like the idea! We would be a perfect team.","¿Ves? ¡Sabía que te gustaría la idea! Seríamos un equipo perfecto."],[1,"Alright, don't get ahead of yourself. But... maybe you can tell me more about your plan.","Está bien, no te adelantes. Pero... quizás puedas contarme más sobre tu plan."]]},{"id":"vb1-19","nivel":"B1","emoji":"📵","titulo":"The Smartphone Situation","tituloEs":"La situación del smartphone","personas":[{"nombre":"Omar","genero":"hombre","rol":"Padre"},{"nombre":"Denise","genero":"mujer","rol":"Madre"}],"lineas":[[0,"Hey, have you seen our son lately? It's been so quiet in the house.","Oye, ¿has visto a nuestro hijo últimamente? Ha estado tan silencioso en la casa."],[1,"He's in his room, of course. He has been looking at his phone for two hours straight.","Está en su cuarto, por supuesto. Lleva dos horas seguidas mirando el celular."],[0,"Two hours? Wow. I wonder what's so interesting on that tiny screen.","¿Dos horas? Guau. Me pregunto qué será tan interesante en esa pantallita."],[1,"I'm a little worried, honestly. He spends more time with his phone than with us.","Sinceramente, estoy un poco preocupada. Pasa más tiempo con su celular que con nosotros."],[0,"I know what you mean. But all his friends are the same way, aren't they?","Sé a qué te refieres. Pero todos sus amigos son así, ¿no?"],[1,"Maybe, but I think we should set some limits. It's becoming a bit much.","Quizás, pero creo que deberíamos poner algunos límites. Se está volviendo un poco excesivo."],[0,"What kind of limits? If we're too strict, he'll just get angry.","¿Qué tipo de límites? Si somos demasiado estrictos, simplemente se enojará."],[1,"Well, for starters, no phones at the dinner table. I think that's fair.","Bueno, para empezar, nada de celulares en la mesa a la hora de cenar. Creo que eso es justo."],[0,"That's a great idea, actually. It would be nice to have a real conversation for a change.","De hecho, es una gran idea. Estaría bien tener una conversación de verdad para variar."],[1,"I agree. And maybe he should finish his homework before he gets his phone.","Estoy de acuerdo. Y quizás debería terminar su tarea antes de recibir su celular."],[0,"Yes, definitely. Schoolwork must come first. That's non-negotiable.","Sí, definitivamente. Los deberes tienen que ser lo primero. Eso no es negociable."],[1,"Okay, so we're on the same page. We'll talk to him together this evening.","Vale, entonces estamos en la misma sintonía. Hablaremos con él juntos esta noche."],[0,"Sounds like a plan. Now, what about our own screen time?","Suena como un plan. Ahora, ¿qué hay de nuestro propio tiempo en pantalla?"],[1,"Hey, one problem at a time! But... you do have a point.","¡Oye, un problema a la vez! Pero... tienes razón."]]},{"id":"vb1-20","nivel":"B1","emoji":"🧠","titulo":"Trivia Night at the Pub","tituloEs":"Noche de trivia en el pub","personas":[{"nombre":"Jasmine","genero":"mujer","rol":"Amiga del grupo"},{"nombre":"Jacob","genero":"hombre","rol":"Amigo del grupo"},{"nombre":"Zoe","genero":"mujer","rol":"Amiga del grupo"},{"nombre":"Sam","genero":"hombre","rol":"Amigo del grupo"}],"lineas":[[0,"Wow, that last round was brutal. The history questions were so hard.","Wow, esa última ronda fue brutal. Las preguntas de historia estuvieron muy difíciles."],[1,"Tell me about it. I've never felt so clueless about a topic in my life.","Ni me digas. Nunca me he sentido tan perdido con un tema en mi vida."],[2,"Well, at least it's over. I think the next category is movies. We should be better at that.","Bueno, al menos ya se acabó. Creo que la siguiente categoría es de películas. Deberíamos ser mejores en eso."],[3,"I hope so. If we get another round like that, we're definitely not winning any free drinks.","Eso espero. Si nos toca otra ronda así, definitivamente no vamos a ganar ninguna bebida gratis."],[0,"Okay, listen to this one: \"Who directed the movie 'Pulp Fiction'?\" Oh, I know this!","Ok, escuchen esta: \"¿Quién dirigió la película 'Pulp Fiction'?\" ¡Ah, esta me la sé!"],[1,"It's that famous guy... it's on the tip of my tongue. He has a really unique style.","Es ese tipo famoso... lo tengo en la punta de la lengua. Tiene un estilo muy particular."],[2,"I think I know it too! Let me think... Is it Martin Scorsese?","¡Creo que yo también lo sé! Déjame pensar... ¿Es Martin Scorsese?"],[3,"No, not Scorsese. It's Quentin Tarantino. I'm a hundred percent sure about that one.","No, no es Scorsese. Es Quentin Tarantino. Estoy cien por ciento seguro de esa."],[0,"Yes, that's it! Quentin Tarantino. Great job, Sam! Let's write that down quickly.","¡Sí, es él! Quentin Tarantino. ¡Bien hecho, Sam! Anotémoslo rápido."],[1,"Phew, you really saved us. I wouldn't have remembered his name.","Uf, de verdad nos salvaste. Yo no habría recordado su nombre."],[2,"See? I told you we'd be good at the movie round. We've already gotten one right!","¿Ven? Les dije que seríamos buenos en la ronda de películas. ¡Ya acertamos una!"],[3,"We just need to keep this momentum going. What's the next one?","Solo necesitamos mantener este impulso. ¿Cuál es la siguiente?"],[0,"It's about actors... \"Which actor has won the most Oscars?\"","Es sobre actores... \"¿Qué actor ha ganado la mayor cantidad de premios Óscar?\""],[1,"Oh, I think I read about this recently. Isn't it Daniel Day-Lewis?","Ah, creo que leí sobre esto hace poco. ¿No es Daniel Day-Lewis?"],[2,"He has won a lot, but I'm not sure if he's the one with the most.","Él ha ganado muchos, pero no estoy segura si es el que más tiene."],[3,"Actually, the record for an actor is three, which he shares. But the overall record for acting is Katharine Hepburn with four.","De hecho, el récord para un actor es de tres, que él comparte. Pero el récord general de actuación es de Katharine Hepburn con cuatro."]]},{"id":"vb1-21","nivel":"B1","emoji":"🥾","titulo":"Lost on the Hiking Trail","tituloEs":"Perdidos en la ruta de senderismo","personas":[{"nombre":"Maya","genero":"mujer","rol":"Amiga y excursionista"},{"nombre":"Omar","genero":"hombre","rol":"Amigo y excursionista"},{"nombre":"Vanessa","genero":"mujer","rol":"Amiga y excursionista"}],"lineas":[[0,"Guys, I'm a little worried. I think we might be lost.","Chicos, estoy un poco preocupada. Creo que podríamos estar perdidos."],[1,"Don't worry. I'm pretty sure the car is this way. Let me just check the GPS.","No te preocupes. Estoy casi seguro de que el auto está por aquí. Déjame revisar el GPS."],[2,"I haven't had any phone signal for the last thirty minutes. Have you?","No he tenido señal en el celular en los últimos treinta minutos. ¿Ustedes sí?"],[0,"No, nothing. My map app won't load. We've walked for a long time.","No, nada. Mi aplicación de mapas no carga. Hemos caminado por mucho tiempo."],[1,"Oh. Well, it seems my phone's battery has just died. That's not helpful.","Ah. Bueno, parece que la batería de mi teléfono se acaba de morir. Eso no ayuda."],[2,"You think? We really should have brought a paper map, you know.","¿Tú crees? De verdad deberíamos haber traído un mapa de papel, sabes."],[0,"Okay, let's not argue. If we follow this stream, it should lead downhill, right?","Bueno, no discutamos. Si seguimos este arroyo, debería llevarnos cuesta abajo, ¿verdad?"],[1,"That's a great idea! I remember the parking lot was near a little bridge.","¡Es una gran idea! Recuerdo que el estacionamiento estaba cerca de un pequeño puente."],[2,"A stream! I'm so thirsty. I drank all my water an hour ago.","¡Un arroyo! Tengo muchísima sed. Me bebí toda el agua hace una hora."],[0,"Here, you can have some of mine. We need to stick together.","Ten, puedes tomar de la mía. Necesitamos permanecer juntos."],[1,"Yeah, we're a team. A slightly lost team, but a team.","Sí, somos un equipo. Un equipo un poco perdido, pero un equipo."],[2,"Thanks, Maya. I'm sorry, I'm just getting hungry and tired.","Gracias, Maya. Lo siento, es que ya me está dando hambre y cansancio."],[0,"I know, me too. Let's start walking. I'm dreaming of a giant cheeseburger.","Lo sé, yo también. Empecemos a caminar. Estoy soñando con una hamburguesa gigante con queso."],[1,"Okay, but I get to choose the restaurant! Let's go.","¡De acuerdo, pero yo elijo el restaurante! Vamos."]]},{"id":"vb1-22","nivel":"B1","emoji":"🚙","titulo":"Buying a Used Car","tituloEs":"Comprando un carro usado","personas":[{"nombre":"Jacob","genero":"hombre","rol":"Comprador de carro"},{"nombre":"Amber","genero":"mujer","rol":"Amiga del comprador"}],"lineas":[[0,"So, what do you think of this one? I think it looks pretty good for the price.","Y bien, ¿qué piensas de este? Creo que se ve bastante bien para el precio."],[1,"Hmm, it's okay. But have you checked the mileage? It seems a little high to me.","Mmm, está bien. ¿Pero has revisado el millaje? Me parece un poco alto."],[0,"Yeah, a little. But the seller said he's willing to negotiate. And I love this blue color!","Sí, un poco. Pero el vendedor dijo que está dispuesto a negociar. ¡Y me encanta este color azul!"],[1,"You can't buy a car just for the color, Jacob! Have you taken it for a test drive yet?","¡No puedes comprar un carro solo por el color, Jacob! ¿Ya lo has manejado para probarlo?"],[0,"Not yet. I haven't even asked for the keys. I wanted you to see it first.","Todavía no. Ni siquiera he pedido las llaves. Quería que lo vieras primero."],[1,"Well, that was smart. If the engine sounds good, it could be a great deal.","Bueno, eso fue inteligente. Si el motor suena bien, podría ser una gran oferta."],[0,"I hope so. I've been searching for a reliable car for almost three months now.","Eso espero. He estado buscando un carro confiable por casi tres meses ya."],[1,"I know. Did you ask about the car's history? I mean, any accidents?","Lo sé. ¿Preguntaste sobre el historial del carro? O sea, ¿algún accidente?"],[0,"Yes, he said it's had only one owner and no accidents at all. That's a good sign, right?","Sí, dijo que ha tenido un solo dueño y ningún accidente. Eso es una buena señal, ¿verdad?"],[1,"Definitely. And what about maintenance? Has he kept the service records?","Definitivamente. ¿Y qué hay del mantenimiento? ¿Ha guardado los registros de servicio?"],[0,"Actually, yes. He has a whole folder with receipts. It looks like he took really good care of it.","De hecho, sí. Tiene una carpeta entera con recibos. Parece que lo cuidó muy bien."],[1,"Okay, I'm impressed. Now I'm actually getting a little excited for you.","Ok, estoy impresionada. Ahora de hecho me estoy emocionando un poco por ti."],[0,"See? So, if the test drive goes well, I think I'll make an offer.","¿Ves? Entonces, si la prueba de manejo va bien, creo que haré una oferta."],[1,"Sounds like a plan. Just remember to start with a lower price. Good luck!","Suena como un plan. Solo recuerda empezar con un precio más bajo. ¡Buena suerte!"]]},{"id":"vb1-23","nivel":"B1","emoji":"🦃","titulo":"Thanksgiving Dinner Surprise","tituloEs":"La Sorpresa de la Cena de Acción de Gracias","personas":[{"nombre":"Nicole","genero":"mujer","rol":"invitada"},{"nombre":"Andre","genero":"hombre","rol":"anfitrión"},{"nombre":"Nate","genero":"hombre","rol":"invitado"},{"nombre":"Emma","genero":"mujer","rol":"invitada"}],"lineas":[[0,"Wow, everything looks incredible! I don't know where to start.","¡Guau, todo se ve increíble! No sé por dónde empezar."],[1,"Well, you have to try the sweet potato casserole. It's my mom's famous recipe.","Bueno, tienes que probar la cazuela de camote. Es la famosa receta de mi mamá."],[2,"Is that the one with marshmallows? I've heard about it but I've never tried it.","¿Esa es la que tiene malvaviscos? He oído de ella pero nunca la he probado."],[3,"Yes! It's the best part of Thanksgiving, I think. It's so good.","¡Sí! Es la mejor parte de Acción de Gracias, yo creo. Es tan buena."],[0,"Marshmallows on potatoes? That sounds a little strange, actually.","¿Malvaviscos sobre papas? Eso suena un poco raro, la verdad."],[1,"I know it sounds weird, but trust me. If you try it, you won't regret it.","Sé que suena extraño, pero confía en mí. Si la pruebas, no te arrepentirás."],[2,"I'm going for it. My plate is already full, but I'll make some room.","Voy a probarla. Mi plato ya está lleno, pero le haré un espacio."],[3,"I've already had two servings. Andre, you have to ask your mom for the recipe for me!","Yo ya me serví dos porciones. ¡Andre, tienes que pedirle la receta a tu mamá para mí!"],[0,"Okay, okay, you've all convinced me. I'll take a small piece.","Está bien, está bien, me convencieron. Tomaré un pedazo pequeño."],[1,"That's the spirit! So, what do you think of it?","¡Esa es la actitud! Y bien, ¿qué te parece?"],[2,"Oh wow. This is surprisingly amazing. I get it now.","Oh, guau. Esto es sorprendentemente increíble. Ahora lo entiendo."],[3,"See? It's impossible not to love it. It makes me so happy.","¿Ves? Es imposible no amarla. Me hace tan feliz."],[0,"Mmm, you were right. This is delicious! I'm so glad I tried it.","Mmm, tenías razón. ¡Esto está delicioso! Qué bueno que lo probé."],[1,"I told you! I'm just thankful everyone is enjoying the food.","¡Te lo dije! Solo estoy agradecido de que todos estén disfrutando la comida."],[2,"And we're thankful you invited us! Happy Thanksgiving, everyone.","¡Y nosotros estamos agradecidos de que nos invitaras! Feliz Día de Acción de Gracias a todos."],[3,"Happy Thanksgiving! To friends and good food.","¡Feliz Día de Acción de Gracias! Por los amigos y la buena comida."]]},{"id":"vb1-24","nivel":"B1","emoji":"🥜","titulo":"Wrong Order and an Allergy","tituloEs":"Pedido equivocado y una alergia","personas":[{"nombre":"Ava","genero":"mujer","rol":"amiga de Eli"},{"nombre":"Eli","genero":"hombre","rol":"cliente en el restaurante"},{"nombre":"Sam","genero":"hombre","rol":"mesero"}],"lineas":[[0,"Mmm, this pasta looks amazing. How's your burger, Eli?","Mmm, esta pasta se ve increíble. ¿Qué tal tu hamburguesa, Eli?"],[1,"Well, actually, I ordered the chicken sandwich. This looks like a beef burger.","Bueno, en realidad, pedí el sándwich de pollo. Esto parece una hamburguesa de res."],[2,"Is everything okay over here?","¿Está todo bien por aquí?"],[0,"Oh, perfect timing. I think there might be a little mix-up with his order.","Oh, justo a tiempo. Creo que podría haber una pequeña confusión con su pedido."],[1,"Yeah, hi. I ordered the grilled chicken sandwich. And also, does this have nuts? I have a serious nut allergy.","Sí, hola. Pedí el sándwich de pollo a la parrilla. Y además, ¿esto tiene frutos secos? Tengo una alergia grave a los frutos secos."],[2,"Oh my gosh, I am so sorry. Let me check. The burger sauce does contain peanuts.","Ay, Dios mío, lo siento mucho. Déjeme revisar. La salsa de la hamburguesa sí contiene maní."],[0,"Wow, that was a close call. It's a good thing you haven't touched it.","Wow, eso estuvo cerca. Menos mal que no lo has tocado."],[1,"Definitely. I would have been really sick if I'd eaten that.","Totalmente. Me habría puesto muy mal si hubiera comido eso."],[2,"I am terribly sorry for the mistake. I'll get you the correct chicken sandwich right away, with no nuts, of course.","Lamento muchísimo el error. Le traeré el sándwich de pollo correcto de inmediato, sin frutos secos, por supuesto."],[0,"He’d also like extra fries, I bet!","¡Apuesto a que también quiere papas fritas extra!"],[1,"Haha, she's not wrong. But seriously, just the sandwich is fine. Thank you.","Jaja, no se equivoca. Pero en serio, solo el sándwich está bien. Gracias."],[2,"Of course. It will be out in just a few minutes. Again, my apologies.","Por supuesto. Saldrá en solo unos minutos. De nuevo, mis disculpas."],[0,"No problem. Thanks for fixing it so quickly.","No hay problema. Gracias por solucionarlo tan rápido."],[1,"Yeah, thank you so much.","Sí, muchas gracias."]]},{"id":"vb1-25","nivel":"B1","emoji":"🛏️","titulo":"The Roommate Dish Dispute","tituloEs":"La disputa de los platos entre compañeros de cuarto","personas":[{"nombre":"Brian","genero":"hombre","rol":"compañero de cuarto"},{"nombre":"Zoe","genero":"mujer","rol":"compañera de cuarto"}],"lineas":[[0,"Hey Zoe, can we talk for a second? It's about the kitchen.","Oye Zoe, ¿podemos hablar un segundo? Es sobre la cocina."],[1,"Sure, what's up? Is everything okay?","Claro, ¿qué pasa? ¿Está todo bien?"],[0,"Well, it's just that the sink has been full of dirty dishes for two days. I couldn't even make breakfast this morning.","Bueno, es que el fregadero ha estado lleno de platos sucios por dos días. Ni siquiera pude preparar el desayuno esta mañana."],[1,"Oh, I know. I'm really sorry about that. I've been so busy with my final project.","Ay, lo sé. Lo siento mucho por eso. He estado tan ocupada con mi proyecto final."],[0,"I understand, but we agreed that we would wash our own dishes right away. It's a bit gross, you know?","Lo entiendo, pero acordamos que lavaríamos nuestros propios platos de inmediato. Es un poco asqueroso, ¿sabes?"],[1,"You're totally right. It's my fault. I promise it won't happen again.","Tienes toda la razón. Es mi culpa. Prometo que no volverá a pasar."],[0,"Okay, thank you. I mean, if we don't keep the place clean, it becomes a problem for both of us.","Okay, gracias. O sea, si no mantenemos el lugar limpio, se convierte en un problema para los dos."],[1,"I know. Look, I'll wash everything right now. And I'll buy us pizza tonight to make it up to you.","Lo sé. Mira, lavaré todo ahora mismo. Y compraré pizza para nosotros esta noche para compensarte."],[0,"Pizza? Okay, you are officially forgiven! Do you need a hand with those?","¿Pizza? ¡Ok, estás oficialmente perdonada! ¿Necesitas una mano con eso?"],[1,"No, I've got it. But thanks for offering. And thanks for bringing it up nicely.","No, yo me encargo. Pero gracias por ofrecerte. Y gracias por mencionarlo amablemente."],[0,"Of course. It would be worse if I just got angry and didn't say anything.","Por supuesto. Sería peor si solo me enojara y no dijera nada."],[1,"I agree. Communication is important! All right, let me get started on this mess.","Estoy de acuerdo. ¡La comunicación es importante! Muy bien, déjame empezar con este desastre."],[0,"Sounds good. I'll be in my room studying. Let me know about the pizza!","Suena bien. Estaré en mi cuarto estudiando. ¡Avísame sobre la pizza!"],[1,"Will do! Thanks for being a cool roommate about it.","¡Lo haré! Gracias por ser un buen compañero de cuarto al respecto."]]},{"id":"vb1-26","nivel":"B1","emoji":"🚚","titulo":"Moving Day Madness","tituloEs":"La locura del día de la mudanza","personas":[{"nombre":"Kevin","genero":"hombre","rol":"Amigo que ayuda"},{"nombre":"Maya","genero":"mujer","rol":"La que se muda"},{"nombre":"Zoe","genero":"mujer","rol":"Amiga que ayuda"}],"lineas":[[0,"Wow, Maya. I've never seen so many boxes. Where did all this stuff come from?","Vaya, Maya. Nunca he visto tantas cajas. ¿De dónde salieron todas estas cosas?"],[1,"I know, it's crazy! I think I might be a secret hoarder. Could you give me a hand with this one?","¡Lo sé, es una locura! Creo que podría ser una acumuladora secreta. ¿Me puedes echar una mano con esta?"],[2,"What's in it? If it's more books, I might just sit down and cry. My back is killing me.","¿Qué hay adentro? Si son más libros, puede que me siente a llorar. La espalda me está matando."],[0,"It feels like books. Don't worry, we can take a break soon. Let's move the couch first.","Parecen libros. No te preocupes, podemos tomar un descanso pronto. Movamos el sofá primero."],[1,"Oh, that's a great idea. It's the biggest piece. Let's get it out of the way.","Oh, es una gran idea. Es el mueble más grande. Saquémoslo de en medio."],[2,"Okay, but where does it go? I really hope it fits through the new doorway.","Vale, ¿pero a dónde va? De verdad espero que quepa por la puerta nueva."],[0,"It should. I've already measured everything. It'll be a tight squeeze, but we can do it.","Debería. Ya lo he medido todo. Va a estar muy justo, pero podemos lograrlo."],[1,"See? This is why you're the moving-day manager. I would be so stressed without you guys.","¿Ves? Por esto eres el gerente de la mudanza. Estaría tan estresada sin ustedes."],[2,"He's the manager, and I'm the muscle. We deserve a good reward for this.","Él es el gerente y yo soy la fuerza. Merecemos una buena recompensa por esto."],[0,"I agree. I'm thinking about a large pepperoni pizza. How does that sound?","Estoy de acuerdo. Estoy pensando en una pizza grande de pepperoni. ¿Qué les parece?"],[1,"It sounds perfect! You guys can have whatever you want. It's on me.","¡Suena perfecto! Pueden pedir lo que quieran. Invito yo."],[2,"Yes! Okay, now I'm motivated. Let's move this couch.","¡Sí! Vale, ahora estoy motivada. Vamos a mover este sofá."],[0,"Alright, on the count of three. One... two... three!","Muy bien, a la cuenta de tres. ¡Una... dos... y tres!"],[1,"We did it! It's in! You guys are officially the best friends ever.","¡Lo logramos! ¡Ya entró! Oficialmente son los mejores amigos del mundo."],[2,"We know. Now, about that pizza... should I look up the menu?","Lo sabemos. Ahora, sobre esa pizza... ¿voy buscando el menú?"]]},{"id":"vb1-27","nivel":"B1","emoji":"🎙️","titulo":"Simple Healthy Habits","tituloEs":"Hábitos saludables simples","personas":[{"nombre":"Nora","genero":"mujer","rol":"presentadora"},{"nombre":"Sam","genero":"hombre","rol":"experto en fitness"}],"lineas":[[0,"Welcome back! Today we're with Sam, a fitness expert. Thanks for being here.","¡Bienvenidos de vuelta! Hoy estamos con Sam, un experto en fitness. Gracias por estar aquí."],[1,"Thanks for having me, Nora. I'm happy to be here.","Gracias por invitarme, Nora. Estoy feliz de estar aquí."],[0,"So, what's one simple healthy habit people can start?","Entonces, ¿cuál es un hábito saludable y simple que la gente puede empezar?"],[1,"Well, a great one is just drinking more water. It sounds simple, but it makes a huge difference.","Bueno, uno genial es simplemente beber más agua. Suena simple, pero hace una gran diferencia."],[0,"I've heard that before. I always try, but I forget to drink enough.","He oído eso antes. Siempre lo intento, pero me olvido de beber lo suficiente."],[1,"I understand. If you carry a reusable water bottle, you'll probably drink more.","Entiendo. Si llevas una botella de agua reutilizable, probablemente beberás más."],[0,"That's a good idea. What about exercise? I don't have a lot of time.","Es una buena idea. ¿Y qué hay del ejercicio? No tengo mucho tiempo."],[1,"You don't need to go to the gym for an hour. Even a 15-minute walk is fantastic.","No necesitas ir al gimnasio por una hora. Incluso una caminata de 15 minutos es fantástica."],[0,"Only 15 minutes? I could totally do that on my lunch break.","¿Solo 15 minutos? Totalmente podría hacer eso en mi hora de almuerzo."],[1,"Exactly! It's more about consistency than intensity.","¡Exacto! Se trata más de la constancia que de la intensidad."],[0,"That's interesting. I've always thought I needed to do long workouts.","Qué interesante. Siempre he pensado que necesitaba hacer entrenamientos largos."],[1,"Actually, if you start small, you're more likely to continue the habit.","De hecho, si empiezas con poco, es más probable que continúes con el hábito."],[0,"This has been really helpful. I feel more motivated already!","Esto ha sido de mucha ayuda. ¡Ya me siento más motivada!"],[1,"I'm glad to hear that! The most important thing is just to start.","¡Me alegra oír eso! Lo más importante es simplemente empezar."]]},{"id":"vb1-28","nivel":"B1","emoji":"🎤","titulo":"Sold Out Concert Blues","tituloEs":"Tristeza por boletos agotados","personas":[{"nombre":"Kim","genero":"mujer","rol":"amiga"},{"nombre":"Tyler","genero":"hombre","rol":"amigo"},{"nombre":"Rosa","genero":"mujer","rol":"amiga"}],"lineas":[[0,"I can't believe the tickets for The Killers are already sold out. I've been waiting for this for months!","No puedo creer que los boletos para The Killers ya estén agotados. ¡He estado esperando esto por meses!"],[1,"Tell me about it. I was on the website the second they went on sale, and they were gone in, like, five minutes.","Ni me digas. Estuve en el sitio web al segundo que salieron a la venta y se acabaron en como cinco minutos."],[2,"Wow, that's crazy. I didn't even try. I knew it would be impossible to get them.","Wow, qué locura. Yo ni siquiera lo intenté. Sabía que sería imposible conseguirlos."],[0,"Well, I really wanted to go. If we had gotten tickets, it would have been an amazing night.","Pues, de verdad quería ir. Si hubiéramos conseguido boletos, habría sido una noche increíble."],[1,"Yeah, totally. I've seen videos of their live shows. They look incredible.","Sí, totalmente. He visto videos de sus conciertos en vivo. Se ven increíbles."],[2,"I have an idea! What if we just have our own concert night at my place? We can watch their old shows on TV.","¡Tengo una idea! ¿Y si hacemos nuestra propia noche de concierto en mi casa? Podemos ver sus shows antiguos en la tele."],[0,"Oh, that's actually a great idea! It's not the same, but it could be really fun.","¡Oh, esa es una gran idea, la verdad! No es lo mismo, pero podría ser muy divertido."],[1,"I'm in! We could order some pizza and make a whole thing of it. It's much cheaper, too.","¡Me apunto! Podríamos pedir pizza y armar todo un plan. Es mucho más barato, además."],[2,"Exactly! And no crowds. I mean, I love concerts, but sometimes the amount of people is just too much.","¡Exacto! Y sin multitudes. O sea, me encantan los conciertos, pero a veces la cantidad de gente es demasiada."],[0,"You've got a point there. Okay, I feel much better now. When should we do it?","Tienes razón en eso. Ok, ya me siento mucho mejor. ¿Cuándo lo hacemos?"],[1,"How about this Saturday? I'm free all evening.","¿Qué tal este sábado? Estoy libre toda la noche."],[2,"Saturday works perfectly for me. I'll get the good speakers ready!","El sábado me queda perfecto. ¡Yo preparo las buenas bocinas!"],[0,"Awesome! This is going to be great. Thanks for suggesting it, Rosa.","¡Genial! Esto va a estar buenísimo. Gracias por sugerirlo, Rosa."],[1,"Yeah, thanks, Rosa! You totally saved the day.","¡Sí, gracias, Rosa! Literalmente salvaste el día."]]},{"id":"vb1-29","nivel":"B1","emoji":"🎉","titulo":"Planning the Office Party","tituloEs":"Organizando la fiesta de la oficina","personas":[{"nombre":"Grace","genero":"mujer","rol":"Colega del trabajo"},{"nombre":"Zach","genero":"hombre","rol":"Colega del trabajo"},{"nombre":"Marcus","genero":"hombre","rol":"Colega del trabajo"},{"nombre":"Omar","genero":"hombre","rol":"Colega del trabajo"}],"lineas":[[0,"Okay everyone, let's talk about the holiday party. Have we decided on a date yet?","Bueno todos, hablemos de la fiesta de fin de año. ¿Ya hemos decidido una fecha?"],[1,"Not yet. I was thinking the second Friday of December. Most people should be free then.","Todavía no. Estaba pensando en el segundo viernes de diciembre. La mayoría de la gente debería estar libre entonces."],[2,"Good idea. And what about food? Are we thinking of catering again, or something different?","Buena idea. ¿Y qué hay de la comida? ¿Estamos pensando en pedir catering de nuevo o algo diferente?"],[3,"I think we should do a potluck! It would be cheaper and more personal, you know?","¡Yo creo que deberíamos hacer una comida 'a la canasta'! Sería más barato y más personal, ¿saben?"],[0,"A potluck sounds fun, but it could get complicated. We'd have to organize who brings what.","Una comida 'a la canasta' suena divertido, pero podría complicarse. Tendríamos que organizar quién trae qué."],[1,"Yeah, that's true. Last time a potluck was suggested, we ended up with five potato salads and no dessert.","Sí, es verdad. La última vez que se sugirió una comida así, terminamos con cinco ensaladas de papa y sin postre."],[2,"Okay, fair point. What if we catered the main dishes and asked people to bring desserts and drinks?","Ok, buen punto. ¿Qué tal si pedimos los platos principales y le pedimos a la gente que traiga postres y bebidas?"],[3,"Oh, I like that idea a lot! That's a great compromise. I can bring my famous cheesecake.","¡Oh, me gusta mucho esa idea! Es un muy buen punto medio. Yo puedo traer mi famoso pastel de queso."],[0,"Perfect! Now, for music... I've already made a playlist, but I'm open to suggestions.","¡Perfecto! Ahora, la música... Ya he hecho una lista de reproducción, pero estoy abierta a sugerencias."],[1,"As long as it's not just holiday music for four hours straight, I'm happy.","Mientras no sea solo música navideña por cuatro horas seguidas, yo estoy feliz."],[2,"We should definitely have a karaoke machine. If we rent one, I promise to sing.","Definitivamente deberíamos tener una máquina de karaoke. Si alquilamos una, prometo que canto."],[3,"Karaoke is a must! It'll be hilarious. I've never seen our boss sing before.","¡El karaoke es obligatorio! Será divertidísimo. Nunca he visto a nuestro jefe cantar."],[0,"Alright, this is great. So, catered mains, potluck desserts, and karaoke. I'll send an email with the details.","Muy bien, esto es genial. Entonces, platos fuertes de catering, postres de contribución y karaoke. Mandaré un correo con los detalles."],[1,"Sounds like it's going to be the best party yet. I'm already excited.","Suena a que va a ser la mejor fiesta hasta ahora. Ya estoy emocionado."]]},{"id":"vb1-30","nivel":"B1","emoji":"🫂","titulo":"An Unexpected Reunion","tituloEs":"Un reencuentro inesperado","personas":[{"nombre":"Emma","genero":"mujer","rol":"vieja amiga"},{"nombre":"Ethan","genero":"hombre","rol":"viejo amigo"}],"lineas":[[0,"Oh my gosh... Ethan? Is that really you?","Dios mío... ¿Ethan? ¿De verdad eres tú?"],[1,"Emma! Wow, I can't believe it. What are you doing in this neighborhood?","¡Emma! Guau, no puedo creerlo. ¿Qué haces por este barrio?"],[0,"I live just two blocks away! It's been ages. You look exactly the same.","¡Vivo a solo dos cuadras! Ha pasado una eternidad. Te ves exactamente igual."],[1,"I wish! It has to be, what, six or seven years? How have you been?","¡Ojalá! Deben ser, ¿qué?, ¿seis o siete años? ¿Cómo has estado?"],[0,"I've been good, really busy. Are you still working in tech sales?","He estado bien, muy ocupada. ¿Todavía trabajas en ventas de tecnología?"],[1,"No, actually. I quit that job a long time ago. I'm a chef now.","No, de hecho. Dejé ese trabajo hace mucho tiempo. Ahora soy chef."],[0,"A chef? No way! That is so cool. Where do you work?","¿Un chef? ¡No puede ser! Eso es genial. ¿Dónde trabajas?"],[1,"I co-own a small Italian restaurant downtown. It's been a wild ride, but I love it.","Soy copropietario de un pequeño restaurante italiano en el centro. Ha sido una aventura, pero me encanta."],[0,"I bet! Well, I'm still at the same marketing agency, but I lead my own team now.","¡Me imagino! Bueno, yo sigo en la misma agencia de marketing, pero ahora dirijo mi propio equipo."],[1,"That's awesome, congratulations! I'm not surprised at all.","¡Eso es increíble, felicidades! No me sorprende para nada."],[0,"Thanks! Hey, we should really catch up properly sometime.","¡Gracias! Oye, de verdad deberíamos ponernos al día bien en algún momento."],[1,"I'd love that. If you're free, you should come by the restaurant for dinner.","Me encantaría. Si estás libre, deberías pasarte por el restaurante a cenar."],[0,"I would love to! How about this Friday night?","¡Me encantaría! ¿Qué te parece este viernes por la noche?"],[1,"Friday is perfect. I'll save you a good table. It was so good to see you.","El viernes es perfecto. Te guardaré una buena mesa. Qué bueno fue verte."]]},{"id":"vb2-01","nivel":"B2","emoji":"📈","titulo":"Performance Review Chat","tituloEs":"Charla de evaluación de desempeño","personas":[{"nombre":"Noah","genero":"hombre","rol":"Empleado"},{"nombre":"Denise","genero":"mujer","rol":"Jefa"}],"lineas":[[0,"Hi Denise, thanks for having me. Should I close the door?","Hola Denise, gracias por recibirme. ¿Cierro la puerta?"],[1,"Come on in, Noah. No need, we can keep it casual. So, let's get into your performance review.","Pasa, Noah. No hace falta, que sea informal. Bueno, entremos en tu evaluación de desempeño."],[0,"Sounds good. I have to admit, I'm always a little nervous for these things.","Me parece bien. Debo admitir que siempre estoy un poco nervioso para estas cosas."],[1,"Don't be! Honestly, it’s overwhelmingly positive. Your work on the Q3 analytics report was a game-changer for us.","¡No lo estés! Sinceramente, es abrumadoramente positiva. Tu trabajo en el informe de análisis del tercer trimestre fue un antes y un después para nosotros."],[0,"Oh, that's great to hear. I was really proud of how that project turned out.","Oh, qué bueno escuchar eso. Estaba muy orgulloso de cómo quedó ese proyecto."],[1,"You should be. You really knocked it out of the park. The board was incredibly impressed with the insights.","Y deberías estarlo. Realmente te luciste. La junta directiva quedó increíblemente impresionada con las conclusiones."],[0,"Wow, thank you. The whole team put a ton of hours into it.","Vaya, gracias. Todo el equipo le dedicó un montón de horas."],[1,"It certainly shows. Now, looking forward, I'd love to see you take the lead more in our brainstorming sessions.","Ciertamente se nota. Ahora, mirando hacia el futuro, me encantaría verte tomar más la iniciativa en nuestras sesiones de lluvia de ideas."],[0,"Okay, that's fair feedback. Can you elaborate a bit on that?","Ok, es una crítica justa. ¿Puedes darme un poco más de detalle sobre eso?"],[1,"Of course. Your ideas are always spot-on, but you sometimes wait until the end to share them. We need your voice earlier in the process.","Por supuesto. Tus ideas siempre son acertadas, pero a veces esperas hasta el final para compartirlas. Necesitamos tu opinión antes en el proceso."],[0,"I see your point. I've been trying to listen more, but I can definitely be more proactive. I'll work on that.","Entiendo tu punto. He estado intentando escuchar más, pero definitivamente puedo ser más proactivo. Trabajaré en ello."],[1,"Perfect. To help with that, I'm thinking of putting you in charge of the initial planning for the new client pitch. How does that feel?","Perfecto. Para ayudar con eso, estoy pensando en ponerte a cargo de la planificación inicial de la propuesta para el nuevo cliente. ¿Qué te parece?"],[0,"That sounds fantastic! I'd be thrilled to take that on. It's the kind of challenge I've been hoping for.","¡Suena fantástico! Estaría encantado de encargarme de eso. Es el tipo de desafío que he estado esperando."],[1,"Excellent. We'll iron out the details next week. Overall, you're a huge asset to the team, Noah. Keep up the great work.","Excelente. Afinaremos los detalles la próxima semana. En general, eres un gran valor para el equipo, Noah. Sigue así."],[0,"Thanks so much, Denise. This was actually really helpful and productive.","Muchas gracias, Denise. La verdad es que esto fue muy útil y productivo."],[1,"I'm glad to hear it. Now go enjoy the rest of your day. You've earned it.","Me alegra oírlo. Ahora ve a disfrutar el resto del día. Te lo has ganado."]]},{"id":"vb2-02","nivel":"B2","emoji":"🚀","titulo":"The Startup Pitch Meeting","tituloEs":"La Reunión de Presentación de la Startup","personas":[{"nombre":"Owen","genero":"hombre","rol":"CEO de la startup"},{"nombre":"Vanessa","genero":"mujer","rol":"CTO de la startup"},{"nombre":"Nate","genero":"hombre","rol":"Inversionista"},{"nombre":"Lauren","genero":"mujer","rol":"Inversionista"}],"lineas":[[0,"So, thank you all for being here. We believe 'ConnectSphere' will fundamentally change how remote teams collaborate.","Bueno, gracias a todos por estar aquí. Creemos que 'ConnectSphere' cambiará fundamentalmente la forma en que colaboran los equipos remotos."],[1,"To put it simply, we're getting rid of the endless, confusing email chains that everyone hates.","En pocas palabras, estamos eliminando las interminables y confusas cadenas de correos que todo el mundo odia."],[2,"That's a bold claim. We've seen a dozen similar platforms. What's your secret sauce?","Esa es una afirmación audaz. Hemos visto una docena de plataformas similares. ¿Cuál es su ingrediente secreto?"],[3,"Right. And how do you plan to stand out in such a crowded market?","Exacto. ¿Y cómo planean destacar en un mercado tan saturado?"],[0,"Great question. Our edge is our AI-powered task prioritization. It learns your workflow and basically sorts your day for you.","Excelente pregunta. Nuestra ventaja es la priorización de tareas impulsada por IA. Aprende tu flujo de trabajo y básicamente te organiza el día."],[1,"It's what we call 'intuitive integration.' It doesn't just hold information; it actively helps you manage it.","Es lo que llamamos 'integración intuitiva'. No solo almacena información; te ayuda activamente a gestionarla."],[2,"Hmm, 'intuitive integration'... I like the sound of that. But what about user adoption? That's a huge hurdle.","Mmm, 'integración intuitiva'... me gusta cómo suena. Pero, ¿qué hay de la adopción por parte de los usuarios? Es un obstáculo enorme."],[3,"He's got a point. People are creatures of habit. How do you make the switch painless?","Tiene razón. La gente es animal de costumbres. ¿Cómo hacen que el cambio sea indoloro?"],[0,"We've gamified the onboarding process. New users get points for exploring features, which sounds silly, but our beta testers loved it.","Hemos ludificado el proceso de incorporación. Los usuarios nuevos obtienen puntos por explorar funciones, lo que suena tonto, pero a nuestros evaluadores beta les encantó."],[1,"They were actually competing to become the 'Onboarding Champion.' We were blown away by the engagement.","De hecho, competían por convertirse en el 'Campeón de la Incorporación'. Nos quedamos impresionados con la participación."],[2,"Okay, that's clever. I can see that working. You two have clearly thought this through.","Ok, eso es ingenioso. Puedo ver que funcione. Ustedes dos claramente han pensado bien en esto."],[3,"I'm impressed. You've addressed some major pain points. What are your initial revenue projections?","Estoy impresionada. Han abordado algunos puntos débiles importantes. ¿Cuáles son sus proyecciones de ingresos iniciales?"],[0,"We're projecting reaching 50,000 active users by year two, with a freemium model that converts at 5% to our Pro plan.","Proyectamos alcanzar 50,000 usuarios activos para el segundo año, con un modelo 'freemium' que convierte al 5% a nuestro plan Pro."],[1,"And our churn rate in beta was under 2%, which we're incredibly proud of.","Y nuestra tasa de cancelación en la versión beta fue inferior al 2%, de lo cual estamos increíblemente orgullosos."],[2,"Alright, this is very promising. Send over the full deck. We'd like to take a closer look.","Muy bien, esto es muy prometedor. Envíen la presentación completa. Nos gustaría echarle un vistazo más de cerca."],[3,"Yes, let's schedule a follow-up for next week to dig into the numbers. We'll be in touch.","Sí, programemos un seguimiento para la próxima semana para profundizar en las cifras. Estaremos en contacto."]]},{"id":"vb2-03","nivel":"B2","emoji":"🏠","titulo":"The Remote Work Debate","tituloEs":"El debate del trabajo remoto","personas":[{"nombre":"Nate","genero":"hombre","rol":"Compañero de trabajo"},{"nombre":"Grace","genero":"mujer","rol":"Compañera de trabajo"},{"nombre":"Luis","genero":"hombre","rol":"Compañero de trabajo"}],"lineas":[[0,"Honestly, I think I'm hitting a wall with this whole work-from-home thing. I actually miss the office buzz.","Honestamente, creo que estoy llegando a mi límite con esto de trabajar desde casa. La verdad es que extraño el ambiente de la oficina."],[1,"You're joking, right? I'm living the dream! I save so much time and money without the commute.","¿Estás bromeando, verdad? ¡Estoy viviendo un sueño! Ahorro muchísimo tiempo y dinero sin el viaje al trabajo."],[2,"I see both sides. The freedom is unbeatable, but I do feel a bit disconnected from the team sometimes.","Entiendo ambos puntos de vista. La libertad es inmejorable, pero a veces sí me siento un poco desconectado del equipo."],[0,"That's exactly it! Spontaneous brainstorming sessions just don't happen over Slack. It feels less creative.","¡A eso me refiero! Las sesiones espontáneas de lluvia de ideas simplemente no suceden por Slack. Se siente menos creativo."],[1,"I have to push back on that a bit. I think our meetings are way more focused now. We get straight to the point.","Tengo que discrepar un poco con eso. Creo que nuestras reuniones son mucho más enfocadas ahora. Vamos directo al grano."],[2,"That's true. There's less small talk, which can be good, but you also miss out on building those team relationships.","Eso es cierto. Hay menos charla trivial, lo cual puede ser bueno, pero también te pierdes de construir esas relaciones de equipo."],[0,"Right! And my back is killing me from sitting on this dining chair all day. I miss my ergonomic setup.","¡Exacto! Y me está matando la espalda de estar sentado en esta silla del comedor todo el día. Extraño mi puesto ergonómico."],[1,"Okay, the chair situation is a valid point. But for me, the trade-off is still worth it. I can throw in a load of laundry between meetings!","Ok, el tema de la silla es un punto válido. Pero para mí, el beneficio lo compensa. ¡Puedo poner una lavadora entre reuniones!"],[2,"What do you guys think about a hybrid schedule? Like, two days in the office and three at home?","¿Qué opinan de un horario híbrido? Por ejemplo, ¿dos días en la oficina y tres en casa?"],[0,"You know, that doesn't sound half bad. It would give me a reason to wear something other than sweatpants.","Sabes, no suena nada mal. Me daría una razón para ponerme algo que no sea un pantalón de chándal."],[1,"Hmm, I could be persuaded. I do miss the free snacks and the fancy coffee machine, I'll admit.","Mmm, podrían convencerme. Admito que sí extraño los snacks gratis y la máquina de café elegante."],[2,"It really seems like the best of both worlds. You get the focus at home and the collaboration in person.","Realmente parece lo mejor de ambos mundos. Obtienes la concentración en casa y la colaboración en persona."],[0,"Yeah, a good compromise. I think I could definitely get behind that idea.","Sí, un buen punto intermedio. Creo que definitivamente podría apoyar esa idea."],[1,"Me too. It's all about finding that balance, isn't it? So, who's going to suggest it to the boss?","Yo también. Se trata de encontrar ese equilibrio, ¿no? Entonces, ¿quién se lo va a sugerir al jefe?"],[2,"Haha, let's draw straws! But seriously, I think it's a solid proposal we could bring up.","¡Jaja, echémoslo a suertes! Pero en serio, creo que es una propuesta sólida que podríamos plantear."]]},{"id":"vb2-04","nivel":"B2","emoji":"🏘️","titulo":"House Hunting with an Agent","tituloEs":"Visitando una casa con una agente","personas":[{"nombre":"Hannah","genero":"mujer","rol":"compradora potencial"},{"nombre":"Frank","genero":"hombre","rol":"comprador potencial"},{"nombre":"Brooke","genero":"mujer","rol":"agente inmobiliaria"}],"lineas":[[2,"Alright, here we are. Come on in! The first thing you'll notice is all this incredible natural light.","Muy bien, aquí estamos. ¡Adelante! Lo primero que notarán es toda esta increíble luz natural."],[0,"Wow, you weren't kidding. It feels so open and airy in here.","Wow, no bromeabas. Se siente muy abierto y espacioso aquí adentro."],[1,"It's definitely bright. I guess we'd save on electricity, which is a plus.","Definitivamente es luminoso. Supongo que ahorraríamos en electricidad, lo cual es una ventaja."],[2,"Exactly! And if you follow me this way, you'll see the newly renovated kitchen.","¡Exacto! Y si me siguen por aquí, verán la cocina recién renovada."],[0,"Oh, I love this island! I can just picture myself making breakfast here.","¡Oh, me encanta esta isla! Ya me puedo imaginar preparando el desayuno aquí."],[1,"It's nice, for sure. I'm just trying to figure out where all our kitchen gadgets would go.","Es bonita, sin duda. Solo estoy tratando de imaginar dónde irían todos nuestros aparatos de cocina."],[2,"Not to worry. There's a huge walk-in pantry right around that corner.","No te preocupes. Hay una despensa enorme justo a la vuelta de esa esquina."],[0,"A walk-in pantry? Okay, now you're speaking my language. This is amazing.","¿Una despensa? Ok, ahora sí que nos entendemos. Esto es increíble."],[1,"Honey, she had you at 'newly renovated.' My only question is where does my giant TV fit?","Cariño, ya te había convencido con 'recién renovada'. Mi única pregunta es ¿dónde cabe mi tele gigante?"],[2,"The living room is quite spacious. I'm sure we can find the perfect spot for it.","La sala de estar es bastante espaciosa. Estoy segura de que podemos encontrarle el lugar perfecto."],[0,"This is great. What's the backyard like? Is it fenced in for a dog?","Esto es genial. ¿Cómo es el patio trasero? ¿Está cercado para un perro?"],[1,"Yeah, and how's the noise level around here? The street seemed pretty quiet coming in.","Sí, ¿y qué tal el nivel de ruido por aquí? La calle parecía bastante tranquila cuando llegamos."],[2,"The backyard is fully fenced, and the neighborhood is known for being very peaceful. It's a big draw for many families.","El patio está completamente cercado y el vecindario es conocido por ser muy tranquilo. Es un gran atractivo para muchas familias."],[0,"I'm really liking this place, Frank. It's ticking a lot of boxes for me.","Realmente me está gustando este lugar, Frank. Cumple con muchos de mis requisitos."],[1,"I have to admit, it's a serious contender. It feels... solid.","Tengo que admitir que es un candidato serio. Se siente... sólido."],[2,"I'm so glad to hear that. Why don't you two take another look around while I pull up the property details?","Me alegra mucho oír eso. ¿Por qué no le echan otro vistazo mientras yo busco los detalles de la propiedad?"]]},{"id":"vb2-05","nivel":"B2","emoji":"🤖","titulo":"Discussing the AI News","tituloEs":"Comentando la noticia de la IA","personas":[{"nombre":"Kyle","genero":"hombre","rol":"Amigo del grupo"},{"nombre":"Emma","genero":"mujer","rol":"Amiga del grupo"},{"nombre":"Danny","genero":"hombre","rol":"Amigo del grupo"}],"lineas":[[0,"Hey, did you guys get a chance to read that article I sent about AI-generated art? The one that won a competition.","Oigan, ¿tuvieron chance de leer el artículo que les mandé sobre el arte generado por IA? El que ganó un concurso."],[1,"I did! It's pretty mind-blowing, but honestly, it makes me a little uneasy. I'm not sure art created by a machine should even qualify.","¡Sí lo leí! Es bastante alucinante, pero sinceramente, me inquieta un poco. No estoy segura de que el arte creado por una máquina siquiera deba calificar."],[2,"Oh, come on, I think it's incredible! I, for one, welcome our new robot overlords. Especially if they can do my dishes.","¡Ay, por favor, a mí me parece increíble! Yo, por mi parte, les doy la bienvenida a nuestros nuevos amos robots. Especialmente si pueden lavar mis platos."],[0,"Haha, dream on. But seriously, the piece brought up some good points. It's forcing us to rethink what creativity actually is.","Jaja, sigue soñando. Pero en serio, el artículo planteaba algunos puntos buenos. Nos está obligando a reconsiderar qué es realmente la creatividad."],[1,"Totally. And what about the people who make a living from this? It feels like we're opening a huge can of worms for artists and designers.","Totalmente. ¿Y qué pasa con la gente que vive de esto? Siento que estamos abriendo una caja de Pandora para los artistas y diseñadores."],[2,"I see what you mean, but couldn't it just be a new tool? Think about when photography first came out. People said it would be the end of painting.","Entiendo lo que dices, pero ¿no podría ser solo una nueva herramienta? Piensa en cuando apareció la fotografía. La gente decía que sería el fin de la pintura."],[0,"That’s a fair comparison. Maybe it's not about replacement, but collaboration. An artist guiding the AI could create something totally new.","Es una comparación justa. Quizás no se trata de reemplazar, sino de colaborar. Un artista guiando a la IA podría crear algo completamente nuevo."],[1,"I suppose. I’m just a bit of a skeptic when it comes to this stuff. It all feels like it’s moving way too fast.","Supongo. Es que soy un poco escéptica con estas cosas. Siento que todo está avanzando demasiado rápido."],[2,"Well, I tried one of those AI portrait generators the other day. It gave me three ears, so I don't think artists are out of a job just yet.","Bueno, el otro día probé uno de esos generadores de retratos con IA. Me puso tres orejas, así que no creo que los artistas se vayan a quedar sin trabajo todavía."],[0,"Ha! See? There's still hope for humanity. Did you save the picture? We have to see this.","¡Ja! ¿Ves? Todavía hay esperanza para la humanidad. ¿Guardaste la foto? Tenemos que ver eso."],[1,"Oh my gosh, please tell me you did. That sounds hilarious. Maybe its specialty is abstract art.","Ay, por Dios, por favor dime que sí. Eso suena divertidísimo. Quizás su especialidad es el arte abstracto."],[2,"Of course I saved it! It's my new profile picture. My mom asked if I was feeling okay.","¡Claro que la guardé! Es mi nueva foto de perfil. Mi mamá me preguntó si me sentía bien."],[0,"That's amazing. Okay, you've convinced me. Maybe this AI thing isn't so bad after all, as long as it keeps making us laugh.","Eso es genial. Ok, me has convencido. Quizás esto de la IA no es tan malo después de todo, siempre y cuando nos siga haciendo reír."],[1,"Agreed. As long as it's for laughs and not, you know, launching nuclear missiles by itself.","De acuerdo. Siempre que sea para reír y no para, ya sabes, lanzar misiles nucleares por sí sola."],[2,"Right. Let's stick to the funny portraits for now. The world's not ready for Skynet.","Exacto. Mejor quedémonos con los retratos chistosos por ahora. El mundo no está listo para Skynet."]]},{"id":"vb2-06","nivel":"B2","emoji":"🧳","titulo":"Airline Compensation Claim","tituloEs":"Reclamo de compensación a la aerolínea","personas":[{"nombre":"Grace","genero":"mujer","rol":"pasajera frustrada"},{"nombre":"Nate","genero":"hombre","rol":"amigo comprensivo"}],"lineas":[[0,"Ugh, I am so over that airline. My flight back from Chicago was a complete disaster.","Uf, estoy tan harta de esa aerolínea. Mi vuelo de regreso de Chicago fue un completo desastre."],[1,"Oh no, what happened? Don't tell me they canceled it on you.","Oh no, ¿qué pasó? No me digas que te lo cancelaron."],[0,"Worse. We were delayed for four hours, and to top it off, they lost my luggage.","Peor. Nos retrasaron cuatro horas y, para colmo, perdieron mi equipaje."],[1,"You've got to be kidding me. That's terrible. You should definitely file for compensation.","No me digas. Eso es terrible. Definitivamente deberías presentar un reclamo de compensación."],[0,"I know I should, but the thought of dealing with their customer service gives me a headache.","Sé que debería, pero la sola idea de lidiar con su servicio al cliente me da dolor de cabeza."],[1,"I get it, but you're entitled to it. They have to compensate you for the delay and the lost bag.","Te entiendo, pero tienes derecho a ello. Tienen que compensarte por el retraso y la maleta perdida."],[0,"Really? I thought it was a long shot. I just don't want to waste my time.","¿En serio? Pensé que era poco probable. Simplemente no quiero perder mi tiempo."],[1,"It's not a long shot at all. I got a few hundred dollars back when my flight to Austin was severely delayed.","No es para nada poco probable. A mí me devolvieron unos cientos de dólares cuando mi vuelo a Austin se retrasó gravemente."],[0,"Wow, seriously? Okay, that's actually motivating. Maybe it's worth a shot then.","Vaya, ¿en serio? Ok, eso es realmente motivador. Quizás valga la pena intentarlo entonces."],[1,"Totally. Just make sure you have your booking reference and keep all the receipts for things you had to buy.","Totalmente. Solo asegúrate de tener tu código de reserva y guarda todos los recibos de las cosas que tuviste que comprar."],[0,"Right, because I had to buy a new charger and some toiletries. It all adds up.","Cierto, porque tuve que comprar un cargador nuevo y algunos artículos de aseo. Todo va sumando."],[1,"Exactly! They have to cover those reasonable expenses. Stand your ground.","¡Exacto! Tienen que cubrir esos gastos razonables. Mantente firme."],[0,"Okay, okay, you've talked me into it. I'll tackle the online form tonight.","Ok, ok, me convenciste. Me pondré con el formulario en línea esta noche."],[1,"That's the spirit! Let me know if you want me to look it over before you submit it.","¡Esa es la actitud! Avísame si quieres que lo revise antes de que lo envíes."],[0,"Thanks, Nate, I really appreciate that. Wish me luck!","Gracias, Nate, de verdad lo aprecio. ¡Deséame suerte!"]]},{"id":"vb2-07","nivel":"B2","emoji":"🩻","titulo":"Going Over Your Test Results","tituloEs":"Revisando los resultados de tus exámenes","personas":[{"nombre":"Jake","genero":"hombre","rol":"Paciente"},{"nombre":"Priya","genero":"mujer","rol":"Médica"}],"lineas":[[0,"Alright, doc, lay it on me. How do the results look? Am I falling apart yet?","Muy bien, doctora, dígame. ¿Qué tal los resultados? ¿Ya me estoy desmoronando?"],[1,"Haha, not at all, Jake. Overall, you're in good shape. There are just a couple of things we should keep an eye on.","Jaja, para nada, Jake. En general, estás en buena forma. Solo hay un par de cosas a las que deberíamos prestar atención."],[0,"Okay, I figured as much. Is it my cholesterol again? I swear, cheeseburgers are my kryptonite.","Ok, me lo imaginaba. ¿Es mi colesterol otra vez? Te juro que las hamburguesas con queso son mi kriptonita."],[1,"That's part of it. Your LDL, the 'bad' cholesterol, is a bit on the high side. Your blood sugar is also creeping up a little.","Eso es parte del asunto. Tu LDL, el colesterol 'malo', está un poco elevado. Tu nivel de azúcar en la sangre también está subiendo un poquito."],[0,"Creeping up? That doesn't sound good. So what's the game plan? Do I have to start eating nothing but kale?","¿Subiendo? Eso no suena bien. ¿Cuál es el plan de acción? ¿Tengo que empezar a comer solo kale?"],[1,"Not quite! We can definitely turn this around with some small changes. I want you to focus on cutting back on processed foods and saturated fats.","¡No exactamente! Definitivamente podemos revertir esto con algunos pequeños cambios. Quiero que te concentres en reducir los alimentos procesados y las grasas saturadas."],[0,"So, fewer cheeseburgers. Got it. What about exercise? I walk the dog, does that count?","Entonces, menos hamburguesas con queso. Entendido. ¿Y qué hay del ejercicio? Paseo al perro, ¿eso cuenta?"],[1,"It's a great start! But I'd like you to aim for about 30 minutes of more intentional activity, three or four times a week.","¡Es un gran comienzo! Pero me gustaría que apuntaras a unos 30 minutos de actividad más intencional, tres o cuatro veces por semana."],[0,"Like what, jogging? Ugh, fine. I guess I can dust off my running shoes. It’s just hard to get motivated sometimes, you know?","¿Como qué, trotar? Uf, está bien. Supongo que puedo desempolvar mis zapatillas de correr. Es que a veces es difícil motivarse, ¿sabes?"],[1,"I completely get it. The key is to find something you don't hate. It could be biking, swimming, or even a fun dance class.","Lo entiendo perfectamente. La clave es encontrar algo que no odies. Podría ser andar en bicicleta, nadar o incluso una clase de baile divertida."],[0,"A dance class... Hmm, now there's an interesting thought. Maybe I'll actually look into that.","Una clase de baile... Mmm, esa es una idea interesante. Quizás de verdad lo investigue."],[1,"You got it. It's not about making huge, drastic changes overnight. It’s about building healthier habits that stick.","Exacto. No se trata de hacer cambios enormes y drásticos de la noche a la mañana. Se trata de construir hábitos más saludables que perduren."],[0,"That makes sense. It feels a lot less overwhelming when you put it that way.","Eso tiene sentido. Suena mucho menos abrumador cuando lo pones de esa forma."],[1,"Exactly. So let's try these adjustments for three months, and then we'll re-check your levels. How does that sound?","Exacto. Entonces, probemos estos ajustes durante tres meses y luego volveremos a revisar tus niveles. ¿Qué te parece?"],[0,"Sounds like a plan. Three months to become a slightly healthier, salsa-dancing version of myself. I can do that.","Suena como un plan. Tres meses para convertirme en una versión un poco más saludable y bailarina de salsa de mí mismo. Puedo hacerlo."],[1,"That's the spirit! My nurse will give you some handouts with dietary suggestions on your way out.","¡Esa es la actitud! Mi enfermera te dará unos folletos con sugerencias dietéticas al salir."]]},{"id":"vb2-08","nivel":"B2","emoji":"🥂","titulo":"Crafting the Perfect Wedding Toast","tituloEs":"Elaborando el brindis de boda perfecto","personas":[{"nombre":"Nora","genero":"mujer","rol":"amiga de la novia"},{"nombre":"Brandon","genero":"hombre","rol":"amigo del novio"},{"nombre":"Andre","genero":"hombre","rol":"amigo del novio"}],"lineas":[[0,"Okay, the toast is in like, ten minutes. Have we come up with anything besides just 'congratulations'?","Okay, el brindis es en como diez minutos. ¿Se nos ha ocurrido algo además de solo 'felicidades'?"],[1,"Hey, 'congratulations' is a classic for a reason. But fine, I was thinking we could start with a funny story about them.","Oye, 'felicidades' es un clásico por algo. Pero bueno, estaba pensando que podríamos empezar con una historia graciosa sobre ellos."],[2,"Oh, I've got a ton of those. Remember that time Mark tried to assemble that IKEA bookshelf for Jen's birthday?","Uy, de esas tengo un montón. ¿Se acuerdan de esa vez que Mark intentó armar esa estantería de IKEA por el cumpleaños de Jen?"],[0,"That’s a great one! But we have to make sure we don't end up just roasting him. It needs to be sweet, too.","¡Esa es buenísima! Pero hay que asegurarnos de no terminar solo burlándonos de él. También tiene que ser tierno."],[1,"Right. We tell the funny story, then pivot to how it shows he'd do anything for her, even if he's terrible at it.","Claro. Contamos la anécdota graciosa y luego le damos un giro para mostrar cómo haría cualquier cosa por ella, aunque sea pésimo para eso."],[2,"I like that. It strikes a good balance. So I'll take the lead on the bookshelf story since I was there.","Me gusta. Logra un buen equilibrio. Entonces yo me encargo de la historia de la estantería, ya que yo estuve ahí."],[0,"Perfect. And I can talk about how Jen is the most patient and supportive person I know, which she clearly had to be!","Perfecto. Y yo puedo hablar de que Jen es la persona más paciente y que más apoya que conozco, ¡lo cual claramente tuvo que ser!"],[1,"This is actually coming together pretty well. What's my part? I don't want to just stand there looking awkward.","Esto de verdad está quedando bastante bien. ¿Y mi parte cuál es? No quiero solo quedarme ahí parado viéndome incómodo."],[2,"You can do the introduction and the final 'raise your glass' part. You've got that confident public speaking voice.","Tú puedes hacer la introducción y la parte final de 'levanten sus copas'. Tienes esa voz segura para hablar en público."],[0,"He's right, you'd be great for the opening and closing. You set the tone and then wrap it all up.","Tiene razón, serías genial para el inicio y el cierre. Tú marcas el tono y luego cierras con broche de oro."],[1,"Alright, I can handle that. I was getting a bit stressed out, but this sounds like a solid plan. I won't screw it up.","De acuerdo, puedo con eso. Ya me estaba estresando un poco, pero suena a un plan sólido. No lo voy a arruinar."],[2,"Of course you won't. We're a team. Just speak from the heart and try not to trip on your way up there.","Claro que no. Somos un equipo. Solo habla con el corazón y trata de no tropezarte al subir."],[0,"So, let's do a quick run-through. Brandon, you kick it off. Andre, bookshelf story. I'll add the sweet stuff about Jen.","Bien, repasemos rápido. Brandon, tú arrancas. Andre, la historia de la estantería. Yo agrego lo tierno sobre Jen."],[1,"And then I jump back in to propose the toast. Got it. Phew, I feel so much better now.","Y luego entro yo de nuevo para proponer el brindis. Entendido. Uf, ya me siento mucho mejor."],[2,"See? Teamwork makes the dream work. Now let's go get a drink... I mean, let's get ready.","¿Ves? El trabajo en equipo hace los sueños realidad. Ahora vamos por un trago... digo, a prepararnos."]]},{"id":"vb2-09","nivel":"B2","emoji":"🤝","titulo":"Negotiating a Salary Offer","tituloEs":"Negociar una oferta de salario","personas":[{"nombre":"Carol","genero":"mujer","rol":"Amiga que recibió una oferta"},{"nombre":"Logan","genero":"hombre","rol":"Amigo que da consejos"}],"lineas":[[0,"Hey, so I got the official job offer from that tech company!","¡Oye, recibí la oferta de trabajo oficial de esa empresa de tecnología!"],[1,"That's fantastic news! So, are you popping the champagne yet?","¡Esas son noticias fantásticas! Y entonces, ¿ya estás descorchando el champán?"],[0,"Not quite. The salary they offered is a little on the low side, to be honest.","Todavía no. El salario que ofrecieron es un poco bajo, para ser honesta."],[1,"Ah, okay. So, are you planning to counteroffer? You definitely should.","Ah, de acuerdo. Entonces, ¿planeas hacer una contraoferta? Definitivamente deberías."],[0,"I want to, but I'm so nervous. What if they just pull the offer?","Quiero, pero estoy muy nerviosa. ¿Y si simplemente retiran la oferta?"],[1,"That almost never happens. Seriously. They expect you to negotiate; it's part of the game.","Eso casi nunca pasa. En serio. Ellos esperan que negocies; es parte del juego."],[0,"I just don't want to come across as greedy or ungrateful.","Es que no quiero parecer codiciosa o malagradecida."],[1,"It's not greedy, it's knowing your value. You did your research on the market rate, right?","No es ser codiciosa, es saber tu valor. Investigaste el rango del mercado, ¿verdad?"],[0,"Yeah, and my target was about 10% higher than what they offered. Is that a reasonable ask?","Sí, y mi objetivo era un 10% más alto de lo que ofrecieron. ¿Es una petición razonable?"],[1,"Totally reasonable. Just be ready to back it up with your experience and the data you found.","Totalmente razonable. Solo prepárate para respaldarlo con tu experiencia y los datos que encontraste."],[0,"Okay, okay, you're right. I just need to get over the awkwardness and write the email.","Vale, vale, tienes razón. Solo necesito superar la incomodidad y escribir el correo."],[1,"Exactly! Just be polite and firm. 'I'm thrilled about the offer, and I'd be happy to accept if we can align on the compensation.'","¡Exacto! Solo sé educada y firme. 'Estoy encantada con la oferta y estaría feliz de aceptar si podemos llegar a un acuerdo en la compensación'."],[0,"Wow, that sounds so professional. Can I just hire you to do it for me?","Guau, eso suena muy profesional. ¿Puedo contratarte para que lo hagas por mí?"],[1,"Haha, nice try! But seriously, you've got this. Think of it as your first win at the new company.","¡Jaja, buen intento! Pero en serio, tú puedes con esto. Piénsalo como tu primera victoria en la nueva empresa."],[0,"When you put it that way, it does sound better. Alright, I'm going to draft it now.","Cuando lo pones de esa manera, sí suena mejor. Muy bien, voy a escribir el borrador ahora."],[1,"That's the spirit! Keep me posted on what they say.","¡Esa es la actitud! Mantenme informado de lo que digan."]]},{"id":"vb2-10","nivel":"B2","emoji":"😤","titulo":"Group Project Troubles","tituloEs":"Problemas en un proyecto grupal","personas":[{"nombre":"Marcus","genero":"hombre","rol":"Líder del grupo"},{"nombre":"Grace","genero":"mujer","rol":"Miembro del grupo"},{"nombre":"Danny","genero":"hombre","rol":"El que va atrasado"},{"nombre":"Andre","genero":"hombre","rol":"El mediador"}],"lineas":[[0,"Alright guys, we need to talk. The presentation is next Friday and we're falling behind schedule.","Ok, chicos, tenemos que hablar. La presentación es el próximo viernes y nos estamos quedando atrás."],[1,"Falling behind is an understatement. The research section is basically empty, Danny.","Decir que nos quedamos atrás es poco. La sección de investigación está básicamente vacía, Danny."],[2,"Whoa, hang on. I've been swamped with my other classes. I was going to get to it this weekend.","Oye, espera. He estado hasta el cuello con mis otras clases. Iba a ponerme con eso este fin de semana."],[3,"Okay, let's not point fingers. The point is, what's our game plan to catch up now?","Vale, no nos echemos la culpa. El punto es, ¿cuál es nuestro plan de acción para ponernos al día ahora?"],[0,"Andre's right. Danny, can you realistically finish the research by, say, Sunday night?","Andre tiene razón. Danny, ¿realmente puedes terminar la investigación para, digamos, el domingo por la noche?"],[1,"And it needs to be solid. We can't just throw a few articles together at the last minute.","Y tiene que ser sólida. No podemos simplemente juntar un par de artículos a último momento."],[2,"Yeah, okay, I get it. I've just been really overwhelmed. I can get it done by Sunday, for real.","Sí, está bien, lo entiendo. Es que he estado muy abrumado. Puedo tenerlo listo para el domingo, de verdad."],[3,"How about this: Grace and I can start outlining the slides with what we have. Once you send the research, we'll plug it in.","¿Qué tal esto? Grace y yo podemos empezar a esquematizar las diapositivas con lo que tenemos. En cuanto mandes la investigación, la incorporamos."],[0,"That sounds like a plan. It splits the work more evenly and gives us a buffer.","Eso suena como un plan. Divide el trabajo más equitativamente y nos da un margen."],[1,"Okay, I can work with that. As long as we're all on the same page now.","De acuerdo, puedo aceptar eso. Siempre y cuando estemos todos en la misma sintonía ahora."],[2,"Cool, thanks guys. Sorry for dropping the ball. I'll send you what I have so far tonight.","Genial, gracias chicos. Perdón por fallarles. Les enviaré lo que tengo hasta ahora esta noche."],[3,"Perfect. See? We just needed to sync up. Let's crush this thing.","Perfecto. ¿Ven? Solo necesitábamos sincronizarnos. Vamos a romperla con esto."],[0,"Definitely. Let's meet again on Monday to review everything.","Totalmente. Reunámonos de nuevo el lunes para revisar todo."],[1,"Sounds good. And Danny, if you need help finding sources, just text me.","Suena bien. Y Danny, si necesitas ayuda para encontrar fuentes, solo mándame un mensaje."],[2,"Will do. Thanks, Grace. I appreciate it.","Lo haré. Gracias, Grace. Te lo agradezco."]]},{"id":"vb2-11","nivel":"B2","emoji":"🌱","titulo":"Dinner Talk on Climate Change","tituloEs":"Charla sobre el cambio climático en la cena","personas":[{"nombre":"Logan","genero":"hombre","rol":"Amigo en la cena"},{"nombre":"Claire","genero":"mujer","rol":"Amiga en la cena"},{"nombre":"Jordan","genero":"hombre","rol":"Amigo en la cena"},{"nombre":"Chloe","genero":"mujer","rol":"Amiga en la cena"}],"lineas":[[0,"Did you guys see that article about the record-breaking heat this year? It's honestly getting a little scary.","¿Vieron ese artículo sobre el calor récord de este año? Sinceramente, se está volviendo un poco aterrador."],[1,"I know, right? It feels so overwhelming. I try to do my part, but it feels like a drop in the ocean.","Sí, ¿verdad? Se siente tan abrumador. Intento poner de mi parte, pero parece una gota en el océano."],[2,"Tell me about it. I mean, I recycle, but does it even make a dent when you've got these huge companies doing whatever they want?","Ni me digas. O sea, yo reciclo, pero ¿realmente hace alguna diferencia cuando tienes a estas empresas enormes haciendo lo que les da la gana?"],[3,"I get that, but I think it all adds up. I've been trying to buy less fast fashion and eat less meat. Small changes, you know?","Entiendo eso, pero creo que todo suma. He estado tratando de comprar menos 'fast fashion' y comer menos carne. Pequeños cambios, ¿sabes?"],[0,"That's a great point. You see more people getting on board with things like electric cars. The tide might be turning, slowly but surely.","Ese es un buen punto. Ves a más gente sumándose a cosas como los autos eléctricos. La marea podría estar cambiando, lento pero seguro."],[1,"I suppose so. It's just hard not to feel a bit of eco-anxiety when the news is all doom and gloom.","Supongo que sí. Es que es difícil no sentir un poco de ecoansiedad cuando las noticias son siempre tan pesimistas."],[2,"My carbon footprint is probably the size of a monster truck. But seriously, Chloe, that's impressive. I should probably cut back on my daily Amazon deliveries.","Mi huella de carbono es probablemente del tamaño de un camión monstruo. Pero en serio, Chloe, eso es impresionante. Debería reducir mis entregas diarias de Amazon."],[3,"Hey, every little bit helps! It's not about being perfect, just more mindful. We're all just trying to figure it out.","¡Oye, todo granito de arena ayuda! No se trata de ser perfecto, solo más consciente. Todos estamos intentando ver cómo solucionarlo."],[0,"Exactly. We can't let perfect be the enemy of good. It's about a collective effort.","Exacto. No podemos dejar que lo perfecto sea enemigo de lo bueno. Se trata de un esfuerzo colectivo."],[1,"That’s a much better way of looking at it. It does make it feel more manageable.","Esa es una forma mucho mejor de verlo. Sí que hace que se sienta más manejable."],[2,"Alright, alright, you've twisted my arm. I'll cancel my private jet for tomorrow's commute.","Está bien, está bien, me has convencido. Cancelaré mi jet privado para el viaje al trabajo de mañana."],[3,"See? You're practically a climate hero already!","¿Ves? ¡Ya eres prácticamente un héroe del clima!"],[0,"Speaking of which, I think this wine is organic. So, technically, we're helping.","Hablando de eso, creo que este vino es orgánico. Así que, técnicamente, estamos ayudando."],[1,"In that case, pour me another glass! I'm ready to do my part.","¡En ese caso, sírveme otra copa! Estoy lista para poner de mi parte."],[2,"Now that's a climate solution I can get behind. Cheers to that!","Esa sí es una solución climática que puedo apoyar. ¡Salud por eso!"],[3,"Cheers!","¡Salud!"]]},{"id":"vb2-12","nivel":"B2","emoji":"🏚️","titulo":"Dispute Over the Deposit","tituloEs":"Disputa por el depósito","personas":[{"nombre":"Marcus","genero":"hombre","rol":"inquilino"},{"nombre":"Nicole","genero":"mujer","rol":"amiga del inquilino"}],"lineas":[[0,"I just got off the phone with my landlord. I'm so fed up; he's trying to keep half my security deposit!","Acabo de colgar con el dueño. ¡Estoy tan harto; está tratando de quedarse con la mitad de mi depósito de garantía!"],[1,"No way! For what? I thought you left that place spotless.","¡No puede ser! ¿Por qué? Pensé que habías dejado ese lugar impecable."],[0,"He's claiming 'excessive wear and tear.' He listed a few tiny scuff marks on a wall and wants to charge for a professional deep clean.","Alega un \"desgaste excesivo\". Mencionó unas pequeñas marcas en una pared y quiere cobrar por una limpieza profunda profesional."],[1,"That's ridiculous. That just sounds like normal living. He's totally nickel-and-diming you.","Eso es ridículo. Suena a uso normal por vivir ahí. Te está buscando cualquier pretexto para sacarte dinero."],[0,"I know, right? I took a ton of pictures before I handed over the keys, and the place looked great.","¿Verdad? Tomé un montón de fotos antes de entregar las llaves, y el lugar se veía genial."],[1,"Well, you can't let him get away with it. You should definitely push back.","Bueno, no puedes dejar que se salga con la suya. Definitivamente deberías oponerte."],[0,"I wanted to, but I was so mad I just had to hang up. I didn't want to say something I'd regret.","Quería, pero estaba tan enojado que tuve que colgar. No quería decir algo de lo que me arrepintiera."],[1,"Probably a good call. You should draft a formal letter outlining why the charges are unreasonable. Be polite but firm.","Probablemente fue una buena decisión. Deberías redactar una carta formal explicando por qué los cargos no son razonables. Sé educado pero firme."],[0,"A formal letter? That sounds so serious. I'm not great at that kind of thing.","¿Una carta formal? Suena tan serio. No soy muy bueno para ese tipo de cosas."],[1,"That's the whole point. It shows you mean business. He's probably just hoping you'll give up without a fight.","Ese es el chiste. Demuestra que vas en serio. Probablemente solo espera que te rindas sin luchar."],[0,"You're right. He's banking on me not wanting the hassle. Okay, it's a matter of principle now.","Tienes razón. Está contando con que yo no quiera meterme en líos. Ok, ahora es una cuestión de principios."],[1,"Exactly! Look up the local tenant rights laws and mention them. That usually gets their attention.","¡Exacto! Busca las leyes locales sobre los derechos de los inquilinos y menciónalas. Eso usualmente capta su atención."],[0,"Okay, you've fired me up. I'm going to work on that letter tonight.","Ok, ya me has motivado. Voy a trabajar en esa carta esta noche."],[1,"That's the spirit! I can look it over for you before you send it, if you want.","¡Esa es la actitud! Puedo echarle un vistazo antes de que la envíes, si quieres."],[0,"Would you? That would be a huge help. Thanks, Nicole, I really appreciate it.","¿Lo harías? Eso sería de gran ayuda. Gracias, Nicole, de verdad lo aprecio."],[1,"Of course. Let's get your hard-earned money back.","Por supuesto. Vamos a recuperar ese dinero que tanto te costó ganar."]]},{"id":"vb2-13","nivel":"B2","emoji":"📻","titulo":"The Tipping Point","tituloEs":"El Punto Crítico de las Propinas","personas":[{"nombre":"Zach","genero":"hombre","rol":"presentador de radio"},{"nombre":"Tiffany","genero":"mujer","rol":"oyente que llama"},{"nombre":"Noah","genero":"hombre","rol":"otro oyente que llama"}],"lineas":[[0,"Alright, let's get into it. Tipping seems to be getting a bit out of hand, right? Our first caller is Tiffany. Welcome to the show!","Bien, vamos al grano. Parece que lo de las propinas se está saliendo un poco de control, ¿verdad? Nuestra primera llamada es de Tiffany. ¡Bienvenida al programa!"],[1,"Hi Zach! Yeah, it's wild. I was asked for a tip at a self-checkout kiosk the other day. I just stood there confused.","¡Hola Zach! Sí, es una locura. Me pidieron propina en un quiosco de autopago el otro día. Me quedé ahí parada, confundida."],[0,"No way! For doing what exactly? Scanning your own items?","¡No puede ser! ¿Por hacer qué exactamente? ¿Escanear tus propios productos?"],[1,"Pretty much! And look, I used to wait tables, so I'm a big tipper. But this just feels like it's going too far.","¡Básicamente! Y mira, yo fui mesera, así que doy buenas propinas. Pero siento que esto ya está yendo demasiado lejos."],[0,"I hear you. We've also got Noah on the line. Noah, what's your take on this?","Te entiendo. También tenemos a Noah en la línea. Noah, ¿cuál es tu opinión sobre esto?"],[2,"Hey guys. I'm definitely feeling the 'tip fatigue'. I'm pretty sure I just tipped 20% on a coffee that I poured myself.","Hola a todos. Definitivamente estoy sintiendo la 'fatiga de las propinas'. Estoy casi seguro de que acabo de dar 20% en un café que me serví yo mismo."],[1,"Oh, I've done that! It’s the pressure of the tablet they flip around, you know?","¡Ah, yo he hecho eso! Es la presión de la tableta que te voltean, ¿sabes?"],[0,"The dreaded tablet stare! It looks right into your soul, doesn't it?","¡La temida mirada de la tableta! Te mira directamente al alma, ¿no es así?"],[2,"Totally. It just makes me wonder why companies don't pay their employees a living wage to begin with.","Totalmente. Me hace preguntarme por qué las empresas no les pagan a sus empleados un salario digno para empezar."],[1,"I'm with Noah on that. It would take all the guesswork out of it for us as customers.","Estoy con Noah en eso. Nos quitaría toda la incertidumbre a nosotros como clientes."],[0,"That opens up a whole other can of worms, but it's a valid point. The system is complicated.","Eso abre otra caja de Pandora, pero es un punto válido. El sistema es complicado."],[2,"For sure. I just feel like it's my job to decide on a fair tip, not to be guilted into giving one on a bottle of water.","Sin duda. Solo siento que es mi trabajo decidir una propina justa, no que me hagan sentir culpable por dar una en una botella de agua."],[1,"Exactly! They just turn the screen with this expectant look on their face. It's so awkward.","¡Exacto! Simplemente giran la pantalla con esa mirada expectante en su cara. Es tan incómodo."],[2,"Right? At this rate, we'll be tipping our landlords just for paying rent on time.","¿Verdad? A este paso, le daremos propina a nuestros arrendadores solo por pagar el alquiler a tiempo."],[0,"Haha, let's hope not! Guys, this has been a great conversation. Thanks so much for calling in.","Jaja, ¡esperemos que no! Chicos, esta ha sido una gran conversación. Muchas gracias por llamar."],[1,"Thanks for having me!","¡Gracias por invitarme!"]]},{"id":"vb2-14","nivel":"B2","emoji":"🍺","titulo":"A Friend's Career Change","tituloEs":"El cambio de carrera de un amigo","personas":[{"nombre":"Nate","genero":"hombre","rol":"amigo de Andre"},{"nombre":"Kim","genero":"mujer","rol":"amiga de Andre"},{"nombre":"Andre","genero":"hombre","rol":"quiere cambiar de carrera"}],"lineas":[[0,"Man, another Monday tomorrow. I'm already dreading my inbox.","Uf, mañana es lunes otra vez. Ya me está dando pavor mi bandeja de entrada."],[1,"Tell me about it. Sometimes I just want to throw my laptop out the window.","Ni me digas. A veces solo quiero tirar mi laptop por la ventana."],[2,"You guys are going to think I'm crazy, but I'm seriously thinking about quitting my job.","Van a pensar que estoy loco, pero estoy considerando seriamente renunciar a mi trabajo."],[0,"Whoa, seriously? Where did that come from? I thought you were on track for a promotion.","Vaya, ¿en serio? ¿Y eso de dónde salió? Pensé que estabas en camino a un ascenso."],[1,"Wow, Andre. That's a huge step. What would you do instead? Do you have a plan?","Guau, Andre. Es un paso enorme. ¿Qué harías en su lugar? ¿Tienes algún plan?"],[2,"Well, this is the crazy part. I want to go to culinary school. I'm so sick of spreadsheets.","Bueno, esta es la parte loca. Quiero ir a la escuela de gastronomía. Estoy tan harto de las hojas de cálculo."],[0,"From crunching numbers to chopping onions! That's a complete 180. Are you sure you're not just hungry?","¡De procesar números a picar cebollas! Es un giro de 180 grados. ¿Estás seguro de que no es solo hambre?"],[1,"Hey, don't tease him! I think that's amazing. You've always been a fantastic cook.","¡Oye, no lo molestes! A mí me parece increíble. Siempre has sido un cocinero fantástico."],[2,"Thanks, Kim. It's just... it's a huge risk. Dropping a stable career feels terrifying, you know?","Gracias, Kim. Es que... es un riesgo enorme. Dejar una carrera estable se siente aterrador, ¿sabes?"],[0,"Of course it's scary, but you gotta follow your passion sometimes. Plus, I expect free meals for life.","Claro que da miedo, pero a veces tienes que seguir tu pasión. Además, espero comidas gratis de por vida."],[1,"Exactly! You could start by taking a weekend class, just to dip your toe in the water.","¡Exacto! Podrías empezar con una clase de fin de semana, solo para probar a ver qué tal."],[2,"That's actually a really good idea. It feels a little less overwhelming that way.","De hecho, es una muy buena idea. Así se siente un poco menos abrumador."],[0,"See? You got this. Let's get another round to celebrate your future as a world-famous chef.","¿Ves? Tú puedes. Pidamos otra ronda para celebrar tu futuro como chef de fama mundial."],[1,"I'll drink to that! To Chef Andre and his new adventure!","¡Brindo por eso! ¡Por el Chef Andre y su nueva aventura!"],[2,"Haha, thanks, you guys. It really means a lot to hear you say that.","Jaja, gracias, chicos. Significa mucho para mí escucharles decir eso."]]},{"id":"vb2-15","nivel":"B2","emoji":"🧘","titulo":"Therapy Session on Stress","tituloEs":"Sesión de terapia sobre el estrés","personas":[{"nombre":"Linda","genero":"mujer","rol":"terapeuta"},{"nombre":"Derek","genero":"hombre","rol":"paciente"}],"lineas":[[0,"Hi Derek, come on in. So, how have things been since our last session?","Hola Derek, pasa. Y bien, ¿cómo han estado las cosas desde nuestra última sesión?"],[1,"Hey, Linda. Honestly, I've been feeling pretty swamped. It's like I'm juggling a dozen things at once and I'm about to drop them all.","Hola, Linda. La verdad, me he sentido bastante abrumado. Es como si estuviera haciendo malabares con mil cosas a la vez y estuviera a punto de que se me caigan todas."],[0,"I hear you. That sounds incredibly stressful. When you say you're juggling things, what's taking up most of your energy right now?","Te entiendo. Suena increíblemente estresante. Cuando dices que estás haciendo malabares, ¿qué es lo que está consumiendo la mayor parte de tu energía ahora mismo?"],[1,"It’s the usual suspect, work. But then all the little life things just pile on top of it, you know?","Es lo de siempre, el trabajo. Pero luego todas las pequeñas cosas de la vida se van acumulando, ¿sabes?"],[0,"Could you give me an example of one of those 'little things' that felt big this week?","¿Podrías darme un ejemplo de una de esas 'cosas pequeñas' que se sintió grande esta semana?"],[1,"Well, the other day I was on a tight deadline, and my car decided it wouldn't start. It just felt like, 'Of course this would happen now!'","Bueno, el otro día tenía una fecha de entrega muy justa y a mi carro se le ocurrió no arrancar. Sentí como, '¡Claro, esto tenía que pasar ahora!'"],[0,"Right. It's that feeling of being kicked when you're already down. It's understandable why that would push your stress levels through the roof.","Claro. Es esa sensación de que te llueve sobre mojado. Es comprensible que eso disparara tus niveles de estrés por las nubes."],[1,"Exactly! My brain feels like it has way too many tabs open, and they're all playing different, loud music.","¡Exacto! Siento que mi cerebro tiene demasiadas pestañas abiertas, y todas están tocando música diferente a todo volumen."],[0,"That's a great analogy. It seems the problem isn't that you can't handle the tasks, but that you feel pressured to handle them all simultaneously.","Es una gran analogía. Parece que el problema no es que no puedas con las tareas, sino que te sientes presionado a manejarlas todas simultáneamente."],[1,"Yeah, I feel like I'm constantly switching gears but not making any real progress. It's exhausting.","Sí, siento que estoy constantemente cambiando de enfoque pero sin avanzar realmente. Es agotador."],[0,"Okay, so let's try a different approach. What if, for this week, we don't try to close all those tabs?","Ok, entonces probemos un enfoque diferente. ¿Qué tal si, por esta semana, no intentamos cerrar todas esas pestañas?"],[1,"What do you mean? Just let the chaos continue?","¿A qué te refieres? ¿Simplemente dejar que el caos continúe?"],[0,"Not exactly. Let's just focus on one or two. Pick the most important one for work and one for your personal life, and give them your full attention.","No exactamente. Enfoquémonos solo en una o dos. Elige la más importante del trabajo y una de tu vida personal, y dales toda tu atención."],[1,"So, just consciously decide to ignore the other stuff for a bit? Is that even allowed?","Entonces, ¿decidir conscientemente ignorar lo demás por un rato? ¿Acaso eso está permitido?"],[0,"It's not just allowed, it's necessary. It's about managing your focus. Let's see how it feels to give yourself that permission.","No solo está permitido, es necesario. Se trata de gestionar tu enfoque. Veamos qué se siente darte a ti mismo ese permiso."],[1,"Huh. That actually takes a weight off my shoulders just thinking about it. Okay, I can try that.","Vaya. La verdad es que me quita un peso de encima solo de pensarlo. Ok, puedo intentar eso."],[0,"Perfect. Let's check in on how that went next week. You're making great progress.","Perfecto. Revisemos cómo te fue con eso la próxima semana. Estás logrando un gran progreso."]]},{"id":"vb2-16","nivel":"B2","emoji":"🔧","titulo":"A Rip-Off at the Mechanic","tituloEs":"Una Estafa en el Taller Mecánico","personas":[{"nombre":"Nate","genero":"hombre","rol":"Cliente insatisfecho"},{"nombre":"Paige","genero":"mujer","rol":"Amiga solidaria"}],"lineas":[[0,"You are not going to believe what the mechanic just charged me. I'm pretty sure I got ripped off.","No vas a creer lo que me acaba de cobrar el mecánico. Estoy bastante seguro de que me estafaron."],[1,"Oh no, really? What happened? I'm always so paranoid about that stuff.","Ay no, ¿en serio? ¿Qué pasó? A mí siempre me da pánico ese tema."],[0,"The final bill was almost double the estimate! They billed me for three hours of labor for a job that couldn't have taken more than one.","¡La factura final fue casi el doble del presupuesto! Me facturaron tres horas de mano de obra por un trabajo que no pudo haber tomado más de una."],[1,"No way! Three hours is ridiculous. Did you call them out on it when you were there?","¡No puede ser! Tres horas es ridículo. ¿Se lo reclamaste cuando estabas allí?"],[0,"I tried, but the guy got all defensive and started throwing around a bunch of technical terms. I just ended up paying to get out of there.","Lo intenté, pero el tipo se puso a la defensiva y empezó a soltar un montón de términos técnicos. Simplemente terminé pagando para poder irme."],[1,"Ugh, that's such a classic move. They bank on people feeling too intimidated to argue back.","Uf, esa es una jugada tan clásica. Cuentan con que la gente se sienta demasiado intimidada como para responder."],[0,"Exactly! Now I'm kicking myself for not pushing back harder.","¡Exacto! Ahora me estoy arrepintiendo por no haber presionado más."],[1,"Don't be so hard on yourself; it happens to the best of us. You should definitely call the manager tomorrow, though.","No seas tan duro contigo mismo; nos pasa hasta a los mejores. Eso sí, definitivamente deberías llamar al gerente mañana."],[0,"Do you really think it's worth the hassle? I mean, I already paid.","¿De verdad crees que vale la pena la molestia? Digo, ya pagué."],[1,"One hundred percent. It's the principle of the thing. Plus, what do you have to lose? You might get some money back.","Cien por ciento. Es por una cuestión de principios. Además, ¿qué tienes que perder? Podrías recuperar algo de dinero."],[0,"I guess you have a point. I just really hate confrontation.","Supongo que tienes razón. Es que de verdad odio la confrontación."],[1,"I get it, but sometimes you just have to stand up for yourself. Just be calm and polite when you explain the situation.","Lo entiendo, pero a veces simplemente tienes que hacerte valer. Solo mantén la calma y sé amable cuando expliques la situación."],[0,"Okay, okay, you've talked me into it. I'll give them a call in the morning.","Está bien, está bien, me has convencido. Les llamaré por la mañana."],[1,"Good! Let me know how it goes. If they give you a hard time, a bad online review usually gets their attention.","¡Bien! Avísame cómo te va. Si te ponen pegas, una mala reseña en internet usualmente llama su atención."],[0,"Haha, that's a great backup plan. Thanks for the pep talk, Paige.","Jaja, ese es un gran plan B. Gracias por la charla motivacional, Paige."]]},{"id":"vb2-17","nivel":"B2","emoji":"🎊","titulo":"Planning a Surprise Party","tituloEs":"Planeando una fiesta sorpresa","personas":[{"nombre":"Megan","genero":"mujer","rol":"colega de David"},{"nombre":"Jake","genero":"hombre","rol":"colega de David"},{"nombre":"Max","genero":"hombre","rol":"colega de David"},{"nombre":"Lucas","genero":"hombre","rol":"colega de David"}],"lineas":[[0,"Okay, so we're all on the same page about David's surprise retirement party, right? We have to pull this off perfectly.","Bueno, ¿estamos todos de acuerdo con la fiesta sorpresa de jubilación para David, verdad? Tiene que salirnos perfecto."],[1,"Absolutely. I was thinking we could just have it here at the office after work next Friday. Keep it simple.","Totalmente. Estaba pensando que podríamos hacerla aquí en la oficina después del trabajo el próximo viernes. Algo sencillo."],[2,"The office? C'mon, Jake, that's a bit lame for a guy who's been here 30 years. We should go all out!","¿La oficina? Vamos, Jake, eso es un poco aburrido para alguien que ha estado aquí 30 años. ¡Deberíamos tirar la casa por la ventana!"],[3,"Max has a point. What about that little Italian place downtown, \"Vittorio's\"? Their private room is pretty nice.","Max tiene razón. ¿Qué tal ese pequeño restaurante italiano en el centro, \"Vittorio's\"? Su salón privado es bastante agradable."],[0,"Ooh, I like that idea. I can call them to check availability and pricing. What about a cake? We can't forget the cake.","Uy, me gusta esa idea. Puedo llamar para ver si tienen disponibilidad y precios. ¿Y el pastel? No podemos olvidarnos del pastel."],[1,"Good call. And we should all chip in for a gift. Maybe a nice watch or something for his fishing hobby?","Buena idea. Y deberíamos cooperar todos para un regalo. ¿Quizás un buen reloj o algo para su pasatiempo de pesca?"],[2,"Or we could get him a life-sized cardboard cutout of himself to remember us by. Just kidding... mostly.","O podríamos regalarle una figura de cartón de tamaño real de sí mismo para que nos recuerde. Es broma... más o menos."],[3,"Ha! Let's stick with the fishing gear. I can put together a list of gift ideas and we can vote.","¡Ja! Mejor quedémonos con el equipo de pesca. Puedo armar una lista de ideas de regalos y votamos."],[0,"Perfect. So, Lucas, you're on gifts. I'll handle the venue and cake. Jake, can you manage the invitations and RSVPs?","Perfecto. Entonces, Lucas, tú te encargas de los regalos. Yo me ocupo del lugar y el pastel. Jake, ¿puedes gestionar las invitaciones y las confirmaciones?"],[1,"You got it. I'll create a group chat, but we have to be super careful David doesn't find out.","Claro que sí. Crearé un chat grupal, pero tenemos que ser súper cuidadosos de que David no se entere."],[2,"My lips are sealed. But you know how chatty Linda from accounting is. We need to make sure she doesn't spill the beans.","Por mi boca no saldrá nada. Pero ya sabes cómo es de habladora Linda de contabilidad. Tenemos que asegurarnos de que no se le escape nada."],[3,"Right. Maybe just tell her the day before. We can't risk David overhearing anything. He has ears like a hawk.","Cierto. Quizás solo deberíamos decirle el día anterior. No podemos arriesgarnos a que David escuche algo. Tiene un oído de halcón."],[0,"Okay, good thinking. Let's keep the circle of trust small for now.","Ok, bien pensado. Mantengamos el círculo de confianza pequeño por ahora."],[1,"So, Megan, once you hear back from the restaurant, let us know the cost per person.","Entonces, Megan, cuando te respondan del restaurante, avísanos el costo por persona."],[2,"Yeah, I need to know how much this is gonna set me back. I hope David appreciates us!","Sí, necesito saber cuánto me va a costar esto. ¡Espero que David nos lo agradezca!"],[3,"He will. This is going to be great, guys. He'll be totally surprised.","Lo hará. Esto va a ser genial, chicos. Se va a llevar una sorpresa total."]]},{"id":"vb2-18","nivel":"B2","emoji":"🌳","titulo":"New Park Neighborhood Meeting","tituloEs":"Reunión de vecinos sobre el parque nuevo","personas":[{"nombre":"Lauren","genero":"mujer","rol":"vecina, organizadora"},{"nombre":"Jordan","genero":"hombre","rol":"vecino práctico"},{"nombre":"Lucas","genero":"hombre","rol":"vecino entusiasta"},{"nombre":"Emma","genero":"mujer","rol":"vecina conciliadora"}],"lineas":[[0,"Alright everyone, thanks for coming. The city sent over the final draft for the new park. What are our initial thoughts?","Bueno, gracias a todos por venir. La municipalidad nos envió el borrador final para el parque nuevo. ¿Cuáles son sus primeras impresiones?"],[1,"I'm thrilled we're finally getting it, but I've got to be honest, the proposed location for the dog run seems a bit... close to the street.","Estoy encantado de que por fin lo tengamos, pero siendo sincero, la ubicación propuesta para el área de perros me parece un poco... cerca de la calle."],[2,"Oh, I hadn't even gotten to that! I was too busy getting excited about the open field. We could totally set up a community pickleball court there!","¡Ah, ni siquiera había llegado a esa parte! Estaba demasiado emocionado con el campo abierto. ¡Podríamos totalmente instalar una cancha de pickleball comunitaria ahí!"],[3,"Pickleball! I love that. And it's something that people of all ages could get into. That’s fantastic for building community spirit.","¡Pickleball! Me encanta. Y es algo en lo que gente de todas las edades puede participar. Eso es fantástico para crear un espíritu comunitario."],[0,"That's a great point, Emma. And Jordan, I see what you mean about the dog run. It does seem like a safety issue.","Ese es un buen punto, Emma. Y Jordan, entiendo lo que dices del área de perros. Sí parece un problema de seguridad."],[1,"Exactly. I'm just picturing a dog darting out into traffic. It gives me the chills just thinking about it.","Exacto. Ya me estoy imaginando a un perro saliendo disparado hacia el tráfico. Me da escalofríos solo de pensarlo."],[2,"Okay, fair enough. Safety first. But we're not giving up on pickleball, are we? The courts are always packed over in Northwood.","Ok, es justo. La seguridad es primero. Pero no vamos a renunciar al pickleball, ¿o sí? Las canchas por Northwood siempre están llenísimas."],[3,"Of course not! What if we suggest swapping the dog run area with the proposed community garden plot? The garden would be a nice, quiet buffer.","¡Claro que no! ¿Qué tal si sugerimos intercambiar el área para perros con el terreno para el huerto comunitario? El huerto sería una buena y tranquila barrera."],[0,"That’s a brilliant idea, Emma. That solves both problems at once. Jordan, would that work for you?","Esa es una idea brillante, Emma. Resuelve ambos problemas a la vez. Jordan, ¿te parecería bien?"],[1,"Yeah, that works. As long as my prize-winning tomatoes aren't being used as a fire hydrant, I'm on board.","Sí, funciona. Mientras mis tomates de concurso no sean usados como un hidrante, yo me apunto."],[2,"Haha, my dog has impeccable taste! But seriously, with that sorted, we're golden. Pickleball here we come!","¡Jaja, mi perro tiene un gusto impecable! Pero en serio, con eso resuelto, estamos listos. ¡Allá vamos, pickleball!"],[3,"It feels like we're striking a good balance between active spaces and quiet spots. I think we're on the right track now.","Siento que estamos logrando un buen equilibrio entre espacios activos y lugares tranquilos. Creo que ahora vamos por buen camino."],[0,"I completely agree. It’s all about finding that middle ground. So, are we all in favor of proposing those two changes?","Totalmente de acuerdo. Se trata de encontrar ese punto medio. Entonces, ¿estamos todos a favor de proponer esos dos cambios?"],[1,"You bet. It’s a much better plan this way.","Claro que sí. Es un plan mucho mejor así."],[3,"Definitely. This is going to be a wonderful addition to the neighborhood. I can already picture it.","Definitivamente. Esta va a ser una adición maravillosa para el vecindario. Ya me lo puedo imaginar."],[2,"Me too! Okay, I’ll offer to draft an email with the suggestions. I can send it to you for review, Lauren.","¡Yo también! Ok, me ofrezco a preparar un borrador del correo con las sugerencias. Te lo puedo enviar para que lo revises, Lauren."],[0,"Oh, thanks, Lucas! That'd be a huge help. Great, productive meeting everyone.","¡Oh, gracias, Lucas! Sería de gran ayuda. Genial, qué reunión tan productiva, gente."]]},{"id":"vb2-19","nivel":"B2","emoji":"👩‍🍳","titulo":"The Secret Sauce of a Chef","tituloEs":"El ingrediente secreto de una chef","personas":[{"nombre":"Abby","genero":"mujer","rol":"Chef"},{"nombre":"Wes","genero":"hombre","rol":"Periodista"}],"lineas":[[1,"Abby, thanks for sitting down with me. Your restaurant is the talk of the town right now.","Abby, gracias por sentarte a conversar conmigo. Tu restaurante está en boca de todos ahora mismo."],[0,"It's my pleasure. It's been a whirlwind, but a good one.","Es un placer. Ha sido un torbellino, pero uno bueno."],[1,"I can imagine. So, everyone wants to know, what’s the secret sauce? What makes this place stand out?","Me lo imagino. Bueno, todos quieren saber, ¿cuál es el ingrediente secreto? ¿Qué hace que este lugar se destaque?"],[0,"Ha, secret sauce. Literally? It's probably the garlic aioli. But figuratively, I think it's that we don't take ourselves too seriously.","Ja, el ingrediente secreto. ¿Literalmente? Probablemente sea el alioli de ajo. Pero en sentido figurado, creo que es que no nos tomamos demasiado en serio."],[1,"How so? Your technique is obviously top-notch.","¿Cómo es eso? Tu técnica es obviamente de primera."],[0,"Thanks, but we throw out the rulebook sometimes. If a 'cheap' ingredient makes a dish better, we use it. We're not trying to be fancy just for the sake of it.","Gracias, pero a veces rompemos las reglas. Si un ingrediente 'barato' mejora un plato, lo usamos. No intentamos ser elegantes solo por aparentar."],[1,"That definitely comes through. The crispy potato dish, for example, is so simple but it’s just... perfect.","Eso definitivamente se nota. El plato de patatas crujientes, por ejemplo, es tan simple pero es simplemente... perfecto."],[0,"That’s my favorite! It’s the dish I make for myself at home when I'm tired. It’s like a hug in a bowl.","¡Ese es mi favorito! Es el plato que me preparo en casa cuando estoy cansada. Es como un abrazo en un tazón."],[1,"I love that. You've been a chef for, what, over 15 years? Has your philosophy changed much over time?","Me encanta eso. Has sido chef por, ¿qué, más de 15 años? ¿Ha cambiado mucho tu filosofía con el tiempo?"],[0,"Oh, completely. I used to be obsessed with perfection, with every plate being a work of art. Now I'm much more focused on flavor and feeling.","Oh, completamente. Antes estaba obsesionada con la perfección, con que cada plato fuera una obra de arte. Ahora estoy mucho más enfocada en el sabor y el sentimiento."],[1,"So you've sort of come full circle, back to the basics?","Así que de alguna manera has cerrado el círculo, ¿de vuelta a lo básico?"],[0,"In a way, yes. But with better knife skills this time around! It's about making food that makes people happy, plain and simple.","En cierto modo, sí. ¡Pero con mejor técnica con el cuchillo esta vez! Se trata de hacer comida que haga feliz a la gente, así de simple."],[1,"Well, you're certainly succeeding. Any hints about what we can look forward to next on the menu?","Bueno, ciertamente lo estás logrando. ¿Alguna pista sobre qué podemos esperar próximamente en el menú?"],[0,"I'm playing around with some seasonal dessert ideas. I'm thinking something with peaches and basil, if I can get the balance right.","Estoy experimentando con algunas ideas de postres de temporada. Estoy pensando en algo con duraznos y albahaca, si logro encontrar el equilibrio correcto."],[1,"That sounds incredible. I'll have to come back to try it. Thank you so much for your time, Abby.","Eso suena increíble. Tendré que volver para probarlo. Muchísimas gracias por tu tiempo, Abby."],[0,"Anytime, Wes. It was great chatting with you.","Cuando quieras, Wes. Fue un gusto conversar contigo."]]},{"id":"vb2-20","nivel":"B2","emoji":"👵","titulo":"What to Do About Grandma","tituloEs":"Qué hacer con la abuela","personas":[{"nombre":"Greg","genero":"hombre","rol":"hijo"},{"nombre":"Carol","genero":"mujer","rol":"nuera"},{"nombre":"Natalie","genero":"mujer","rol":"hija"}],"lineas":[[0,"Alright, we need to have a serious talk about Mom. I got a call from her doctor this morning.","Bueno, tenemos que hablar en serio sobre mamá. Me llamó su doctor esta mañana."],[1,"Oh, no. Is she okay? I've been a bit worried ever since she took that tumble last week.","Ay, no. ¿Está bien? He estado un poco preocupada desde que se dio ese tropezón la semana pasada."],[2,"She told me she's fine. Honestly, I think she’s just getting a little clumsy in her old age.","Ella me dijo que está bien. Sinceramente, creo que solo se está volviendo un poco torpe con la edad."],[0,"Well, the doctor doesn't think so. He strongly recommended that she shouldn't be living by herself anymore.","Pues, el doctor no piensa así. Recomendó firmemente que ya no debería vivir sola."],[1,"I hate to say it, but I agree. Maybe we should start looking into some nice assisted living places near us.","Odio decirlo, pero estoy de acuerdo. Quizás deberíamos empezar a buscar algunos buenos asilos de ancianos cerca de nosotros."],[2,"A nursing home? Absolutely not. We can't just stick her in a home and forget about her.","¿Un asilo? Para nada. No podemos simplemente meterla en un lugar de esos y olvidarnos de ella."],[0,"Natalie, let's be realistic. We all work full-time. Who’s going to make sure she’s safe all day?","Natalie, seamos realistas. Todos trabajamos a tiempo completo. ¿Quién se va a asegurar de que esté a salvo todo el día?"],[1,"He's got a point. It's a massive undertaking. We need to consider what's actually practical for everyone.","Él tiene razón. Es una tarea enorme. Tenemos que considerar lo que es realmente práctico para todos."],[2,"So? We'll figure it out. I can work from home a few days a week, and we could hire some part-time help.","¿Y qué? Ya lo resolveremos. Puedo trabajar desde casa un par de días a la semana, y podríamos contratar a alguien de medio tiempo."],[0,"Hiring a caregiver... That’s actually not a bad idea. It would be pricey, but it's worth exploring.","Contratar a una cuidadora... En realidad no es una mala idea. Sería costoso, pero vale la pena explorarlo."],[1,"And I could pop in during my lunch break to check on her on the days I work from home. It could work.","Y yo podría pasar a verla durante mi hora de almuerzo los días que trabajo desde casa. Podría funcionar."],[2,"See? It’s doable. I just want her to be with family. She'd be miserable otherwise.","¿Ven? Es factible. Solo quiero que esté con la familia. Sería muy infeliz de otra manera."],[0,"You're right. Okay, let's crunch the numbers and try to put together a weekly schedule.","Tienes razón. De acuerdo, hagamos los cálculos e intentemos armar un horario semanal."],[1,"I like the sound of that. I'll start researching home care agencies tonight.","Me gusta cómo suena eso. Empezaré a investigar agencias de cuidado en casa esta noche."],[2,"Thank you, guys. I knew we could come up with a better solution if we put our heads together.","Gracias, chicos. Sabía que podríamos encontrar una solución mejor si lo pensábamos juntos."]]},{"id":"vb2-21","nivel":"B2","emoji":"🛎️","titulo":"The Overbooked Upgrade","tituloEs":"La mejora por sobreventa","personas":[{"nombre":"Rosa","genero":"mujer","rol":"huésped del hotel"},{"nombre":"Sam","genero":"hombre","rol":"recepcionista"}],"lineas":[[0,"Hi there, I'm checking in. The reservation is under Rosa Vargas.","Hola, vengo a registrarme. La reserva está a nombre de Rosa Vargas."],[1,"Welcome, Ms. Vargas. Let me just pull that up... Ah. It seems we've run into a bit of a snag. We're overbooked tonight.","Bienvenida, Sra. Vargas. Permítame buscarla... Ah. Parece que hemos tenido un pequeño contratiempo. Tenemos sobreventa esta noche."],[0,"Overbooked? You've got to be kidding me. I have a confirmation email from three months ago.","¿Sobreventa? Tienes que estar bromeando. Tengo un correo de confirmación de hace tres meses."],[1,"I completely understand your frustration, and I am truly sorry. We can arrange a room for you at our sister hotel just down the street.","Entiendo completamente su frustración y de verdad lo siento. Podemos conseguirle una habitación en nuestro hotel afiliado, justo al final de la calle."],[0,"Hmm, I'm not thrilled about that. I picked this hotel for a reason. Just sending me elsewhere doesn't really cut it.","Mmm, eso no me entusiasma. Elegí este hotel por una razón. Simplemente enviarme a otro lugar no es una solución aceptable."],[1,"You're right, it's a major inconvenience. Let me just check one more thing... Sometimes we get last-minute cancellations.","Tiene razón, es una gran molestia. Déjeme revisar una cosa más... A veces tenemos cancelaciones de último minuto."],[0,"I'd appreciate that. After a long flight, the last thing I want to do is haul my luggage to another hotel.","Se lo agradecería. Después de un vuelo largo, lo último que quiero hacer es acarrear mi equipaje a otro hotel."],[1,"Okay, so... this is unusual, but it looks like our junior suite is actually free due to a system glitch. It wasn't showing up before.","Ok, entonces... esto es inusual, pero parece que nuestra junior suite está de hecho libre debido a un error del sistema. No aparecía antes."],[0,"A junior suite? Well, that's a step in the right direction. What's the catch?","¿Una junior suite? Bueno, eso es un paso en la dirección correcta. ¿Cuál es el truco?"],[1,"No catch at all. To make up for our mistake, we can offer it to you for the same rate as your original booking.","Ningún truco. Para compensar nuestro error, podemos ofrecérsela por la misma tarifa de su reserva original."],[0,"For the same rate? Alright, that seems fair. I can live with that solution.","¿Por la misma tarifa? De acuerdo, eso parece justo. Puedo aceptar esa solución."],[1,"Excellent. And how about we throw in complimentary breakfast for your troubles as well?","Excelente. ¿Y qué tal si le incluimos el desayuno de cortesía por las molestias también?"],[0,"Now you're talking! That would be wonderful, thank you so much.","¡Ahora sí nos entendemos! Eso sería maravilloso, muchas gracias."],[1,"My pleasure. Let me get your keys ready. We appreciate your understanding.","Es un placer. Permítame preparar sus llaves. Agradecemos su comprensión."],[0,"This definitely makes up for the rocky start. Thanks again.","Esto definitivamente compensa el mal comienzo. Gracias de nuevo."]]},{"id":"vb2-22","nivel":"B2","emoji":"📱","titulo":"Tech Support for Dad","tituloEs":"Soporte técnico para papá","personas":[{"nombre":"Eli","genero":"hombre","rol":"papá"},{"nombre":"Abby","genero":"mujer","rol":"hija"}],"lineas":[[0,"Abby, thank goodness you picked up. I'm about to throw this phone out the window.","Abby, qué bueno que contestaste. Estoy a punto de tirar este teléfono por la ventana."],[1,"Whoa, Dad, what's wrong? Deep breaths. What did the phone do now?","Uy, papá, ¿qué pasa? Respira hondo. ¿Qué hizo el teléfono ahora?"],[0,"I'm trying to open that social media thing with the bird, and it's just gone! I can't find it anywhere.","Estoy intentando abrir esa cosa de redes sociales del pajarito, ¡y simplemente desapareció! No la encuentro por ningún lado."],[1,"The bird? Oh, you mean Twitter. They changed the name and the icon a while back, remember? It's called 'X' now.","¿El pajarito? Ah, te refieres a Twitter. Le cambiaron el nombre y el ícono hace un tiempo, ¿recuerdas? Ahora se llama 'X'."],[0,"X? Why on earth would they call it X? It sounds so sinister. I'm looking, but I don't see any 'X'.","¿X? ¿Por qué diablos le pondrían X? Suena tan siniestro. Estoy buscando, pero no veo ninguna 'X'."],[1,"It should be a black square with a white X on it. Did you maybe accidentally drag it into a folder?","Debería ser un cuadrado negro con una X blanca. ¿Quizás lo arrastraste a una carpeta sin querer?"],[0,"A folder? How would I even do that? This is getting way too complicated. I just want to see what your uncle posted.","¿Una carpeta? ¿Cómo haría eso siquiera? Esto se está complicando demasiado. Solo quiero ver lo que publicó tu tío."],[1,"Okay, okay, don't give up on me. Let's try the easy fix first. Have you tried turning the phone off and on again?","Vale, vale, no te des por vencido. Probemos primero la solución fácil. ¿Has intentado apagar y encender el teléfono de nuevo?"],[0,"You always say that... Alright, hold on a sec. Let me do it.","Siempre dices eso... Bueno, espera un segundo. Déjame hacerlo."],[1,"Just let me know when it's back on.","Solo avísame cuando se haya vuelto a encender."],[0,"Okay, it's back on. I'm looking... Hey! There it is! The black X thing. You're a genius, sweetheart.","Vale, ya se encendió. Estoy buscando... ¡Oye! ¡Ahí está! La cosa esa negra de la X. Eres una genio, cariño."],[1,"Haha, not a genius, Dad. It's just the oldest trick in the book. It usually clears up any little software glitches.","Jaja, no soy una genio, papá. Es solo el truco más viejo del mundo. Normalmente soluciona cualquier pequeña falla de software."],[0,"Well, you certainly saved the day. So, I didn't just call to get my phone fixed. How have you been?","Bueno, ciertamente me salvaste el día. Oye, no solo llamé para que me arreglaran el teléfono. ¿Cómo has estado?"],[1,"I'm doing great, Dad. It's good to hear your voice. What's been going on with you and Mom?","Estoy muy bien, papá. Qué bueno oír tu voz. ¿Qué han estado haciendo tú y mamá?"],[0,"We were just talking about coming up to visit next weekend, actually. Would you be free?","De hecho, justo hablábamos de ir a visitarte el próximo fin de semana. ¿Estarías libre?"]]},{"id":"vb2-23","nivel":"B2","emoji":"🏀","titulo":"After the Final Whistle","tituloEs":"Después del pitazo final","personas":[{"nombre":"Abby","genero":"mujer","rol":"Jugadora del equipo"},{"nombre":"Lucas","genero":"hombre","rol":"Jugador del equipo"},{"nombre":"Ava","genero":"mujer","rol":"Jugadora del equipo"},{"nombre":"Tasha","genero":"mujer","rol":"Jugadora del equipo"}],"lineas":[[0,"Ugh, that was rough. I can't believe we let that slip away in the final minutes.","Uf, qué duro. No puedo creer que lo hayamos dejado escapar en los últimos minutos."],[1,"Tell me about it. We had them on the ropes. I'm still replaying that last play in my head.","Ni me digas. Los teníamos contra las cuerdas. Sigo repasando esa última jugada en mi cabeza."],[2,"I know, right? But to be fair, we were playing on fumes by the end. We just ran out of gas.","Ya sé, ¿verdad? Pero para ser justos, ya estábamos jugando con lo último de energía al final. Simplemente nos quedamos sin gasolina."],[3,"For real. My legs feel like noodles. Did you see their goalie, though? She was like a brick wall.","Totalmente. Siento las piernas como fideos. ¿Pero vieron a su portera? Era como un muro de ladrillos."],[0,"Seriously! I swear she has eight arms. That one save she made on my shot was just insane.","¡En serio! Juro que tiene ocho brazos. Esa parada que hizo en mi tiro fue simplemente una locura."],[1,"You almost had her, though. We can't beat ourselves up too much. We played a solid game for the most part.","Pero casi la vences. No podemos castigarnos demasiado. Jugamos un partido sólido en su mayor parte."],[2,"That's true. Our defense was way tighter than last week. We just fell apart a bit at the very end.","Es verdad. Nuestra defensa estuvo mucho más sólida que la semana pasada. Solo nos desmoronamos un poco justo al final."],[3,"And maybe we could try not hitting the post three times? Just throwing it out there.","¿Y tal vez podríamos intentar no pegarle al poste tres veces? Solo lo comento por si acaso."],[0,"Haha, okay, fair point. Two of those were mine, so I'll own that. My bad.","Jaja, ok, buen punto. Dos de esos fueron míos, así que asumo la culpa. Culpa mía."],[1,"It's a team loss. We win together, we lose together... and we hit posts together, apparently.","Es una derrota de equipo. Ganamos juntos, perdemos juntos... y le pegamos a los postes juntos, al parecer."],[2,"I think hitting the post is your specialty, actually.","De hecho, creo que pegarle al poste es tu especialidad."],[3,"Ooh, shots fired! But she's not wrong, Lucas.","¡Uy, qué golpe! Pero no se equivoca, Lucas."],[1,"Hey! Okay, maybe a little. Anyway, who's up for pizza? I'm starving and I need to drown my sorrows.","¡Oye! Bueno, tal vez un poco. En fin, ¿quién quiere pizza? Me muero de hambre y necesito ahogar mis penas."],[0,"You don't have to ask me twice. Pizza sounds like the perfect cure for this.","No tienes que preguntármelo dos veces. La pizza suena como la cura perfecta para esto."],[2,"I'm in. Let's get out of here. We'll bounce back next week.","Me apunto. Vámonos de aquí. Nos recuperaremos la próxima semana."],[3,"Absolutely. On to the next one.","Absolutamente. A pensar en el siguiente."]]},{"id":"vb2-24","nivel":"B2","emoji":"🛣️","titulo":"Road Trip Budget Calculations","tituloEs":"Cálculos del presupuesto para el viaje","personas":[{"nombre":"Justin","genero":"hombre","rol":"el organizador"},{"nombre":"Erin","genero":"mujer","rol":"la pragmática"},{"nombre":"Brandon","genero":"hombre","rol":"el optimista"}],"lineas":[[0,"Alright, I've run the numbers, and... oof. This road trip might be a bit pricier than we initially thought.","Bueno, ya hice los cálculos, y... uf. Este viaje por carretera podría ser un poco más caro de lo que pensamos inicialmente."],[1,"Really? Let me see. Oh, wow. Did you factor in how crazy gas prices are right now? That alone is going to eat up a huge chunk of the budget.","¿En serio? A ver. Oh, vaya. ¿Consideraste lo carísimos que están los precios de la gasolina ahora? Solo eso se va a comer una gran parte del presupuesto."],[2,"Come on, guys, don't be downers. We can totally make this work. We'll just pack a cooler and live off sandwiches for a bit.","Vamos, chicos, no sean pesimistas. Podemos lograrlo totalmente. Simplemente llevaremos una hielera y viviremos de sándwiches por un tiempo."],[0,"Live off sandwiches? For ten days? I'm not sure my stomach is on board with that specific plan, Brandon.","¿Vivir de sándwiches? ¿Por diez días? No estoy seguro de que mi estómago esté de acuerdo con ese plan específico, Brandon."],[1,"He's got a point, though. We could save a ton on food. Eating out three times a day would add up so fast.","Sin embargo, tiene razón en algo. Podríamos ahorrar un montón en comida. Comer fuera tres veces al día se acumularía muy rápido."],[2,"Exactly! And think of the epic picnic spots we'll find. It's all part of the adventure. Who needs a fancy restaurant anyway?","¡Exacto! Y piensen en los lugares épicos para hacer picnic que encontraremos. Todo es parte de la aventura. ¿Quién necesita un restaurante elegante de todos modos?"],[0,"Okay, fine, you've sold me on the picnics. But what about lodging? The motels along that route aren't exactly cheap.","Está bien, de acuerdo, me convenciste con los picnics. Pero, ¿qué hay del alojamiento? Los moteles en esa ruta no son precisamente baratos."],[1,"I was looking into that. Some places offer better rates if we book way in advance. We should probably lock those down this week.","Estuve investigando eso. Algunos lugares ofrecen mejores tarifas si reservamos con mucha antelación. Probablemente deberíamos asegurarlos esta semana."],[2,"Good call, Erin. And hey, maybe we can find a campsite for a night or two? That would definitely cut costs and be fun.","Buena idea, Erin. Y oigan, ¿quizás podamos encontrar un lugar para acampar por una noche o dos? Eso definitivamente reduciría los costos y sería divertido."],[0,"Camping... now that's an idea. As long as it doesn't pour rain the whole time. I'm not bailing you guys out if you get soaked.","Acampar... esa sí es una idea. Siempre y cuando no llueva a cántaros todo el tiempo. No voy a rescatarlos si se empapan."],[1,"Deal. So, a mix of pre-booked motels, lots of sandwiches, and a bit of camping. It's starting to sound more manageable.","Trato hecho. Entonces, una mezcla de moteles reservados, muchos sándwiches y un poco de campamento. Empieza a sonar más manejable."],[2,"See? I told you we could pull it off. This is going to be legendary, I can feel it!","¿Ven? Les dije que podíamos lograrlo. ¡Esto va a ser legendario, lo presiento!"],[0,"Alright, Mr. Legendary. Let's rework this budget with the new plan and see where we land. I'm cautiously optimistic now.","De acuerdo, Sr. Legendario. Rehagamos este presupuesto con el nuevo plan y veamos cómo quedamos. Ahora soy cautelosamente optimista."],[1,"Perfect. Send over the updated spreadsheet when you can. I'm actually getting really excited for this!","Perfecto. Manda la hoja de cálculo actualizada cuando puedas. ¡La verdad es que ya me estoy emocionando mucho por esto!"],[2,"Me too! This is what it's all about. Road trip!","¡Yo también! De esto se trata todo. ¡Viaje por carretera!"]]},{"id":"vb2-25","nivel":"B2","emoji":"🎓","titulo":"The University Interview","tituloEs":"La entrevista de admisión","personas":[{"nombre":"Lucas","genero":"hombre","rol":"Solicitante"},{"nombre":"Amber","genero":"mujer","rol":"Entrevistadora"}],"lineas":[[1,"Hi Lucas, come on in. I'm Amber. It's great to finally meet you in person.","Hola Lucas, pasa. Soy Amber. Es un gusto conocerte finalmente en persona."],[0,"Hi Amber, thanks for having me. I've been looking forward to this, maybe a little nervously.","Hola Amber, gracias por recibirme. He estado esperando esto con ansias, quizás con un poco de nervios."],[1,"Oh, don't be! This is just a chat. I was really intrigued by your application essay, by the way.","¡Oh, no te preocupes! Esto es solo una charla. Por cierto, tu ensayo de postulación me intrigó mucho."],[0,"You were? I was worried it might be a bit... out there. Talking about the economics of vintage video games.","¿En serio? Me preocupaba que fuera un poco... excéntrico. Hablar de la economía de los videojuegos retro."],[1,"Not at all! It was refreshing. It tells me you think outside the box. So, what got you into that?","¡Para nada! Fue refrescante. Me dice que piensas de forma creativa. Y dime, ¿cómo te metiste en eso?"],[0,"Well, I started collecting them as a kid, and then I realized there's this whole complex market. It sort of blew my mind.","Bueno, empecé a coleccionarlos de niño y luego me di cuenta de que hay todo un mercado complejo. En cierto modo, me voló la cabeza."],[1,"I can see that. It's a unique intersection of history and economics. How do you see that fitting in with our business program?","Ya veo. Es una intersección única de historia y economía. ¿Cómo crees que eso encaja con nuestro programa de negocios?"],[0,"I think modern business can learn a lot from niche markets. They show how value is created beyond just utility.","Creo que los negocios modernos pueden aprender mucho de los mercados de nicho. Muestran cómo se crea valor más allá de la simple utilidad."],[1,"That's a fantastic point. I also saw you listed 'competitive napping' as a hobby... I have to ask about that.","Ese es un punto fantástico. También vi que pusiste 'siestas competitivas' como pasatiempo... tengo que preguntar sobre eso."],[0,"Oh, that! That was a bit of a joke for the activities section. I was hoping it would stand out.","¡Ah, eso! Fue una pequeña broma para la sección de actividades. Esperaba que destacara."],[1,"It definitely did! I appreciate the humor. It shows personality, which we love to see.","¡Definitivamente lo hizo! Aprecio el humor. Muestra personalidad, que es algo que nos encanta ver."],[0,"Phew, glad it landed well. I do take my studies seriously, though, despite my napping championship dreams.","Uf, qué bueno que funcionó. Sin embargo, sí me tomo mis estudios en serio, a pesar de mis sueños de ser campeón de siestas."],[1,"I have no doubt. You have an excellent academic record to back it up. We're looking for well-rounded students, not just robots.","No tengo duda. Tienes un excelente historial académico que lo respalda. Buscamos estudiantes integrales, no solo robots."],[0,"That's really great to hear. This university has been my top choice for a while now.","Es genial escuchar eso. Esta universidad ha sido mi primera opción desde hace tiempo."],[1,"Well, you've certainly made a strong impression, Lucas. We'll be in touch within the next few weeks with a decision. It was a pleasure.","Bueno, ciertamente has causado una fuerte impresión, Lucas. Nos pondremos en contacto en las próximas semanas con una decisión. Fue un placer."],[0,"The pleasure was all mine. Thanks again for your time, Amber.","El placer fue todo mío. Gracias de nuevo por tu tiempo, Amber."]]},{"id":"vb2-26","nivel":"B2","emoji":"📦","titulo":"A Roommate Is Moving Out","tituloEs":"Un compañero de piso se muda","personas":[{"nombre":"Wes","genero":"hombre","rol":"compañero de piso"},{"nombre":"Nicole","genero":"mujer","rol":"compañera de piso"}],"lineas":[[0,"Hey, Nicole, you got a sec? I have some news.","Oye, Nicole, ¿tienes un segundo? Tengo noticias."],[1,"Sure. You look kind of serious, what's going on?","Claro. Te ves algo serio, ¿qué pasa?"],[0,"It's nothing bad! Well, mostly. I just wanted to let you know I'm moving out.","¡No es nada malo! Bueno, en su mayor parte. Solo quería que supieras que me mudo."],[1,"Oh, wow. Really? That's sudden. Is everything okay?","Oh, vaya. ¿En serio? Qué repentino. ¿Está todo bien?"],[0,"Yeah, everything's great, actually. My girlfriend and I decided to pull the trigger and get a place together.","Sí, todo genial, de hecho. Mi novia y yo decidimos dar el paso y conseguir un apartamento juntos."],[1,"Shut up! That's amazing news! I'm so happy for you guys.","¡No me digas! ¡Esas son noticias increíbles! Me alegro mucho por ustedes."],[0,"Thanks. It all happened pretty fast. We're moving in at the end of next month.","Gracias. Todo pasó bastante rápido. Nos mudamos a finales del próximo mes."],[1,"Okay, good to know. I'm a little sad you're leaving, but this is a huge step! Congrats.","Ok, bueno saberlo. Estoy un poco triste de que te vayas, ¡pero este es un gran paso! Felicidades."],[0,"I appreciate that. I feel kind of bad leaving you to find a new roommate, though.","Te lo agradezco. Aunque me siento un poco mal por dejarte la tarea de encontrar un nuevo compañero."],[1,"Don't even worry about it. We'll find someone cool. It's the end of an era, though!","Ni te preocupes por eso. Encontraremos a alguien genial. ¡Aunque es el fin de una era!"],[0,"Tell me about it. We've been roommates for what, four years now?","Ni que lo digas. Hemos sido compañeros de piso por, ¿qué, cuatro años ya?"],[1,"Almost five! So... this is a bit forward, but what's the plan for your room? The one with the big closet.","¡Casi cinco! Oye... esto es un poco atrevido, pero ¿cuál es el plan para tu cuarto? El que tiene el clóset grande."],[0,"Haha, I knew you were going to ask that. I guess it's up for grabs!","Jaja, sabía que ibas a preguntar eso. ¡Supongo que está disponible!"],[1,"I'm calling dibs! Seriously though, we have to celebrate. A proper farewell dinner.","¡Me lo pido! Pero en serio, tenemos que celebrar. Una cena de despedida como se debe."],[0,"For sure. It's the least I can do. We'll plan something.","Por supuesto. Es lo menos que puedo hacer. Ya planearemos algo."]]},{"id":"vb2-27","nivel":"B2","emoji":"🎞️","titulo":"The Book vs. The Movie","tituloEs":"¿El libro o la película?","personas":[{"nombre":"Vanessa","genero":"mujer","rol":"Cinéfila y lectora"},{"nombre":"Victor","genero":"hombre","rol":"Defensor de las películas"},{"nombre":"Erin","genero":"mujer","rol":"Amante de los libros"}],"lineas":[[0,"Okay, so I just finished a book that was made into a movie, and I have to say, the book is always better.","Bueno, acabo de terminar un libro que hicieron película y debo decir que el libro siempre es mejor."],[1,"Oh, come on! I think that depends. Sometimes a movie brings the world to life in a way a book just can't.","¡Ay, por favor! Creo que eso depende. A veces una película le da vida al mundo de una forma que un libro simplemente no puede."],[2,"I get that, but you miss out on so much of the characters' internal thoughts. That's where all the depth is.","Entiendo eso, pero te pierdes muchos de los pensamientos internos de los personajes. Ahí es donde está toda la profundidad."],[0,"Exactly! And they always have to cut things out for time. It drives me crazy when my favorite subplot is gone.","¡Exacto! Y siempre tienen que cortar cosas por el tiempo. Me vuelve loca cuando mi trama secundaria favorita desaparece."],[1,"True, but who really has time for a 500-page book? A movie is a two-hour commitment, and it's more social.","Cierto, pero ¿quién tiene tiempo realmente para un libro de 500 páginas? Una película es un compromiso de dos horas, y es más social."],[2,"It's not about speed! Reading is about getting lost in another world. I'd rather spend a week there than just two hours.","¡No se trata de la velocidad! Leer se trata de perderse en otro mundo. Prefiero pasar una semana allí que solo dos horas."],[0,"And don't even get me started on when they change the ending. It can completely ruin the story's message.","Y ni me hagas empezar a hablar de cuando cambian el final. Puede arruinar por completo el mensaje de la historia."],[1,"Okay, I'll give you that one. But sometimes the movie actually improves on the book by fixing a slow plot.","Ok, te concedo esa. Pero a veces la película de hecho mejora el libro al arreglar una trama lenta."],[2,"Improves on it? That's blasphemy! The author's original vision is sacred, flaws and all.","¿Que lo mejora? ¡Eso es una blasfemia! La visión original del autor es sagrada, con todo y sus defectos."],[0,"Well, what about casting? I mean, sometimes the actor they choose is just perfect for the role.","Bueno, ¿y qué hay del casting? O sea, a veces el actor que eligen es simplemente perfecto para el papel."],[1,"Thank you! Seeing the characters come to life is the best part. It finally puts a face to the name.","¡Gracias! Ver a los personajes cobrar vida es la mejor parte. Finalmente le pone una cara al nombre."],[2,"I guess, but I'd rather use my imagination. The person I picture in my head is always better anyway.","Supongo, pero prefiero usar mi imaginación. La persona que imagino en mi cabeza siempre es mejor de todos modos."],[0,"Haha, you have a point there. My version of the hero was definitely more handsome.","Jaja, tienes razón en eso. Mi versión del héroe era definitivamente más guapo."],[1,"Alright, alright, you bookworms win this round. I'm still just gonna watch the sequel, though.","Está bien, está bien, ustedes, ratas de biblioteca, ganan esta ronda. Aunque yo igual solo voy a ver la secuela."],[2,"Your loss! You'll be missing out on all the best details.","¡Tú te lo pierdes! Te vas a estar perdiendo todos los mejores detalles."]]},{"id":"vb2-28","nivel":"B2","emoji":"⭐","titulo":"That One-Star Review","tituloEs":"Esa reseña de una estrella","personas":[{"nombre":"Jake","genero":"hombre","rol":"Co-dueño del restaurante"},{"nombre":"Lauren","genero":"mujer","rol":"Co-dueña del restaurante"},{"nombre":"Brooke","genero":"mujer","rol":"Chef principal"}],"lineas":[[0,"Did you guys see the new one-star review on Yelp? It's brutal. He said the chicken was 'aggressively bland'.","¿Vieron la nueva reseña de una estrella en Yelp? Es brutal. Dijo que el pollo estaba 'agresivamente soso'."],[1,"Oh, come on, Jake. One bad review out of hundreds of great ones isn't the end of the world.","Ay, vamos, Jake. Una mala reseña entre cientos de reseñas geniales no es el fin del mundo."],[2,"'Aggressively bland'? That's almost impressive. What does that even mean? Did the chicken personally offend him?","¿'Agresivamente soso'? Eso es casi impresionante. ¿Qué significa eso siquiera? ¿El pollo lo ofendió personalmente?"],[0,"I don't know, but it stings! We've been putting so much work into that new marinade.","¡No lo sé, pero duele! Hemos estado trabajando tanto en esa nueva marinada."],[1,"I know, but you can't please everyone. Some people are just looking for something to complain about.","Lo sé, pero no se puede complacer a todo el mundo. Algunas personas solo buscan algo de qué quejarse."],[2,"Totally. Maybe his taste buds were on vacation. I stand by that chicken; it's delicious.","Totalmente. Quizás sus papilas gustativas estaban de vacaciones. Yo defiendo ese pollo; está delicioso."],[0,"He also complained the service was slow. I guess that falls on me, we were short-staffed on Saturday.","También se quejó de que el servicio fue lento. Supongo que eso es mi culpa, teníamos poco personal el sábado."],[1,"It was an insane night. We can't beat ourselves up over it. We just have to keep an eye on staffing levels.","Fue una noche de locos. No podemos culparnos por ello. Solo tenemos que estar atentos a los niveles de personal."],[2,"Exactly. And for the record, my kitchen team was flying that night. We were pushing out dishes left and right.","Exacto. Y para que conste, mi equipo de cocina estaba volando esa noche. Estábamos sacando platos a diestra y siniestra."],[0,"I just hate that it's up there for everyone to see. It makes us look bad.","Es que odio que esté ahí para que todo el mundo lo vea. Nos hace quedar mal."],[1,"Or it makes him look like an outlier. Most people read a mix of reviews. Let's just draft a polite, professional response.","O lo hace parecer a él como un caso aislado. La mayoría de la gente lee una mezcla de reseñas. Simplemente redactemos una respuesta educada y profesional."],[2,"Yeah, something like, 'We're sorry our chicken wasn't aggressive enough for you. We'll try to be more passive-aggressive next time'.","Sí, algo como: 'Lamentamos que nuestro pollo no fuera lo suficientemente agresivo para usted. Intentaremos ser más pasivo-agresivos la próxima vez'."],[0,"Haha, okay, okay, maybe not *that*. But I have to admit, your version is way more fun.","Jaja, vale, vale, quizás no *eso*. Pero debo admitir que tu versión es mucho más divertida."],[1,"We'll write something nice, offer a gift card for them to come back, and just move on. It'll get buried in no time.","Escribiremos algo amable, ofreceremos una tarjeta de regalo para que vuelvan y simplemente seguiremos adelante. Quedará enterrada en nada de tiempo."],[2,"You got it. Now, who's up for trying my new 'aggressively flavorful' dessert prototype?","Entendido. Ahora, ¿quién se apunta a probar mi nuevo prototipo de postre 'agresivamente sabroso'?"],[0,"Fine, you've talked me down. But only if there's chocolate involved.","Bien, me has convencido. Pero solo si lleva chocolate."]]},{"id":"vb2-29","nivel":"B2","emoji":"✈️","titulo":"The Barcelona Job Offer","tituloEs":"La oferta de trabajo de Barcelona","personas":[{"nombre":"Emma","genero":"mujer","rol":"recibió la oferta"},{"nombre":"Lucas","genero":"hombre","rol":"su pareja"}],"lineas":[[0,"Hey, honey. You have a minute? I have some... pretty wild news to share.","Hola, cariño. ¿Tienes un minuto? Tengo una noticia... bastante increíble que contarte."],[1,"Sure. You look like you've seen a ghost. Everything okay?","Claro. Pareces como si hubieras visto un fantasma. ¿Todo bien?"],[0,"Better than okay! Remember that job I applied for in Barcelona? Well, they just offered me the position.","¡Mejor que bien! ¿Recuerdas ese trabajo al que apliqué en Barcelona? Pues, me acaban de ofrecer el puesto."],[1,"Get out of here! Seriously? That's incredible news, I'm so proud of you!","¡No me digas! ¿En serio? ¡Qué noticia increíble, estoy muy orgulloso de ti!"],[0,"Thanks! But... it is in Barcelona. As in, Spain. And it's a two-year contract to start.","¡Gracias! Pero... es en Barcelona. O sea, España. Y es un contrato de dos años para empezar."],[1,"Right. Wow. My brain is still catching up. I mean, Spain! That's... far.","Cierto. Vaya. Mi cerebro todavía está procesándolo. Digo, ¡España! Eso está... lejos."],[0,"I know it's a lot to process. The thing is, the opportunity is insane. It's a huge step up for my career.","Sé que es mucho que asimilar. El caso es que la oportunidad es una locura. Es un gran salto en mi carrera."],[1,"Of course it is, and you totally deserve it. I'm just trying to picture... us, in Spain.","Claro que lo es, y te lo mereces totalmente. Solo estoy tratando de imaginar... a nosotros, en España."],[0,"That's the thing... I wouldn't even think about accepting it unless you were open to the idea of coming with me.","Ese es el punto... Ni siquiera consideraría aceptarlo a menos que estuvieras abierto a la idea de venir conmigo."],[1,"Whoa, okay. Moving to Spain. My Spanish is basically limited to 'una cerveza, por favor'.","Vaya, okey. Mudarnos a España. Mi español se limita básicamente a 'una cerveza, por favor'."],[0,"That's a very useful start! We could take classes. Imagine the tapas, the weekend trips...","¡Es un comienzo muy útil! Podríamos tomar clases. Imagina las tapas, los viajes de fin de semana..."],[1,"You're definitely painting a nice picture. But what about my job? My whole life is here.","Definitivamente estás pintando un cuadro muy bonito. ¿Pero qué hay de mi trabajo? Toda mi vida está aquí."],[0,"I know, and I don't want to gloss over that. It's a massive decision, not just for me, but for us.","Lo sé, y no quiero restarle importancia a eso. Es una decisión enorme, no solo para mí, sino para nosotros."],[1,"Okay. Let's not panic. This is huge, but it's a good kind of huge. We just need to break it down.","De acuerdo. No entremos en pánico. Esto es enorme, pero es algo bueno. Solo tenemos que analizarlo por partes."],[0,"Exactly. How about we order some takeout and make a 'pros and cons' list, old-school style?","Exacto. ¿Qué tal si pedimos comida a domicilio y hacemos una lista de 'pros y contras', a la antigua?"],[1,"I like that plan. As long as 'endless tapas' is at the top of the 'pros' list.","Me gusta ese plan. Siempre y cuando 'tapas sin fin' esté al principio de la lista de 'pros'."]]},{"id":"vb2-30","nivel":"B2","emoji":"🔐","titulo":"Escape Room Challenge","tituloEs":"El Desafío del Escape Room","personas":[{"nombre":"Nate","genero":"hombre","rol":"compañero de equipo"},{"nombre":"Erin","genero":"mujer","rol":"compañera de equipo"},{"nombre":"Carlos","genero":"hombre","rol":"compañero de equipo"},{"nombre":"Brooke","genero":"mujer","rol":"compañera de equipo"}],"lineas":[[0,"Alright team, one hour on the clock. Where should we even start? This is a lot to take in.","Bueno equipo, una hora en el reloj. ¿Por dónde empezamos? Es bastante que procesar."],[1,"Okay, deep breaths. Let's not get overwhelmed. How about you and I check the desk, and Carlos and Brooke tackle that weird map?","Ok, respiremos hondo. No nos dejemos abrumar. ¿Qué tal si tú y yo revisamos el escritorio, y Carlos y Brooke se encargan de ese mapa raro?"],[2,"Sounds like a plan. This map has some strange symbols on it, and some pins in weird places.","Me parece un buen plan. Este mapa tiene unos símbolos extraños y algunos alfileres en lugares raros."],[3,"Wait, I recognize this symbol here! It looks just like the one on that locked box in the corner.","¡Esperen, reconozco este símbolo de aquí! Se ve idéntico al que está en esa caja con candado en la esquina."],[0,"We're not finding much over here, just a bunch of old papers and a locked drawer. No key in sight.","No estamos encontrando mucho por acá, solo un montón de papeles viejos y un cajón cerrado. Ni rastro de la llave."],[1,"Hold on, look at this letter opener. The handle has a specific shape. Does it match any of the symbols on the map?","Un momento, miren este abrecartas. El mango tiene una forma particular. ¿Coincide con alguno de los símbolos del mapa?"],[2,"Let me see... holy cow, it does! It's a perfect match for the symbol next to this pin.","A ver... ¡caramba, sí coincide! Es idéntico al símbolo que está junto a este alfiler."],[3,"So what does that mean? Are we supposed to press it or something?","Entonces, ¿qué significa eso? ¿Se supone que lo presionemos o algo así?"],[0,"Good thinking. Try pushing on that spot on the map gently.","Bien pensado. Intenta presionar suavemente en ese punto del mapa."],[2,"Okay, I'm pressing it and... I heard a click! The drawer on your desk just popped open, Nate!","Ok, estoy presionando y... ¡escuché un clic! ¡El cajón de tu escritorio se acaba de abrir, Nate!"],[1,"No way! You guys are brilliant. Talk about putting two and two together.","¡No puede ser! Ustedes son geniales. Eso sí que es atar cabos."],[3,"Yes! Teamwork! I was starting to get a little nervous we were stuck.","¡Sí! ¡Trabajo en equipo! Estaba empezando a ponerme un poco nerviosa de que nos hubiéramos atascado."],[0,"Awesome! Let's see what's inside. Okay... it's a key and a piece of paper with a riddle on it.","¡Genial! Veamos qué hay adentro. Ok... es una llave y un trozo de papel con un acertijo."],[1,"A riddle! Okay, read it out loud. We're on a roll now.","¡Un acertijo! Ok, léelo en voz alta. Ahora estamos en racha."],[2,"We might actually beat the record if we keep this up.","Podríamos incluso romper el récord si seguimos a este ritmo."]]}];
